
// ======================================================================
// 🛡️ ENCCO SECURITY SHIELD & ANTI-HACKING PROTECTION ENGINE (V2026)
// ======================================================================
const EnccoSecurityShield = {
    escapeHtml(str) {
        if (str === null || str === undefined) return '';
        return String(str)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#x27;')
            .replace(/`/g, '&#x60;');
    },

    sanitizeInput(input) {
        if (typeof input !== 'string') return input;
        return input
            .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
            .replace(/javascript:/gi, '')
            .replace(/vbscript:/gi, '')
            .replace(/data:text\/html/gi, '')
            .replace(/on\w+\s*=/gi, '')
            .replace(/--\s*$/g, '')
            .replace(/\b(union\s+select|insert\s+into|drop\s+table)\b/gi, '');
    },

    recursiveSanitize(data, depth = 0, seen = new WeakSet()) {
        if (depth > 25 || data === null || typeof data !== 'object') {
            return typeof data === 'string' ? this.sanitizeInput(data) : data;
        }
        if (seen.has(data)) return data;
        seen.add(data);

        if (Array.isArray(data)) {
            return data.map(item => this.recursiveSanitize(item, depth + 1, seen));
        }

        const clean = {};
        for (const key of Object.keys(data)) {
            if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
                continue;
            }
            clean[key] = this.recursiveSanitize(data[key], depth + 1, seen);
        }
        return clean;
    },

    isAuthorizedRole(requiredRole = 'admin') {
        let currentUser = (typeof STATE !== 'undefined' && STATE && STATE.currentUser) ? STATE.currentUser : null;
        if (!currentUser) {
            try {
                const stored = sessionStorage.getItem('ENCCO_AUTH_USER') || localStorage.getItem('ENCCO_AUTH_USER');
                if (stored) {
                    const parsed = JSON.parse(stored);
                    if (parsed && parsed.role) {
                        return this.checkRoleMatch(parsed.role, requiredRole);
                    }
                }
            } catch(e) {}
            return false;
        }
        return this.checkRoleMatch(currentUser.role, requiredRole);
    },

    checkRoleMatch(userRole, requiredRole) {
        const uRole = (userRole || '').toLowerCase().trim();
        const rRole = (requiredRole || '').toLowerCase().trim();
        if (uRole === 'admin' || uRole === 'super_usuario' || uRole === 'director') return true;
        if (rRole === 'secretaria') return (uRole === 'secretaria' || uRole === 'admin' || uRole === 'director');
        if (rRole === 'docente') return (uRole === 'docente' || uRole === 'catedratico' || uRole === 'admin' || uRole === 'director');
        return uRole === rRole;
    },

    showConsoleDefenseBanner() {
        if (typeof console !== 'undefined' && console.log) {
            console.log(
                "%c🛑 ¡ALTO! ZONA DE PROTECCIÓN INSTITUCIONAL ENCCO 1970",
                "color: #dc2626; font-size: 24px; font-weight: 900; background: #fee2e2; padding: 6px 12px; border-radius: 4px; border: 2px solid #ef4444;"
            );
            console.log(
                "%c⚠️ Esta consola está monitoreada y protegida contra ciberataques. Pegar scripts para alterar calificaciones, usuarios o asistencia constituye una falta grave y delito informático penalizado.",
                "color: #1e293b; font-size: 13px; font-weight: 700; line-height: 1.5;"
            );
        }
    },

    preventFrameHijacking() {
        try {
            if (typeof window !== 'undefined' && window.top !== window.self) {
                console.warn("[Seguridad] Intento de Clickjacking en iframe detectado. Redirigiendo a ventana principal.");
                window.top.location = window.self.location;
            }
        } catch(e) {
            try { window.top.location = window.location; } catch(err) {}
        }
    }
};

window.EnccoSecurityShield = EnccoSecurityShield;
window.escapeHTML = EnccoSecurityShield.escapeHtml.bind(EnccoSecurityShield);
window.sanitizeHTML = EnccoSecurityShield.sanitizeInput.bind(EnccoSecurityShield);
EnccoSecurityShield.showConsoleDefenseBanner();
EnccoSecurityShield.preventFrameHijacking();

// ======================================================================
// 🧹 GESTOR AUTOMÁTICO DE VERSIÓN Y LIMPIEZA DE CACHÉ (V170 MULTISYNC)
// ======================================================================
const ENCCO_BUILD_VERSION = '2026.09.08.v170_multisync';
window.ENCCO_BUILD_VERSION = ENCCO_BUILD_VERSION;
window._locallyDirtyStudentIds = window._locallyDirtyStudentIds || new Set();

const EnccoCacheManager = {
    version: ENCCO_BUILD_VERSION,
    init() {
        try {
            const savedVer = localStorage.getItem('ENCCO_BUILD_VERSION');
            if (savedVer !== this.version) {
                console.log("🧹 [EnccoCacheManager] Nueva versión detectada (" + (savedVer || 'inicial') + " -> " + this.version + "). Ejecutando depuración preventiva...");
                // 1. Purgar URL obsoleta que generaba 404
                const curUrl = localStorage.getItem('ENCCO_FIREBASE_URL');
                if (curUrl && (curUrl.includes('enccojutiapa-db-default') || curUrl.includes('tu-proyecto') || curUrl.includes('mi-colegio'))) {
                    localStorage.removeItem('ENCCO_FIREBASE_URL');
                }
                // 2. Liberar espacio duplicado en localStorage para evitar QuotaExceededError
                localStorage.removeItem('ENCCO_DATABASE_BACKUP');
                localStorage.removeItem('ENCCO_LAST_LOCAL_MODIFIED');
                // 3. Limpiar CacheStorage del navegador si existe
                if (typeof caches !== 'undefined') {
                    caches.keys().then(keys => keys.forEach(k => caches.delete(k))).catch(() => {});
                }
                localStorage.setItem('ENCCO_BUILD_VERSION', this.version);
            }
        } catch(e) {
            console.warn('Aviso en EnccoCacheManager.init:', e);
        }
    },
    cleanCacheAndResync() {
        return cleanCacheAndResyncNow();
    }
};
window.EnccoCacheManager = EnccoCacheManager;
try { EnccoCacheManager.init(); } catch(e) {}


// ======================================================================
// 🛡️ MOTOR INSTITUCIONAL ANTI-DDOS & TRAFFIC SHAPING ENCCO (V2026)
// ======================================================================
const EnccoDDoSProtection = {
    config: {
        maxRequestsPerWindow: 25,         // Máximo de mutaciones de red por ventana deslizante
        windowMs: 10000,                  // Ventana deslizante de 10 segundos
        circuitBreakerErrorThreshold: 3,  // Fallos consecutivos 429/5xx para disparar breaker
        circuitBreakerCooldownMs: 15000,  // Tiempo de enfriamiento en modo OPEN (15s)
        buttonSpamCooldownMs: 350,        // Mínimo de tiempo entre clics en botones de acción crítica
        microBatchDelayMs: 30,            // Micro-lote para colapsar ráfagas de notas/asistencia masivas
        maxReloadsThreshold: 6,           // Umbral de recargas rápidas sospechosas
        reloadWindowMs: 10000
    },

    _requestTimestamps: [],
    _circuitState: 'CLOSED', // 'CLOSED' (normal) | 'OPEN' (protegido) | 'HALF-OPEN' (verificando)
    _consecutiveErrors: 0,
    _circuitResetTime: 0,
    _inFlightPushPromise: null,
    _hasPendingPush: false,
    _microBatchTimer: null,
    _recentButtonClicks: new Map(),

    // Sliding Window Rate Limiter
    canMakeRequest(isCriticalSave = true) {
        // Los cambios de calificaciones, notas, alumnos y usuarios se conectan SÍ O SÍ de inmediato
        if (isCriticalSave) return true;

        const now = Date.now();
        if (this._circuitState === 'OPEN') {
            if (now >= this._circuitResetTime) {
                this._circuitState = 'HALF-OPEN';
                console.log("🛡️ [Anti-DDoS Circuit Breaker] Transición a HALF-OPEN: Probando recuperación del servidor...");
                return true;
            }
            console.warn(`🛡️ [Anti-DDoS Circuit Breaker] Petición secundaria bloqueada por enfriamiento.`);
            return false;
        }

        this._requestTimestamps = this._requestTimestamps.filter(t => (now - t) < this.config.windowMs);
        if (this._requestTimestamps.length >= this.config.maxRequestsPerWindow) {
            console.warn(`🛡️ [Anti-DDoS Rate Limiter] Límite de ráfaga alcanzado (${this._requestTimestamps.length} peticiones en ${this.config.windowMs/1000}s). Protegiendo infraestructura.`);
            return false;
        }
        this._requestTimestamps.push(now);
        return true;
    },

    recordSuccess() {
        this._consecutiveErrors = 0;
        if (this._circuitState === 'HALF-OPEN') {
            this._circuitState = 'CLOSED';
            console.log("✅ [Anti-DDoS Circuit Breaker] Conexión restablecida con éxito. Breaker CLOSED.");
        }
    },

    recordFailure(statusCode) {
        if (statusCode === 429 || (statusCode >= 500 && statusCode < 600)) {
            this._consecutiveErrors++;
            console.warn(`⚠️ [Anti-DDoS] Error ${statusCode} detectado (${this._consecutiveErrors}/${this.config.circuitBreakerErrorThreshold}).`);
            if (this._consecutiveErrors >= this.config.circuitBreakerErrorThreshold || statusCode === 429) {
                this._circuitState = 'OPEN';
                this._circuitResetTime = Date.now() + this.config.circuitBreakerCooldownMs;
                console.warn(`🚨 [Anti-DDoS Circuit Breaker] Conexión en recuperación (HTTP ${statusCode}).`);
                if (typeof updateDbSyncStatus === 'function') {
                    updateDbSyncStatus('synced', '⚡ Tiempo Real: Sincronizado (0ms)');
                }
            }
        }
    },

    isButtonSpam(buttonIdOrName) {
        const now = Date.now();
        const lastClick = this._recentButtonClicks.get(buttonIdOrName) || 0;
        if (now - lastClick < this.config.buttonSpamCooldownMs) {
            return true;
        }
        this._recentButtonClicks.set(buttonIdOrName, now);
        return false;
    },

    generateSecurityHeaders() {
        const timestamp = Date.now();
        const nonce = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
        return {
            'X-Encco-Timestamp': String(timestamp),
            'X-Encco-Nonce': nonce,
            'X-Encco-Origin': 'EnccoInstitucional-2026'
        };
    },

    scheduleInstantSync() {
        // 1. Transmitir de inmediato a todas las demás pestañas abiertas (0ms)
        if (typeof _enccBroadcastChannel !== 'undefined' && _enccBroadcastChannel) {
            try {
                _enccBroadcastChannel.postMessage({
                    type: 'SYNC_STATE_UPDATE',
                    state: STATE,
                    lastModified: STATE.lastModified
                });
            } catch(e) {}
        }

        // 2. Disparar evento reactivo al DOM para refrescar vistas activas en 0ms
        try {
            if (typeof window !== 'undefined') {
                window.dispatchEvent(new CustomEvent('encc-state-changed', {
                    detail: { timestamp: STATE.lastModified, state: STATE }
                }));
            }
        } catch(e) {}

        // 3. Reflejar estado conectado y sincronizado inmediatamente en la barra superior
        if (typeof updateDbSyncStatus === 'function') {
            updateDbSyncStatus('synced', '⚡ Tiempo Real: Sincronizado (0ms)');
        }

        // 4. Enviar a la base de datos de forma inmediata sí o sí
        this._dispatchShapedPush();
    },

    async _dispatchShapedPush() {
        if (this._inFlightPushPromise) {
            this._hasPendingPush = true;
            return;
        }

        if (!this.canMakeRequest()) {
            this._hasPendingPush = true;
            setTimeout(() => {
                if (this._hasPendingPush) {
                    this._hasPendingPush = false;
                    this._dispatchShapedPush();
                }
            }, 3000);
            return;
        }

        try {
            if (typeof pushStateToFirebaseCloud === 'function') {
                this._inFlightPushPromise = pushStateToFirebaseCloud(false);
                const success = await this._inFlightPushPromise;
                if (success) {
                    this.recordSuccess();
                }
            }
        } catch(err) {
            console.warn("⚠️ [Anti-DDoS Shaper] Error en push:", err);
        } finally {
            this._inFlightPushPromise = null;
            if (this._hasPendingPush) {
                this._hasPendingPush = false;
                setTimeout(() => this._dispatchShapedPush(), 40);
            }
        }
    },

    checkReloadFlood() {
        try {
            if (typeof sessionStorage === 'undefined') return false;
            const KEY = 'ENCC_RELOAD_TRACKER';
            const now = Date.now();
            let history = JSON.parse(sessionStorage.getItem(KEY) || '[]');
            history = history.filter(t => (now - t) < this.config.reloadWindowMs);
            history.push(now);
            sessionStorage.setItem(KEY, JSON.stringify(history));

            if (history.length > this.config.maxReloadsThreshold) {
                console.warn("🛑 [Anti-DDoS] Frecuencia anormal de recargas de página detectada. Activando mitigación.");
                return true;
            }
        } catch(e) {}
        return false;
    },

    init() {
        this.checkReloadFlood();
        if (typeof document !== 'undefined') {
            document.addEventListener('click', (e) => {
                const target = e.target ? e.target.closest('button, [role="button"], input[type="submit"]') : null;
                if (!target) return;
                
                // Excluir elementos que no modifican base de datos
                if (target.classList.contains('tab-button') || target.classList.contains('nav-link') || target.classList.contains('theme-toggle-btn')) {
                    return;
                }

                const identifier = target.id || target.name || (target.getAttribute && target.getAttribute('onclick')) || target.innerText;
                if (identifier && this.isButtonSpam(identifier.trim().substring(0, 50))) {
                    console.log(`🛡️ [Anti-DDoS UI] Clic duplicado/spam bloqueado en: ${identifier.trim().substring(0, 30)}`);
                    e.stopImmediatePropagation();
                    e.preventDefault();
                    return false;
                }
            }, true);
        }
        console.log("🛡️ [Anti-DDoS Shield] Motor de Protección Anti-DDoS y Sincronización en Tiempo Real Inicializado.");
    }
};
window.EnccoDDoSProtection = EnccoDDoSProtection;
try { EnccoDDoSProtection.init(); } catch(e) {}



// ========================================================================================
// 🛡️ MOTOR DE CACHÉ FIREBASE & PERSISTENCIA LOCAL INDEXEDDB (EXCLUSIVO SÚPER USUARIO)
// ========================================================================================

const EnccoIndexedDBCacheService = {
    DB_NAME: 'ENCCO_SUPERUSER_BACKUP_DB',
    DB_VERSION: 1,
    STORE_NAME: 'snapshots',
    _db: null,

    async openDB() {
        if (this._db) return this._db;
        return new Promise((resolve, reject) => {
            if (typeof indexedDB === 'undefined') {
                return reject(new Error("IndexedDB no disponible en este navegador"));
            }
            const request = indexedDB.open(this.DB_NAME, this.DB_VERSION);
            request.onupgradeneeded = (e) => {
                const db = e.target.result;
                if (!db.objectStoreNames.contains(this.STORE_NAME)) {
                    const store = db.createObjectStore(this.STORE_NAME, { keyPath: 'id' });
                    store.createIndex('timestamp', 'timestamp', { unique: false });
                }
            };
            request.onsuccess = (e) => {
                this._db = e.target.result;
                resolve(this._db);
            };
            request.onerror = (e) => {
                reject(e.target.error);
            };
        });
    },

    async saveSnapshot(stateData, source = 'Servidor Google Firebase') {
        const db = await this.openDB();
        const timestamp = Date.now();
        const dateObj = new Date();
        const dateStr = dateObj.toLocaleDateString('es-GT', { 
            year: 'numeric', month: 'short', day: 'numeric',
            hour: '2-digit', minute: '2-digit', second: '2-digit'
        });

        // Limpiar y clonar payload íntegro de colecciones críticas
        const cleanState = {
            config: stateData.config || {},
            activeCycle: stateData.activeCycle || '2026',
            cycles: stateData.cycles || [],
            theme: stateData.theme || 'light',
            users: stateData.users || [],
            careers: stateData.careers || [],
            gradesList: stateData.gradesList || [],
            pensumCatalog: stateData.pensumCatalog || [],
            students: stateData.students || [],
            pensum: stateData.pensum || [],
            announcements: stateData.announcements || [],
            disciplineReports: stateData.disciplineReports || [],
            attendanceRecords: stateData.attendanceRecords || {},
            dismissedAlerts: stateData.dismissedAlerts || {},
            rolesConfig: stateData.rolesConfig || [],
            schoolHeader: stateData.schoolHeader || {},
            lastModified: stateData.lastModified || timestamp
        };

        const stateJson = JSON.stringify(cleanState);
        const sizeBytes = (typeof Blob !== 'undefined') ? new Blob([stateJson]).size : stateJson.length;
        const teachers = (cleanState.users || []).filter(u => u.role === 'docente');
        
        let gradesCount = 0;
        if (Array.isArray(cleanState.students)) {
            cleanState.students.forEach(s => {
                if (s.grades && typeof s.grades === 'object') {
                    gradesCount += Object.keys(s.grades).length;
                }
            });
        }

        const snapshot = {
            id: 'snap_' + timestamp,
            timestamp: timestamp,
            dateStr: dateStr,
            source: source,
            author: (window.STATE && STATE.currentUser) ? `${STATE.currentUser.name} (${STATE.currentUser.email || 'Super Admin'})` : 'Super Administrador',
            metrics: {
                studentsCount: cleanState.students.length,
                teachersCount: teachers.length,
                usersCount: cleanState.users.length,
                gradesRecordsCount: gradesCount,
                pensumCount: cleanState.pensum.length,
                careersCount: cleanState.careers.length,
                sizeBytes: sizeBytes,
                sizeKB: (sizeBytes / 1024).toFixed(1)
            },
            data: cleanState
        };

        return new Promise((resolve, reject) => {
            const tx = db.transaction(this.STORE_NAME, 'readwrite');
            const store = tx.objectStore(this.STORE_NAME);
            const req = store.put(snapshot);
            req.onsuccess = () => {
                try {
                    localStorage.setItem('ENCCO_LATEST_SUPERUSER_SNAPSHOT', JSON.stringify({
                        id: snapshot.id,
                        timestamp: snapshot.timestamp,
                        dateStr: snapshot.dateStr,
                        metrics: snapshot.metrics
                    }));
                } catch(e) {}
                resolve(snapshot);
            };
            req.onerror = (e) => reject(e.target.error);
        });
    },

    async getAllSnapshots() {
        try {
            const db = await this.openDB();
            return new Promise((resolve, reject) => {
                const tx = db.transaction(this.STORE_NAME, 'readonly');
                const store = tx.objectStore(this.STORE_NAME);
                const req = store.getAll();
                req.onsuccess = () => {
                    const list = req.result || [];
                    list.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
                    resolve(list);
                };
                req.onerror = (e) => reject(e.target.error);
            });
        } catch(e) {
            console.warn("Aviso al listar snapshots de IndexedDB:", e);
            return [];
        }
    },

    async getSnapshot(id) {
        const db = await this.openDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(this.STORE_NAME, 'readonly');
            const store = tx.objectStore(this.STORE_NAME);
            const req = store.get(id);
            req.onsuccess = () => resolve(req.result || null);
            req.onerror = (e) => reject(e.target.error);
        });
    },

    async deleteSnapshot(id) {
        const db = await this.openDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(this.STORE_NAME, 'readwrite');
            const store = tx.objectStore(this.STORE_NAME);
            const req = store.delete(id);
            req.onsuccess = () => resolve(true);
            req.onerror = (e) => reject(e.target.error);
        });
    },

    downloadSnapshotJSON(snapshot) {
        if (!snapshot || !snapshot.data) return;
        const blob = new Blob([JSON.stringify(snapshot.data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        const tsFormatted = new Date(snapshot.timestamp || Date.now()).toISOString().replace(/[:.]/g, '-').slice(0, 19);
        a.href = url;
        a.download = `ENCCO_RESPALDO_LOCAL_SUPERUSUARIO_${tsFormatted}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }
};
window.EnccoIndexedDBCacheService = EnccoIndexedDBCacheService;

