function handleDirectGuideTeacherChange(gradeId, newTeacherId) {
    if (typeof canRoleModify === 'function' && !canRoleModify('guide-teachers', STATE.currentRole)) {
        showToast('Acceso Restringido: Su rol no tiene autorización para modificar o asignar Maestros Guías.', 'warning');
        return;
    }

    const grade = (STATE.gradesList || []).find(g => g.id === gradeId);
    if (!grade) return;
    const teacherObj = (STATE.users || []).find(u => u.id === newTeacherId);
    grade.guideTeacherId = newTeacherId || null;
    grade.guideTeacher = teacherObj ? teacherObj.name : (newTeacherId ? newTeacherId : 'Sin asignar');

    STATE.lastModified = Date.now();
    saveStateToLocalStorage();
    renderGuideTeachersView();
    if (typeof renderGradesTable === 'function') renderGradesTable();
    if (typeof renderDashboard === 'function') renderDashboard();

    if (typeof autoSyncToCloud === 'function') {
        autoSyncToCloud(true, false);
    } else if (typeof syncStateToFirebaseImmediate === 'function') {
        syncStateToFirebaseImmediate(false);
    }
    showToast(`Maestro(a) Guía "${grade.guideTeacher}" asignado exitosamente a ${grade.name} (${grade.section}).`, 'success');
}
window.handleDirectGuideTeacherChange = handleDirectGuideTeacherChange;

function printGuideTeachersOfficialDirectory() {
    const h = STATE.schoolHeader || (typeof getInitialData === 'function' ? getInitialData().schoolHeader : {});
    const cycle = STATE.activeCycle || '2026';
    const list = sortGrades(STATE.gradesList || []);

    // Filtros activos en la vista
    const careerFilterEl = document.getElementById('guideTeachersCareerFilter');
    const careerFilter = (careerFilterEl && careerFilterEl.value) ? careerFilterEl.value : 'ALL';
    const searchInput = document.getElementById('guideTeachersSearchInput');
    const searchVal = (searchInput && searchInput.value) ? searchInput.value.trim().toLowerCase() : '';

    let filteredList = list.filter(g => {
        if (careerFilter !== 'ALL' && g.career !== careerFilter) return false;
        if (searchVal) {
            const name = (g.name || '').toLowerCase();
            const sec = (g.section || '').toLowerCase();
            const code = (g.code || '').toLowerCase();
            const guide = (g.guideTeacher || '').toLowerCase();
            if (!name.includes(searchVal) && !sec.includes(searchVal) && !code.includes(searchVal) && !guide.includes(searchVal)) {
                return false;
            }
        }
        return true;
    });

    if (filteredList.length === 0) filteredList = list;

    const todayDate = new Date();
    const dateFormatted = todayDate.toLocaleDateString('es-GT', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    const capDate = dateFormatted.charAt(0).toUpperCase() + dateFormatted.slice(1);

    const baseUrl = window.location.href;
    let logoUrl = 'logo.png';
    try {
        if (typeof URL !== 'undefined' && window.location && window.location.href) {
            logoUrl = new URL('logo.png', window.location.href).href;
        }
    } catch (e) {
        logoUrl = 'logo.png';
    }

    let totalStudentsCount = 0;
    const rowsHtml = filteredList.map((g, idx) => {
        const count = typeof getStudentCountByGradeAndSection === 'function' ? getStudentCountByGradeAndSection(g.code, g.name, g.section) : 0;
        totalStudentsCount += count;
        const guideTeacherObj = (STATE.users || []).find(u => u.id === g.guideTeacherId || u.name === g.guideTeacher);
        const guideName = guideTeacherObj ? guideTeacherObj.name : (g.guideTeacher || 'Pendiente de asignación');
        const guideEmail = guideTeacherObj ? (guideTeacherObj.email || '---') : '---';
        const sectionClean = (g.section || '').replace(/Secci[oó]n\s*/i, '').trim() || g.section;

        return `
            <tr>
                <td style="text-align:center; font-weight:bold; padding:7px 5px; border:1px solid #000;">${idx + 1}</td>
                <td style="padding:7px 10px; border:1px solid #000; font-weight:bold;">${escapeHtml(g.name)}</td>
                <td style="text-align:center; padding:7px 5px; border:1px solid #000; font-weight:bold; font-size:11px;">${escapeHtml(sectionClean)}</td>
                <td style="padding:7px 10px; border:1px solid #000; font-weight:bold;">${escapeHtml(guideName)}</td>
                <td style="padding:7px 10px; border:1px solid #000; font-size:10px;">${escapeHtml(guideEmail)}</td>
                <td style="text-align:center; padding:7px 5px; border:1px solid #000; font-weight:bold; font-size:11px;">${count}</td>
            </tr>
        `;
    }).join('');

    const filterSubtitle = (careerFilter !== 'ALL')
        ? `<div style="font-size:10.5px; font-weight:bold; margin-top:2px; text-transform:uppercase;">CARRERA: ${escapeHtml(careerFilter)}</div>`
        : '';

    const printWin = window.open('', '_blank');
    if (!printWin) {
        showToast("Por favor permita las ventanas emergentes en su navegador para imprimir la lista.", "warning");
        return;
    }

    const htmlContent = `<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <base href="${escapeHtml(baseUrl)}">
    <title>Nómina Oficial de Docentes Guías - Ciclo ${escapeHtml(cycle)}</title>
    <style>
        @page {
            size: letter portrait;
            margin: 15mm 12mm 15mm 12mm;
        }
        * {
            box-sizing: border-box;
            -webkit-print-color-adjust: exact;
            print-color-adjust: exact;
        }
        body {
            font-family: Arial, Helvetica, sans-serif;
            font-size: 11px;
            color: #000;
            background: #fff;
            margin: 0;
            padding: 5px;
        }
        /* ENCABEZADO SIMPLE Y FORMAL CON LOGOTIPO */
        .header-table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 14px;
            border-bottom: 2px solid #000;
            padding-bottom: 8px;
        }
        .header-table td {
            vertical-align: middle;
        }
        .header-logo {
            width: 75px;
            text-align: center;
        }
        .header-logo img {
            max-height: 65px;
            max-width: 70px;
            display: block;
            margin: 0 auto;
        }
        .header-text {
            text-align: center;
            padding: 0 10px;
        }
        .line-mineduc {
            font-size: 9.5px;
            font-weight: bold;
            color: #333;
            letter-spacing: 0.5px;
            text-transform: uppercase;
        }
        .line-school {
            font-size: 15px;
            font-weight: 900;
            margin: 2px 0;
            color: #000;
            text-transform: uppercase;
        }
        .line-title {
            font-size: 12px;
            font-weight: bold;
            text-transform: uppercase;
            letter-spacing: 0.3px;
            margin-top: 2px;
        }
        .line-meta {
            font-size: 9px;
            color: #444;
            margin-top: 2px;
        }
        /* LISTA SIMPLE / TABLA SIN ADORNOS */
        .simple-table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 10px;
            font-size: 10.5px;
        }
        .simple-table th {
            background-color: #f2f2f2;
            border: 1px solid #000;
            padding: 7px 5px;
            font-size: 9.5px;
            font-weight: bold;
            text-transform: uppercase;
            text-align: center;
        }
        .simple-table td {
            border: 1px solid #000;
            vertical-align: middle;
        }
        .simple-table tfoot td {
            background-color: #f9f9f9;
            font-weight: bold;
            border: 1px solid #000;
            padding: 7px 10px;
        }
        .footer-note {
            margin-top: 20px;
            font-size: 8.5px;
            color: #555;
            text-align: right;
            border-top: 1px dashed #bbb;
            padding-top: 5px;
        }
        .print-btn-bar {
            text-align: right;
            margin-bottom: 10px;
        }
        .btn-print-now {
            background: #000;
            color: #fff;
            padding: 6px 14px;
            border: none;
            font-size: 11px;
            font-weight: bold;
            border-radius: 4px;
            cursor: pointer;
        }
        @media print {
            .print-btn-bar { display: none !important; }
            body { padding: 0 !important; }
        }
    </style>
</head>
<body>
    <div class="print-btn-bar">
        <button class="btn-print-now" onclick="window.print()">🖨️ Imprimir Documento</button>
    </div>

    <table class="header-table">
        <tr>
            <td class="header-logo">
                <img src="${escapeHtml(logoUrl)}" alt="Logo ENCCO" onerror="this.style.display='none'">
            </td>
            <td class="header-text">
                <div class="line-mineduc">MINISTERIO DE EDUCACIÓN &bull; DIRECCIÓN DEPARTAMENTAL DE EDUCACIÓN DE JUTIAPA</div>
                <div class="line-school">${escapeHtml(h.schoolName || 'ESCUELA NACIONAL DE CIENCIAS COMERCIALES')}</div>
                <div class="line-title">NÓMINA OFICIAL DE DOCENTES GUÍAS</div>
                ${filterSubtitle}
                <div class="line-meta">CICLO ESCOLAR ${escapeHtml(cycle)} &bull; JORNADA VESPERTINA &bull; CÓDIGO: ${escapeHtml(h.mineducCode || h.schoolCode || '22-01-0014-46')}</div>
            </td>
        </tr>
    </table>

    <table class="simple-table">
        <thead>
            <tr>
                <th style="width:35px;">No.</th>
                <th>Grado y Carrera</th>
                <th style="width:60px;">Sección</th>
                <th>Docente Guía Titular</th>
                <th>Correo Institucional</th>
                <th style="width:70px;">Alumnos</th>
            </tr>
        </thead>
        <tbody>
            ${rowsHtml}
        </tbody>
        <tfoot>
            <tr>
                <td colspan="5" style="text-align:right; font-weight:bold; text-transform:uppercase; padding-right:12px;">TOTAL GENERAL DE ALUMNOS EN SECCIONES:</td>
                <td style="text-align:center; font-weight:bold;">${totalStudentsCount}</td>
            </tr>
        </tfoot>
    </table>

    <div class="footer-note">
        Documento Oficial &bull; Fecha de emisión: ${escapeHtml(capDate)} &bull; ENCCO Jutiapa
    </div>
</body>
</html>`;

    printWin.document.open();
    printWin.document.write(htmlContent);
    printWin.document.close();

    const triggerPrint = () => {
        try {
            printWin.focus();
            printWin.print();
        } catch (e) {
            console.error("Error al imprimir nómina:", e);
        }
    };

    const imgEl = printWin.document.querySelector('img');
    if (imgEl) {
        if (imgEl.complete) {
            setTimeout(triggerPrint, 250);
        } else {
            imgEl.onload = () => setTimeout(triggerPrint, 200);
            imgEl.onerror = () => setTimeout(triggerPrint, 200);
            setTimeout(triggerPrint, 1000);
        }
    } else {
        setTimeout(triggerPrint, 300);
    }
}
window.printGuideTeachersOfficialDirectory = printGuideTeachersOfficialDirectory;

// Si cualquier enlace o botón llama a openGradesDirectoryModal, navega fluidamente a la lista completa (no flotante)
