// 🌟 HELPER UNIVERSAL DE ESTUDIANTES ACTIVOS / MATRICULADOS
function isStudentActive(s) {
    if (!s) return false;
    if (s.active === false) return false;
    if (s.status === 'Retirado' || s.status === 'Ausente' || s.status === 'Inactivo') return false;
    return true; // 'Activo', 'Inscrito', 'INSCRITO', o sin estatus explícito
}
window.isStudentActive = isStudentActive;

function getCleanSectionLetter(str) {
    if (!str) return '';
    const m = str.match(/Secci[oó]n\s*([A-D])/i) || str.match(/\b([A-D])\b/i);
    return m ? m[1].toUpperCase() : '';
}
window.getCleanSectionLetter = getCleanSectionLetter;

function getStudentAssignment(s) {
    if (!s) return { grade: 'Sin asignar', section: 'Sin sección', gradeCode: '', fullLabel: 'Sin grado asignado' };
    if (typeof s === 'string') {
        return { grade: s, section: 'Sección A', gradeCode: '', fullLabel: s };
    }
    let grade = (s.grade || '').trim();
    let section = (s.section || '').trim();
    let gradeCode = (s.gradeCode || '').trim();

    // 1. Si falta grado o sección, buscar correspondencia en los datos oficiales SIRE
    if ((!grade || !section || section === 'Sin sección') && typeof OFFICIAL_SIRE_412_STUDENTS !== 'undefined') {
        const off = OFFICIAL_SIRE_412_STUDENTS.find(o => 
            (o.carne && o.carne === s.carne) || 
            (o.personalCode && o.personalCode === s.personalCode) ||
            (o.cui && o.cui === s.cui) ||
            (o.id && o.id === s.id)
        );
        if (off) {
            if (!grade || grade === 'Sin grado') grade = off.grade;
            if (!section || section === 'Sin sección') section = off.section;
            if (!gradeCode) gradeCode = off.gradeCode;
        }
    }

    // 2. Extraer sección desde gradeCode o gradeLabel si no está definida
    if (!section && gradeCode) {
        const letter = getCleanSectionLetter(gradeCode);
        if (letter) section = `Sección ${letter}`;
    }
    if (!section && s.gradeLabel) {
        const letter = getCleanSectionLetter(s.gradeLabel);
        if (letter) section = `Sección ${letter}`;
    }
    if (!section && grade) {
        const letter = getCleanSectionLetter(grade);
        if (letter) section = `Sección ${letter}`;
    }
    if (section && !section.startsWith('Sección')) {
        section = `Sección ${section.toUpperCase()}`;
    }

    // 3. Limpiar nombre de grado (remover sufijos de sección si venían incrustados)
    let cleanGrade = grade;
    if (cleanGrade.includes(' - Sección')) cleanGrade = cleanGrade.split(' - Sección')[0].trim();
    else if (cleanGrade.includes(' (Sección')) cleanGrade = cleanGrade.split(' (Sección')[0].trim();
    else if (cleanGrade.includes(' Sección')) cleanGrade = cleanGrade.split(' Sección')[0].trim();
    
    if (!cleanGrade) cleanGrade = '4to Perito Contador';
    if (!section) section = 'Sección A';

    const fullLabel = `${cleanGrade} (${section})`;
    return { grade: cleanGrade, section, gradeCode, fullLabel };
}
window.getStudentAssignment = getStudentAssignment;

function formatStudentGradeAndSection(s) {
    if (!s) return 'Sin grado asignado';
    if (typeof s === 'string') return s;
    const assign = getStudentAssignment(s);
    return assign.fullLabel;
}
window.formatStudentGradeAndSection = formatStudentGradeAndSection;


function updateGradeSelects() {
    try {
        const gradeSelects = document.querySelectorAll('.grade-select, #studentGradeFilter, #studentFormGrade, #pensumSubjectGrade, #gradeFilterSelect, #attendanceGradeSelect, #reportsGradeSelect, #honorRollGradeSelect, #profGradeSelect');
        if (gradeSelects && gradeSelects.length > 0) {
            const grades = (STATE.gradesList && STATE.gradesList.length > 0) ? STATE.gradesList : [];
            gradeSelects.forEach(sel => {
                if (!sel) return;
                const currentVal = sel.value;
                const isProfileSel = (sel.id === 'profGradeSelect');
                let opts = isProfileSel ? '<option value="">-- Seleccione Grado y Sección --</option>' : '<option value="">Todos los Grados / Secciones</option>';
                grades.forEach(g => {
                    const val = g.name + ' - ' + g.section;
                    opts += `<option value="${val}" data-grade="${escapeHtml(g.name)}" data-section="${escapeHtml(g.section)}" data-code="${escapeHtml(g.code)}">${g.name} (${g.section})</option>`;
                });
                sel.innerHTML = opts;
                if (currentVal) sel.value = currentVal;
            });
        }
    } catch(e) {}
}
window.updateGradeSelects = updateGradeSelects;


function updateCareerSelects() {
    try {
        const careers = (STATE.careers && STATE.careers.length > 0) ? STATE.careers : [{ id: 'car-1', name: 'Perito Contador' }];
        const careerSelects = document.querySelectorAll('.career-select, #studentCareerFilterSelect, #studentCareerFilter, #guideTeachersCareerFilter, #studentFormCareer, #pensumSubjectCareer, #gradeFormCareer, #gradesCareerFilter, #pensumCareerFilterSelect, #careerFilterSelect');
        if (careerSelects && careerSelects.length > 0) {
            careerSelects.forEach(sel => {
                if (!sel) return;
                const currentVal = sel.value;
                const isCascadingFilter = (sel.id === 'studentCareerFilterSelect');
                const hasAllOption = sel.id && (sel.id.toLowerCase().includes('filter') || sel.id.toLowerCase().includes('search')) && !isCascadingFilter;
                
                let html = '';
                if (isCascadingFilter) {
                    html = '<option value="">-- Seleccione Carrera --</option>';
                } else if (hasAllOption) {
                    html = '<option value="ALL">Todas las Carreras</option>';
                }
                
                html += careers.map(c => `<option value="${c.name}">${c.name}</option>`).join('');
                sel.innerHTML = html;
                if (currentVal && (currentVal === 'ALL' || careers.some(c => c.name === currentVal))) {
                    sel.value = currentVal;
                }
            });
        }
    } catch(e) {}
}
window.updateCareerSelects = updateCareerSelects;


function generateTeacherPassword(name) {
    if (!name) return 'C@rolina1';
    const firstWord = name.replace(/^(PEM\.|Licda\.|Lic\.|Prof\.|Ing\.|MA\.)\s*/i, '').trim().split(' ')[0] || 'Docente';
    return firstWord.charAt(0).toUpperCase() + firstWord.slice(1).toLowerCase() + '1';
}
window.generateTeacherPassword = generateTeacherPassword;


function sortGrades(grades) {
    if (!Array.isArray(grades)) return [];
    return [...grades].sort((a, b) => (a.name || '').localeCompare(b.name || '') || (a.section || '').localeCompare(b.section || ''));
}
window.sortGrades = sortGrades;


// ======================================================================
//   MOTOR DE PERSISTENCIA Y RECUPERACIÓN MAESTRA DE BASE DE DATOS (V126)
// ======================================================================

var DB_STORAGE_KEY = 'ENCCO_DATABASE';
window.DB_STORAGE_KEY = DB_STORAGE_KEY;

function purgeOldDatabaseVersions() {
    try {
        if (typeof localStorage === 'undefined') return;

        let currentMaster = localStorage.getItem(DB_STORAGE_KEY);
        let bestCandidate = null;
        let bestTime = 0;

        if (currentMaster) {
            try {
                const parsed = JSON.parse(currentMaster);
                if (parsed && typeof parsed === 'object' && (parsed.students || parsed.users)) {
                    bestCandidate = currentMaster;
                    bestTime = parsed.lastModified || 1;
                }
            } catch(e) {}
        }

        const legacyKeysToDelete = [];

        for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (!k) continue;

            const isLegacy = (
                k !== DB_STORAGE_KEY &&
                k !== 'ENCCO_DATABASE_BACKUP' &&
                k !== 'ENCCO_LAST_LOCAL_MODIFIED' &&
                k !== 'ENCCO_AUTH_USER' &&
                k !== 'ENCCO_AUTH_ROLE' &&
                k !== 'ENCCO_AUTH_REMEMBER' &&
                k !== 'ENCCO_FIREBASE_URL' &&
                k !== 'ENCCO_FIREBASE_KEY' &&
                (
                    k.startsWith('ENCCO_SYSTEM_DATABASE_') ||
                    k.startsWith('ENCCO_STATE_BACKUP_') ||
                    k.startsWith('ENCCO_SYSTEM_DATA_') ||
                    k.startsWith('ENCCO_DATABASE_PROD_') ||
                    k.startsWith('ENCCO_DATABASE_BLANK_') ||
                    k.startsWith('ENCCO_DATABASE_SNAPSHOT') ||
                    k.startsWith('ENCCO_DB_') ||
                    k.includes('_BACKUP') ||
                    k.includes('_V')
                )
            );

            if (isLegacy) {
                legacyKeysToDelete.push(k);
                if (!currentMaster) {
                    try {
                        const raw = localStorage.getItem(k);
                        if (raw) {
                            const p = JSON.parse(raw);
                            if (p && typeof p === 'object' && (p.students || p.users)) {
                                const t = p.lastModified || 0;
                                if (t >= bestTime) {
                                    bestTime = t;
                                    bestCandidate = raw;
                                }
                            }
                        }
    } catch(e) {}
                }
            }
        }

        // Si no teníamos ENCCO_DATABASE y encontramos datos en alguna versión antigua, migrarlos
        if (!currentMaster && bestCandidate) {
            localStorage.setItem(DB_STORAGE_KEY, bestCandidate);
            currentMaster = bestCandidate;
        }

        // Eliminar definitivamente todas las versiones antiguas
        legacyKeysToDelete.forEach(k => {
            try {
                localStorage.removeItem(k);
            } catch(e) {}
        });

        if (legacyKeysToDelete.length > 0) {
            console.log(`🧹 [Base de Datos Única] Se purgaron ${legacyKeysToDelete.length} versiones anteriores obsoletas. Única base activa: ENCCO_DATABASE.`);
        }
    } catch(err) {
        console.warn("Aviso durante purga de versiones antiguas:", err);
    }
}
window.purgeOldDatabaseVersions = purgeOldDatabaseVersions;

function loadMasterDatabaseState() {
    // 1. Purgar versiones antiguas y consolidar todo en la base única ENCCO_DATABASE
    purgeOldDatabaseVersions();

    // 2. Recuperar el estado maestro permanente de la institución
    let saved = (typeof localStorage !== 'undefined') ? localStorage.getItem(DB_STORAGE_KEY) : null;

    // Respaldo redundante si DB_STORAGE_KEY no está disponible
    if (!saved && typeof localStorage !== 'undefined') {
        saved = localStorage.getItem('ENCCO_DATABASE_BACKUP');
        if (saved) {
            try {
                localStorage.setItem(DB_STORAGE_KEY, saved);
                console.log("🔄 [Recuperación Automática] Base restaurada desde ENCCO_DATABASE_BACKUP.");
            } catch(e) {}
        }
    }
    return saved;
}
window.loadMasterDatabaseState = loadMasterDatabaseState;

