function getOfficialBim1Details(student, subjectName) {
    if (!student || typeof OFFICIAL_BIM1_PATCH_MAP === 'undefined') return null;
    const cleanStr = s => (s || '').toLowerCase()
        .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-z0-9]/g, '');

    let record = null;
    if (student.id && OFFICIAL_BIM1_PATCH_MAP[student.id]) {
        record = OFFICIAL_BIM1_PATCH_MAP[student.id];
    } else if (student.personalCode && OFFICIAL_BIM1_PATCH_MAP[student.personalCode]) {
        record = OFFICIAL_BIM1_PATCH_MAP[student.personalCode];
    } else if (student.carne && OFFICIAL_BIM1_PATCH_MAP[student.carne]) {
        record = OFFICIAL_BIM1_PATCH_MAP[student.carne];
    } else {
        const c1 = cleanStr(student.name);
        const c2 = cleanStr(`${student.lastName || ''} ${student.firstName || ''}`);
        const c3 = cleanStr(`${student.firstName || ''} ${student.lastName || ''}`);
        record = OFFICIAL_BIM1_PATCH_MAP[c1] || OFFICIAL_BIM1_PATCH_MAP[c2] || OFFICIAL_BIM1_PATCH_MAP[c3];
    }

    if (record && record[subjectName]) {
        return record[subjectName];
    }
    return null;
}
window.getOfficialBim1Details = getOfficialBim1Details;

