//        UTILIDADES DE DEDUPLICACIÓN Y CONTROL DE ESTADO GLOBAL
// ======================================================================
function deduplicateUsersCollection(users) {
    if (!Array.isArray(users)) return [];
    const seenIds = new Set();
    const result = [];

    users.forEach(u => {
        if (!u || !u.id) return;
        if (seenIds.has(u.id)) return;
        seenIds.add(u.id);
        result.push(u);
    });

    return result;
}
window.deduplicateUsersCollection = deduplicateUsersCollection;

function deduplicateStudentsCollection(students) {
    if (!Array.isArray(students)) return [];
    const seen = new Set();
    const result = [];
    students.forEach(s => {
        if (!s) return;
        const key = (s.carne || s.personalCode || s.id || '').trim();
        const nameKey = ((s.firstName || '') + ' ' + (s.lastName || '') + '_' + (s.grade || '') + '_' + (s.section || '')).trim().toLowerCase();
        if (key && seen.has(key)) return;
        if (nameKey && seen.has(nameKey)) return;
        if (key) seen.add(key);
        if (nameKey) seen.add(nameKey);
        result.push(s);
    });
    return result;
}
window.deduplicateStudentsCollection = deduplicateStudentsCollection;

function deduplicateGradesCollection(grades) {
    if (!Array.isArray(grades)) return [];
    const seen = new Set();
    const result = [];
    grades.forEach(g => {
        if (!g || !g.name) return;
        const key = ((g.name || '') + '_' + (g.section || '')).trim().toLowerCase();
        if (seen.has(key) || (g.id && seen.has(g.id))) return;
        seen.add(key);
        if (g.id) seen.add(g.id);
        result.push(g);
    });
    return result;
}
window.deduplicateGradesCollection = deduplicateGradesCollection;

