function toggleMobileMenu() {
    const menu = document.getElementById('mobileNavMenu');
    const icon = document.getElementById('mobileMenuIcon');
    if (!menu) return;
    if (menu.classList.contains('active')) {
        menu.classList.remove('active');
        if (icon) icon.className = 'fa-solid fa-bars';
    } else {
        menu.classList.add('active');
        if (icon) icon.className = 'fa-solid fa-xmark';
    }
}

// ==========================================================================
// CONTROL DE VISTAS: PORTAL INFORMATIVO Y LOGIN DE LA PLATAFORMA
// ==========================================================================
function showPortalView(e) {
    if (e && typeof e.preventDefault === 'function') e.preventDefault();
    const portal = document.getElementById('portalSection');
    const gate = document.getElementById('mandatoryLoginGate');
    const app = document.getElementById('appMainLayout');
    const topBar = document.getElementById('topRoleBar');
    
    if (portal) portal.style.display = 'block';
    if (gate) {
        gate.classList.remove('active');
        gate.style.display = 'none';
    }
    if (app) app.style.display = 'none';
    if (topBar) topBar.style.display = 'none';
    
    if (window.location.hash === '#login') {
        history.pushState("", document.title, window.location.pathname + window.location.search);
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

function openPlatformLogin(e) {
    if (e && typeof e.preventDefault === 'function') e.preventDefault();
    const portal = document.getElementById('portalSection');
    const gate = document.getElementById('mandatoryLoginGate');
    const app = document.getElementById('appMainLayout');
    const topBar = document.getElementById('topRoleBar');
    
    if (portal) portal.style.display = 'none';
    if (app) app.style.display = 'none';
    if (topBar) topBar.style.display = 'none';
    if (gate) {
        gate.style.display = 'flex';
        gate.classList.add('active');
        const userInput = document.getElementById('gateUsername');
        if (userInput) userInput.focus();
    }
    window.location.hash = 'login';
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

function openPlatformLoginFromMobile(e) {
    if (e && typeof e.preventDefault === 'function') e.preventDefault();
    const menu = document.getElementById('mobileNavMenu');
    const icon = document.getElementById('mobileMenuIcon');
    if (menu) menu.classList.remove('active');
    if (icon) icon.className = 'fa-solid fa-bars';
    openPlatformLogin(e);
}

// Escuchar cambios de hash para navegación por enlaces directos
window.addEventListener('hashchange', function() {
    if (window.location.hash === '#login') {
        if (!STATE.isLoggedIn) openPlatformLogin();
    } else if (window.location.hash === '' || window.location.hash === '#inicio' || window.location.hash === '#portal') {
        if (!STATE.isLoggedIn) showPortalView();
    }
});



