function updateLoginAccountSelect() {
    const select = document.getElementById('quickLoginAccountSelect');
    if (!select) return;

    const currentSelected = select.value;
    const adminsAndStaff = STATE.users.filter(u => u.role === 'admin' || u.role === 'director' || u.role === 'secretaria');
    const teachers = STATE.users.filter(u => u.role === 'docente');

    let html = '';

    if (adminsAndStaff.length > 0) {
        html += `<optgroup label="🛡️ Dirección y Administración">`;
        adminsAndStaff.forEach(u => {
            const icon = u.role === 'admin' ? '🛡️' : (u.role === 'director' ? '👨‍💼' : '📋');
            html += `<option value="${u.id}">${icon} ${u.name} — ${u.title || u.role}</option>`;
        });
        html += `</optgroup>`;
    }

    if (teachers.length > 0) {
        html += `<optgroup label="👩‍🏫 Claustro de Catedráticos / Docentes (${teachers.length})">`;
        teachers.forEach(t => {
            html += `<option value="${t.id}">👩‍🏫 ${t.name} — ${t.title || 'Catedrático'}</option>`;
        });
        html += `</optgroup>`;
    }

    select.innerHTML = html;

    // Mantener la selección o seleccionar el primero
    if (currentSelected && STATE.users.some(u => u.id === currentSelected)) {
        select.value = currentSelected;
    } else if ((STATE.users || []).length > 0) {
        select.value = STATE.users[0].id;
        fillLoginCredentials(STATE.users[0].id);
    }
}

function fillLoginCredentials(userIdentifier) {
    const user = STATE.users.find(u => u.id === userIdentifier || u.email === userIdentifier || u.role === userIdentifier) || STATE.users[0];
    if (user) {
        document.getElementById('gateUsername').value = user.email;
        document.getElementById('gatePassword').value = ''; // Exige ingresar la clave obligatoria
    }
}

function togglePasswordVisibility(inputId) {
    const input = document.getElementById(inputId);
    const icon = document.getElementById('eyeIcon');
    if (!input) return;
    if (input.type === 'password') {
        input.type = 'text';
        if (icon) icon.className = 'fa-solid fa-eye-slash';
    } else {
        input.type = 'password';
        if (icon) icon.className = 'fa-solid fa-eye';
    }
}

