function deleteStudent(studentId) {
    if (!checkEnrolmentPermissions()) return;
    const student = (STATE.students || []).find(s => s.id === studentId);
    if (!student) return;

    if (confirm(`¿Está seguro de eliminar permanentemente al estudiante "${student.firstName} ${student.lastName}" (${student.carne})? Esta acción borrará expediente, notas y registros de disciplina.`)) {
        STATE.students = (STATE.students || []).filter(s => s.id !== studentId);
        
        // Limpiar reportes de disciplina del estudiante
        if (STATE.disciplineReports) {
            STATE.disciplineReports = STATE.disciplineReports.filter(d => d.studentId !== studentId);
        }

        saveStateToLocalStorage();
        renderStudentsTable();
        updateDashboardKPIs();
        updateUserAlertsUI();
        renderCurrentDashboardAlerts();
        renderTeacherGradeProgressTable();
        populateAttendanceSelects(false);
        showToast(`El estudiante "${student.firstName} ${student.lastName}" ha sido eliminado del sistema.`, "info");
    }
}

function calculateStudentAge(birthDateString = null) {
    const input = document.getElementById('studentFormBirthDate');
    const ageDisplay = document.getElementById('studentFormAge');
    const dateVal = birthDateString || (input ? input.value : '');
    if (!dateVal) {
        if (ageDisplay) ageDisplay.value = '';
        return '';
    }
    const birthDate = new Date(dateVal + 'T00:00:00');
    const today = new Date();
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
        age--;
    }
    const ageText = age >= 0 ? `${age} años` : '';
    if (ageDisplay) ageDisplay.value = ageText;
    return ageText;
}

