// CÁMARA WEBCAM INTERACTIVA
function startWebcam() {
    const container = document.getElementById('webcamContainer');
    const video = document.getElementById('webcamVideo');

    if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        navigator.mediaDevices.getUserMedia({ video: { width: 400, height: 400 } })
            .then(stream => {
                STATE.webcamStream = stream;
                video.srcObject = stream;
                container.style.display = 'block';
                showToast("Cámara activada. Apunte al alumno y capture la fotografía.", "info");
            })
            .catch(err => {
                showToast("No se pudo acceder a la cámara web. Puede subir una foto desde el dispositivo.", "warning");
            });
    } else {
        showToast("Su navegador o dispositivo no permite acceso directo a la cámara.", "danger");
    }
}

function captureWebcamPhoto() {
    const video = document.getElementById('webcamVideo');
    const canvas = document.getElementById('webcamCanvas');
    if (!video || !STATE.webcamStream) return;

    canvas.width = 320;
    canvas.height = 320;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0, 320, 320);

    const dataUrl = canvas.toDataURL('image/jpeg', 0.88);
    document.getElementById('studentFormPhotoPreview').src = dataUrl;
    
    stopWebcam();
    showToast("Fotografía del alumno tomada y guardada con éxito desde la cámara.", "success");
}

function stopWebcam() {
    const container = document.getElementById('webcamContainer');
    if (STATE.webcamStream) {
        STATE.webcamStream.getTracks().forEach(track => track.stop());
        STATE.webcamStream = null;
    }
    if (container) container.style.display = 'none';
}

function checkStudentDuplicateEnrollment(data, excludeId = null) {
    const { personalCode, cui, carne, firstName, lastName, birthDate, cycle } = data;
    const targetCycle = cycle || STATE.activeCycle;

    return (STATE.students || []).find(s => {
        if (excludeId && s.id === excludeId) return false;

        const studentCycle = s.cycle || STATE.activeCycle;
        if (targetCycle && studentCycle && targetCycle !== studentCycle) {
            return false;
        }

        // 1. Coincidencia por Código Personal MINEDUC
        if (personalCode && s.personalCode && s.personalCode.trim().toLowerCase() === personalCode.trim().toLowerCase()) {
            return true;
        }

        // 2. Coincidencia por CUI (sin espacios)
        if (cui && s.cui && s.cui.trim().replace(/\s+/g, '') === cui.trim().replace(/\s+/g, '')) {
            return true;
        }

        // 3. Coincidencia por Carné
        if (carne && s.carne && s.carne.trim().toLowerCase() === carne.trim().toLowerCase()) {
            return true;
        }

        // 4. Coincidencia por Nombres y Apellidos idénticos
        if (firstName && lastName && s.firstName && s.lastName) {
            const matchName = (s.firstName.trim().toLowerCase() === firstName.trim().toLowerCase()) &&
                              (s.lastName.trim().toLowerCase() === lastName.trim().toLowerCase());
            if (matchName) {
                if (!birthDate || !s.birthDate || s.birthDate === birthDate) {
                    return true;
                }
            }
        }

        return false;
    });
}

function validateStudentFormLiveDuplicate() {
    const studentId = document.getElementById('studentFormId')?.value;
    const carne = document.getElementById('studentFormCarne')?.value.trim();
    const personalCode = document.getElementById('studentFormPersonalCode')?.value.trim();
    const cui = document.getElementById('studentFormCui')?.value.trim();
    const firstName = document.getElementById('studentFormFirstName')?.value.trim();
    const lastName = document.getElementById('studentFormLastName')?.value.trim();
    const birthDate = document.getElementById('studentFormBirthDate')?.value;
    const cycle = document.getElementById('studentFormCycle')?.value || STATE.activeCycle;

    const warnBox = document.getElementById('studentDuplicateWarning');
    const warnText = document.getElementById('studentDuplicateWarningText');
    if (!warnBox || !warnText) return;

    if (!personalCode && !cui && !carne && (!firstName || !lastName)) {
        warnBox.style.display = 'none';
        return;
    }

    const duplicate = checkStudentDuplicateEnrollment({
        personalCode, cui, carne, firstName, lastName, birthDate, cycle
    }, studentId);

    if (duplicate) {
        const dupGrade = duplicate.gradeLabel || duplicate.grade || 'otro grado';
        const dupCycle = duplicate.cycle || STATE.activeCycle || 'ciclo actual';
        warnBox.style.display = 'block';
        warnText.textContent = `Aviso: El alumno "${duplicate.firstName} ${duplicate.lastName}" ya está inscrito en "${dupGrade}" (${dupCycle}).`;
    } else {
        warnBox.style.display = 'none';
    }
}

function saveStudentForm(e) {
    e.preventDefault();
    if (!checkEnrolmentPermissions()) return;

    const studentId = document.getElementById('studentFormId').value;
    const carne = document.getElementById('studentFormCarne').value.trim() || ('ENCCO-' + Date.now().toString().slice(-4));
    const personalCode = document.getElementById('studentFormPersonalCode').value.trim();
    const cui = document.getElementById('studentFormCui').value.trim();
    const firstName = document.getElementById('studentFormFirstName').value.trim();
    const lastName = document.getElementById('studentFormLastName').value.trim();
    const birthDate = document.getElementById('studentFormBirthDate').value;
    const age = calculateStudentAge(birthDate);
    const phone = document.getElementById('studentFormPhone').value.trim();
    const email = document.getElementById('studentFormEmail').value.trim();
    const address = document.getElementById('studentFormAddress').value.trim();
    const grade = document.getElementById('studentFormGrade').value;
    const cycle = document.getElementById('studentFormCycle').value || STATE.activeCycle;
    const shift = document.getElementById('studentFormShift').value;

    // Verificar si el estudiante ya está inscrito en otro grado para el mismo ciclo
    const duplicate = checkStudentDuplicateEnrollment({
        personalCode, cui, carne, firstName, lastName, birthDate, cycle
    }, studentId);

    if (duplicate) {
        const dupGrade = duplicate.gradeLabel || duplicate.grade || 'otro grado';
        const dupCycle = duplicate.cycle || STATE.activeCycle || 'el ciclo lectivo actual';
        showToast(`⚠️ No se puede duplicar la inscripción: El alumno "${duplicate.firstName} ${duplicate.lastName}" ya está inscrito en "${dupGrade}" (${dupCycle}).`, "danger");
        return;
    }

    // Encargado y padres
    const motherName = document.getElementById('studentFormMotherName').value.trim();
    const motherDpi = document.getElementById('studentFormMotherDpi').value.trim();
    const motherPhone1 = document.getElementById('studentFormMotherPhone1').value.trim();
    const motherPhone2 = document.getElementById('studentFormMotherPhone2').value.trim();

    const fatherName = document.getElementById('studentFormFatherName').value.trim();
    const fatherDpi = document.getElementById('studentFormFatherDpi').value.trim();
    const fatherPhone1 = document.getElementById('studentFormFatherPhone1').value.trim();
    const fatherPhone2 = document.getElementById('studentFormFatherPhone2').value.trim();

    const guardianName = document.getElementById('studentFormGuardianName').value.trim();
    const guardianDpi = document.getElementById('studentFormGuardianDpi').value.trim();
    const guardianPhone1 = document.getElementById('studentFormGuardianPhone1').value.trim();
    const guardianPhone2 = document.getElementById('studentFormGuardianPhone2').value.trim();

    // Tutor representativo para listas rápidas
    const primaryTutor = guardianName || motherName || fatherName || 'No registrado';
    const primaryPhone = guardianPhone1 || motherPhone1 || fatherPhone1 || phone || '';

    const photo = document.getElementById('studentFormPhotoPreview').src;

    const gradeSelectEl = document.getElementById('studentFormGrade');
    let selGrade = grade;
    let selSection = 'Sección A';
    let selCode = '';
    const selOpt = gradeSelectEl?.selectedOptions?.[0];
    if (selOpt && selOpt.dataset && selOpt.dataset.grade) {
        selGrade = selOpt.dataset.grade;
        selSection = selOpt.dataset.section || 'Sección A';
        selCode = selOpt.dataset.code || '';
    } else {
        const parts = (grade || '').split(' - ');
        if (parts.length >= 2) {
            selGrade = parts[0].trim();
            selSection = parts[1].trim();
        }
    }
    const cleanAssign = getStudentAssignment({ grade: selGrade, section: selSection, gradeCode: selCode });

    if (studentId) {
        const student = (STATE.students || []).find(s => 
            String(s.id) === String(studentId) || 
            (s.carne && carne && s.carne === carne) ||
            (s.personalCode && personalCode && s.personalCode === personalCode) ||
            (s.cui && cui && s.cui === cui)
        );
        if (student) {
            student.carne = carne;
            student.personalCode = personalCode;
            student.cui = cui;
            student.firstName = firstName;
            student.lastName = lastName;
            student.birthDate = birthDate;
            student.age = age;
            student.phone = phone;
            student.email = email;
            student.address = address;
            student.grade = cleanAssign.grade;
            student.section = cleanAssign.section;
            student.gradeCode = cleanAssign.gradeCode || selCode;
            student.gradeLabel = cleanAssign.fullLabel;
            student.cycle = cycle;
            student.shift = shift;
            student.photo = photo;

            student.motherName = motherName;
            student.motherDpi = motherDpi;
            student.motherPhone1 = motherPhone1;
            student.motherPhone2 = motherPhone2;

            student.fatherName = fatherName;
            student.fatherDpi = fatherDpi;
            student.fatherPhone1 = fatherPhone1;
            student.fatherPhone2 = fatherPhone2;

            student.guardianName = guardianName;
            student.guardianDpi = guardianDpi;
            student.guardianPhone1 = guardianPhone1;
            student.guardianPhone2 = guardianPhone2;

            student.tutor = primaryTutor;
            student.tutorPhone = primaryPhone;

            saveStateToLocalStorage();
            showToast('Estudiante guardado exitosamente.', 'success');
            closeStudentProfileModal();
            hideModalById('studentProfileModal');
            if (typeof renderStudentsTable === 'function') renderStudentsTable();
            if (typeof renderDashboard === 'function') renderDashboard();
        }
    } else {
        STATE.students.push({
            id: 'stu-' + Date.now(),
            carne,
            personalCode,
            cui,
            firstName,
            lastName,
            birthDate,
            age,
            phone,
            email,
            address,
            grade: cleanAssign.grade,
            section: cleanAssign.section,
            gradeCode: cleanAssign.gradeCode || selCode,
            gradeLabel: cleanAssign.fullLabel,
            cycle,
            shift,
            photo,
            motherName,
            motherDpi,
            motherPhone1,
            motherPhone2,
            fatherName,
            fatherDpi,
            fatherPhone1,
            fatherPhone2,
            guardianName,
            guardianDpi,
            guardianPhone1,
            guardianPhone2,
            tutor: primaryTutor,
            tutorPhone: primaryPhone,
            status: 'Activo',
            retireReason: '',
            retireRecipient: '',
            retireDate: '',
            grades: {}
        });
        saveStateToLocalStorage();
        showToast('Estudiante guardado exitosamente.', 'success');
        closeStudentProfileModal();
        hideModalById('studentProfileModal');
        if (typeof renderStudentsTable === 'function') renderStudentsTable();
        if (typeof renderDashboard === 'function') renderDashboard();
    }

    saveStateToLocalStorage();
    resetStudentEnrollmentForm(false);
    navigateTo('students');
}

function isSubjectBimestreExonerated(student, subjectName, bimestreNum) {
    if (!student || !student.academicExceptions || !Array.isArray(student.academicExceptions)) return false;
    const b = parseInt(bimestreNum) || 0;
    return student.academicExceptions.some(ex => {
        const matchSubject = (!ex.subject || ex.subject === 'ALL' || ex.subject.toLowerCase() === (subjectName || '').toLowerCase());
        const matchBimestre = (!ex.bimestre || ex.bimestre === 'ALL' || parseInt(ex.bimestre) === b);
        const isActive = (ex.type === 'EXONERADO' || ex.type === 'JUSTIFICADO');
        return matchSubject && matchBimestre && isActive;
    });
}

function getStudentAcademicInfo(student) {
    if (!student) {
        return {
            average: 0,
            totalPoints: 0,
            classCount: 9,
            gradedClasses: 0,
            gradeGroup: '4to',
            is6to: false,
            is5to: false,
            is4to: true,
            officialClassLoad: 9,
            classLoadLabel: '9 Clases (4to/5to)',
            hasFailedGrade: false,
            isExonerated: false,
            eligibleForHonorRoll: false,
            failedSubjectsList: [],
            exoneratedCount: 0
        };
    }

    const rawGrade = (student.grade || student.gradeLabel || '').toUpperCase();
    const is6to = rawGrade.includes('6') || rawGrade.includes('SEXTO') || rawGrade.includes('6TO');
    const is5to = !is6to && (rawGrade.includes('5') || rawGrade.includes('QUINTO') || rawGrade.includes('5TO'));
    const is4to = !is6to && !is5to;
    
    // Carga académica oficial: 4to y 5to tienen 9 clases oficiales; 6to tiene 10 clases oficiales
    const officialClassLoad = is6to ? 10 : 9;
    const classLoadLabel = is6to ? '10 Clases (6to)' : '9 Clases (4to/5to)';
    const activeBimestre = parseInt(STATE.config?.activeBimestre) || 1;

    let sumCourseAverages = 0;
    let totalAccumulatedPoints = 0;
    let gradedCount = 0;
    let hasFailedGrade = false;
    const failedSubjectsList = [];
    let exoneratedCount = 0;

    // Verificar si el estudiante está exonerado
    if (student.isExonerated === true || student.exonerated === true) {
        exoneratedCount++;
    }
    if (student.academicExceptions && Array.isArray(student.academicExceptions)) {
        exoneratedCount += student.academicExceptions.length;
    }

    const isStudentExonerated = (exoneratedCount > 0);

    // Revisar calificaciones ingresadas por los docentes
    if (student.grades && typeof student.grades === 'object') {
        const courseNames = Object.keys(student.grades);
        courseNames.forEach(cName => {
            const bGrades = student.grades[cName];
            if (Array.isArray(bGrades)) {
                let validCourseScores = [];
                for (let b = 1; b <= activeBimestre; b++) {
                    const score = parseInt(bGrades[b - 1]) || 0;
                    if (score > 0) {
                        if (score < 60) {
                            hasFailedGrade = true;
                            failedSubjectsList.push(`${cName} (${score} pts)`);
                        }
                        validCourseScores.push(score);
                    }
                }

                if (validCourseScores.length > 0) {
                    const courseAvg = validCourseScores.reduce((a, b) => a + b, 0) / validCourseScores.length;
                    sumCourseAverages += courseAvg;
                    totalAccumulatedPoints += courseAvg;
                    gradedCount++;
                }
            }
        });
    }

    // Revisar estructura moderna de gradebookDetails si existe
    if (student.gradebookDetails && typeof student.gradebookDetails === 'object') {
        const courses = Object.keys(student.gradebookDetails);
        courses.forEach(cName => {
            for (let b = 1; b <= activeBimestre; b++) {
                const bDetail = student.gradebookDetails[cName] && student.gradebookDetails[cName][b];
                if (bDetail) {
                    const totalScore = (parseInt(bDetail.zona) || 0) + (parseInt(bDetail.exam) || 0);
                    if (totalScore > 0) {
                        if (totalScore < 60) {
                            hasFailedGrade = true;
                            if (!failedSubjectsList.some(f => f.startsWith(cName))) {
                                failedSubjectsList.push(`${cName} (${totalScore} pts)`);
                            }
                        }
                    }
                }
            }
        });
    }

    // REGLAS ESTRICTAS DE CUADRO DE HONOR:
    // 1. Debe tener al menos una clase calificada (gradedCount > 0)
    // 2. NO debe tener ninguna clase perdida (hasFailedGrade === false)
    // 3. NO debe ser un alumno exonerado (isStudentExonerated === false)
    const isEligible = (gradedCount > 0) && (!hasFailedGrade) && (!isStudentExonerated);

    if (gradedCount > 0) {
        // Nivelación matemática exacta Base 100
        const balancedAvg = parseFloat((sumCourseAverages / gradedCount).toFixed(2));
        const totalPointsCalc = Math.round(sumCourseAverages);

        return {
            average: balancedAvg,
            totalPoints: totalPointsCalc,
            classCount: officialClassLoad,
            gradedClasses: gradedCount,
            gradeGroup: is6to ? '6to' : (is5to ? '5to' : '4to'),
            is6to: is6to,
            is5to: is5to,
            is4to: is4to,
            officialClassLoad: officialClassLoad,
            classLoadLabel: classLoadLabel,
            hasFailedGrade: hasFailedGrade,
            isExonerated: isStudentExonerated,
            eligibleForHonorRoll: isEligible,
            failedSubjectsList: failedSubjectsList,
            exoneratedCount: exoneratedCount
        };
    }

    // Si AÚN NO hay calificaciones ingresadas, todo permanece en 0 real (limpio)
    return {
        average: 0,
        totalPoints: 0,
        classCount: officialClassLoad,
        gradedClasses: 0,
        gradeGroup: is6to ? '6to' : (is5to ? '5to' : '4to'),
        is6to: is6to,
        is5to: is5to,
        is4to: is4to,
        officialClassLoad: officialClassLoad,
        classLoadLabel: classLoadLabel,
        hasFailedGrade: false,
        isExonerated: isStudentExonerated,
        eligibleForHonorRoll: false,
        failedSubjectsList: [],
        exoneratedCount: exoneratedCount
    };
}


function openAcademicExonerationModal(studentId) {
    const student = STATE.students.find(s => s.id === studentId);
    if (!student) {
        showToast("No se encontró el expediente del estudiante.", "warning");
        return;
    }

    STATE.exonerationStudentId = studentId;

    const nameEl = document.getElementById('exonModalStudentName');
    const metaEl = document.getElementById('exonModalStudentMeta');
    const badgeEl = document.getElementById('exonModalStatusBadge');
    const subjSelect = document.getElementById('exonFormSubject');

    if (nameEl) nameEl.textContent = `Estudiante: ${student.firstName} ${student.lastName}`;
    if (metaEl) metaEl.textContent = `Carné: ${student.carne || '—'} | Cód. Personal: ${student.personalCode || '—'} | Grado y Sección: ${formatStudentGradeAndSection(student)}`;

    const exceptions = student.academicExceptions || [];
    if (badgeEl) {
        if (exceptions.length > 0) {
            badgeEl.textContent = `${exceptions.length} Consideración(es) Activa(s)`;
            badgeEl.style.background = '#fef3c7';
            badgeEl.style.color = '#92400e';
        } else {
            badgeEl.textContent = 'Sin Exoneraciones';
            badgeEl.style.background = '#ccfbf1';
            badgeEl.style.color = '#115e59';
        }
    }

    // Poblar selector de materias con las materias del pensum del grado del estudiante
    if (subjSelect) {
        let opts = `<option value="ALL">🌟 Todas las Asignaturas (Bimestre Completo)</option>`;
        const courseNames = student.grades ? Object.keys(student.grades) : [];
        if (courseNames.length > 0) {
            courseNames.forEach(cn => {
                opts += `<option value="${escapeHtml(cn)}">📚 ${escapeHtml(cn)}</option>`;
            });
        } else {
            // Asignaturas por defecto del pensum
            (STATE.pensum || []).filter(p => p.gradeCode === student.grade || p.grade === student.grade).forEach(p => {
                opts += `<option value="${escapeHtml(p.subject)}">📚 ${escapeHtml(p.subject)}</option>`;
            });
        }
        subjSelect.innerHTML = opts;
    }

    renderAcademicExonerationsList(student);

    showModalById('academicExonerationModal');
}

function closeAcademicExonerationModal() {
    const modal = document.getElementById('academicExonerationModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

function renderAcademicExonerationsList(student) {
    const container = document.getElementById('exonListContainer');
    if (!container) return;

    const list = student.academicExceptions || [];
    if (list.length === 0) {
        container.innerHTML = `
            <div style="text-align:center; padding:18px; background:#f8fafc; border:1px dashed #cbd5e1; border-radius:6px; color:#64748b; font-size:0.84rem;">
                <i class="fa-solid fa-circle-check" style="color:#10b981; font-size:1.2rem; margin-bottom:4px; display:block;"></i>
                El estudiante cursa todas sus asignaturas de forma regular sin exoneraciones ni justificaciones especiales.
            </div>
        `;
        return;
    }

    container.innerHTML = list.map((ex, idx) => {
        const bimLabel = ex.bimestre === 'ALL' ? 'Todo el Ciclo' : `Bimestre ${ex.bimestre}`;
        const subLabel = ex.subject === 'ALL' ? 'Todas las Asignaturas' : ex.subject;
        const typeLabel = ex.type === 'EXONERADO' ? 'Exoneración Oficial' : 'Justificación de Fuerza Mayor';

        return `
            <div style="background:#ffffff; border:1px solid #cbd5e1; border-left:4px solid #0d9488; border-radius:4px; padding:10px 14px; display:flex; justify-content:space-between; align-items:center; gap:10px;">
                <div>
                    <div style="display:flex; align-items:center; gap:8px;">
                        <strong style="color:#0f766e; font-size:0.9rem;">${escapeHtml(subLabel)}</strong>
                        <span class="badge badge-primary" style="font-size:0.75rem;">${bimLabel}</span>
                        <span class="badge badge-success" style="font-size:0.75rem;">${typeLabel}</span>
                    </div>
                    <div style="font-size:0.8rem; color:#475569; margin-top:3px;">
                        <strong>Motivo:</strong> ${escapeHtml(ex.reason || 'Sin justificación registrada')} | <small style="color:#64748b;">${ex.date || ''}</small>
                    </div>
                </div>
                <button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteAcademicExoneration('${student.id}', ${idx})" title="Eliminar exoneración">
                    <i class="fa-solid fa-trash"></i>
                </button>
            </div>
        `;
    }).join('');
}

function saveAcademicExoneration(e) {
    if (e) e.preventDefault();
    const studentId = STATE.exonerationStudentId;
    const student = STATE.students.find(s => s.id === studentId);
    if (!student) return;

    const subject = document.getElementById('exonFormSubject')?.value || 'ALL';
    const bimestre = document.getElementById('exonFormBimestre')?.value || '2';
    const type = document.getElementById('exonFormType')?.value || 'EXONERADO';
    const reason = document.getElementById('exonFormReason')?.value || '';

    if (!student.academicExceptions) student.academicExceptions = [];

    student.academicExceptions.push({
        id: `exon-${Date.now()}`,
        subject: subject,
        bimestre: bimestre,
        type: type,
        reason: reason.trim(),
        date: new Date().toLocaleDateString('es-GT'),
        authorizedBy: STATE.currentUser ? STATE.currentUser.name : 'Dirección / Secretaría ENCCO'
    });

    saveStateToLocalStorage();
    renderAcademicExonerationsList(student);
    loadHonorRoll();

    const form = document.getElementById('academicExonerationForm');
    if (form) form.reset();

    showToast("¡Consideración individual / exoneración aplicada correctamente!", "success");
}

function deleteAcademicExoneration(studentId, exIndex) {
    const student = STATE.students.find(s => s.id === studentId);
    if (!student || !student.academicExceptions) return;

    if (!confirm("¿Desea eliminar esta exoneración? La nota regular volverá a ser evaluada en el Cuadro de Honor.")) {
        return;
    }

    student.academicExceptions.splice(exIndex, 1);
    saveStateToLocalStorage();
    renderAcademicExonerationsList(student);
    loadHonorRoll();
    showToast("Exoneración eliminada del expediente del alumno.", "info");
}

function calculateStudentAvg(student) {
    const info = getStudentAcademicInfo(student);
    return info.average;
}

function switchStudentProfileTab(tabKey) {
    document.querySelectorAll('.profile-tab-btn').forEach(btn => btn.classList.remove('active'));
    document.querySelectorAll('.profile-tab-content').forEach(content => {
        content.classList.remove('active');
        content.style.display = 'none';
    });

    const activeBtn = document.getElementById(`profTabBtn-${tabKey}`);
    const activeContent = document.getElementById(`profTab-${tabKey}`);
    if (activeBtn) activeBtn.classList.add('active');
    if (activeContent) {
        activeContent.classList.add('active');
        activeContent.style.display = 'block';
    }
}

function openStudentProfileModal(id) {
    const student = STATE.students.find(s => s.id === id);
    if (!student) return;

    STATE.selectedStudentId = id;
    const isDocente = (STATE.currentRole === 'docente');
    const canEdit = (STATE.currentRole === 'admin' || STATE.currentRole === 'director' || STATE.currentRole === 'secretaria');

    // 1. Cabecera del Perfil
    const photoImg = document.getElementById('profilePhotoImg');
    if (photoImg) photoImg.src = student.photo || 'https://ui-avatars.com/api/?name=' + student.firstName;
    
    const nameDisp = document.getElementById('profNameDisplay');
    if (nameDisp) nameDisp.textContent = `${student.firstName} ${student.lastName}`;

    const carneDisp = document.getElementById('profCarneDisplay');
    if (carneDisp) carneDisp.textContent = `Carné: ${student.carne} | Cód. Personal: ${student.personalCode || 'No registrado'} | CUI: ${student.cui || 'No registrado'} | Ciclo: ${student.cycle || STATE.activeCycle || '2026'}`;

    const statusBadge = document.getElementById('profStatusBadge');
    if (statusBadge) {
        statusBadge.className = student.status === 'Activo' ? 'badge badge-success' : 'badge badge-danger';
        statusBadge.textContent = student.status || 'Activo';
    }

    const careerBadge = document.getElementById('profCareerBadge');
    if (careerBadge) careerBadge.textContent = student.career || 'Perito Contador';

    const assign = getStudentAssignment(student);
    const gradeBadge = document.getElementById('profGradeDisplayBadge');
    if (gradeBadge) {
        gradeBadge.innerHTML = `<i class="fa-solid fa-graduation-cap"></i> ${escapeHtml(assign.grade)} &nbsp;|&nbsp; <i class="fa-solid fa-users-rectangle"></i> ${escapeHtml(assign.section)}`;
        gradeBadge.style.background = '#e0f2fe';
        gradeBadge.style.color = '#0369a1';
        gradeBadge.style.border = '1px solid #bae6fd';
        gradeBadge.style.fontWeight = '800';
        gradeBadge.title = `Estudiante asignado a: ${assign.fullLabel}`;
    }

    // Actualizar banner de asignación académica oficial en Pestaña 1
    const titleEl = document.getElementById('profAssignedGradeTitle');
    if (titleEl) titleEl.textContent = `${assign.grade} — ${assign.section}`;
    const guideEl = document.getElementById('profAssignedGuideTeacher');
    if (guideEl) {
        const grd = (STATE.gradesList || []).find(g => 
            (g.name === assign.grade && (!assign.section || g.section === assign.section)) ||
            (assign.gradeCode && g.code === assign.gradeCode)
        );
        const teacher = grd && grd.guideTeacher ? grd.guideTeacher : 'Dirección del Plantel / Secretaría';
        guideEl.innerHTML = `👨‍🏫 <strong>Maestro(a) Guía:</strong> ${escapeHtml(teacher)}`;
    }

    // 2. Llenar campos de Pestaña 1 (Ficha de Datos)
    const statusSel = document.getElementById('profStatusSelect');
    if (statusSel) {
        statusSel.value = student.status || 'Activo';
        statusSel.disabled = !canEdit;
    }

    const gradeSel = document.getElementById('profGradeSelect');
    if (gradeSel) {
        const grades = (STATE.gradesList && STATE.gradesList.length > 0) ? STATE.gradesList : [];
        let opts = '<option value="">-- Seleccione Grado y Sección --</option>';
        grades.forEach(g => {
            const val = `${g.name} - ${g.section}`;
            opts += `<option value="${val}" data-grade="${escapeHtml(g.name)}" data-section="${escapeHtml(g.section)}" data-code="${escapeHtml(g.code)}">${g.name} (${g.section})</option>`;
        });
        gradeSel.innerHTML = opts;

        const targetVal = `${assign.grade} - ${assign.section}`;
        const matchOpt = Array.from(gradeSel.options).find(o => 
            o.value === targetVal || 
            (o.dataset.grade === assign.grade && o.dataset.section === assign.section) ||
            (assign.gradeCode && o.dataset.code === assign.gradeCode) ||
            (o.text && o.text.includes(assign.grade) && o.text.includes(assign.section))
        );
        if (matchOpt) {
            gradeSel.value = matchOpt.value;
        } else {
            const newOpt = document.createElement('option');
            newOpt.value = targetVal;
            newOpt.textContent = assign.fullLabel;
            gradeSel.appendChild(newOpt);
            gradeSel.value = targetVal;
        }
        gradeSel.disabled = !canEdit;
    }
    
    const birthStr = student.birthDate ? `${student.birthDate} (${student.age || calculateStudentAge(student.birthDate)})` : 'No registrada';
    const birthDisp = document.getElementById('profBirthDateDisplay');
    if (birthDisp) birthDisp.value = birthStr;

    const addrDisp = document.getElementById('profAddressDisplay');
    if (addrDisp) {
        addrDisp.value = student.address || '';
        addrDisp.readOnly = !canEdit;
    }

    const phoneDisp = document.getElementById('profPhone');
    if (phoneDisp) {
        phoneDisp.value = student.phone || '';
        phoneDisp.readOnly = !canEdit;
    }

    const emailDisp = document.getElementById('profEmail');
    if (emailDisp) {
        emailDisp.value = student.email || '';
        emailDisp.readOnly = !canEdit;
    }

    // Datos familiares estructurados
    const familyBox = document.getElementById('profFamilyDetailsBox');
    if (familyBox) {
        const momInfo = student.motherName ? `👩 <strong>Madre:</strong> ${student.motherName} (DPI: ${student.motherDpi || 'N/A'}) - Tel: <strong>${student.motherPhone1 || 'Sin teléfono'}</strong> ${student.motherPhone2 ? ' / ' + student.motherPhone2 : ''}` : '👩 <strong>Madre:</strong> No registrada';
        const dadInfo = student.fatherName ? `👨 <strong>Padre:</strong> ${student.fatherName} (DPI: ${student.fatherDpi || 'N/A'}) - Tel: <strong>${student.fatherPhone1 || 'Sin teléfono'}</strong> ${student.fatherPhone2 ? ' / ' + student.fatherPhone2 : ''}` : '👨 <strong>Padre:</strong> No registrado';
        const guardianInfo = student.guardianName ? `🛡️ <strong>Encargado / Tutor:</strong> ${student.guardianName} (DPI: ${student.guardianDpi || 'N/A'}) - Tel: <strong>${student.guardianPhone1 || 'Sin teléfono'}</strong> ${student.guardianPhone2 ? ' / ' + student.guardianPhone2 : ''}` : `🛡️ <strong>Encargado:</strong> ${student.tutor || 'No registrado'}`;
        
        familyBox.innerHTML = `
            <div style="margin-bottom:4px;">${momInfo}</div>
            <div style="margin-bottom:4px;">${dadInfo}</div>
            <div>${guardianInfo}</div>
        `;
    }

    toggleInactivationFields(student.status);
    const retReason = document.getElementById('profRetireReason');
    if (retReason) {
        retReason.value = student.retireReason || '';
        retReason.readOnly = !canEdit;
    }
    const retRecip = document.getElementById('profRetireRecipient');
    if (retRecip) {
        retRecip.value = student.retireRecipient || '';
        retRecip.readOnly = !canEdit;
    }
    const retDate = document.getElementById('profRetireDate');
    if (retDate) {
        retDate.value = student.retireDate || '';
        retDate.readOnly = !canEdit;
    }

    // 3. Pestaña 2: Reportes Disciplinarios
    const discList = (STATE.disciplineReports || []).filter(d => d.studentId === id);
    const countBadge = document.getElementById('profDisciplineCount');
    if (countBadge) countBadge.textContent = discList.length;

    const discBox = document.getElementById('studentDisciplineHistory');
    if (discBox) {
        if (discList.length === 0) {
            discBox.innerHTML = `
                <div style="text-align:center; padding:20px; color:var(--text-muted);">
                    <i class="fa-solid fa-circle-check" style="color:var(--brand-green); font-size:1.8rem; margin-bottom:6px; display:block;"></i>
                    <strong style="color:var(--text-primary);">Expediente Disciplinario Impecable</strong>
                    <p style="margin:4px 0 0 0; font-size:0.82rem;">El estudiante no cuenta con llamadas de atención ni reportes de conducta registrados.</p>
                </div>
            `;
        } else {
            discBox.innerHTML = discList.map((d, index) => {
                const isGrav = d.severity === 'Grave' || d.severity === 'Muy Grave';
                return `
                    <div style="margin-bottom:8px; border:1px solid #e2e8f0; background:#ffffff; border-radius:6px; padding:10px 12px; box-shadow:0 1px 2px rgba(0,0,0,0.03);">
                        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
                            <span class="badge ${isGrav ? 'badge-danger' : 'badge-warning'}" style="font-weight:700;">
                                <i class="fa-solid fa-triangle-exclamation"></i> ${d.severity || 'Falta Leve'}
                            </span>
                            <span style="font-size:0.78rem; color:var(--text-muted); font-weight:600;"><i class="fa-regular fa-clock"></i> ${d.date}</span>
                        </div>
                        <div style="font-weight:700; color:#1e293b; font-size:0.88rem; margin-bottom:2px;">${d.reason}</div>
                        ${d.notes ? `<div style="font-size:0.82rem; color:var(--text-secondary); margin-bottom:4px; font-style:italic;">"${d.notes}"</div>` : ''}
                        <div style="font-size:0.78rem; color:#0369a1; display:flex; justify-content:space-between; border-top:1px dashed #e2e8f0; padding-top:4px; margin-top:4px;">
                            <span><strong>Reportado por:</strong> ${d.teacher || 'Catedrático Titular'}</span>
                            ${d.tutorNotified ? '<span style="color:#15803d; font-weight:700;"><i class="fa-solid fa-phone-volume"></i> Padres Notificados</span>' : '<span style="color:#b45309;">Sin notificar a padres</span>'}
                        </div>
                    </div>
                `;
            }).join('');
        }
    }

    // 4. Pestaña 3: Récord de Calificaciones (RESTRINGIDO A DIRECCIÓN Y SECRETARÍA)
    const adminView = document.getElementById('profGradesAdminView');
    const docenteView = document.getElementById('profGradesDocenteRestrictedView');

    if (isDocente) {
        if (adminView) adminView.style.display = 'none';
        if (docenteView) docenteView.style.display = 'block';
    } else {
        if (adminView) adminView.style.display = 'block';
        if (docenteView) docenteView.style.display = 'none';
        renderStudentProfileGrades(student);
    }

    // Activar por defecto la Pestaña 1
    switchStudentProfileTab('data');

    showModalById('studentProfileModal');
}

function renderStudentProfileGrades(student) {
    const tbody = document.getElementById('profGradesTableBody');
    const summaryBox = document.getElementById('profGradesSummaryBox');
    if (!tbody) return;

    const gradeObj = (STATE.gradesList || []).find(g => 
        (g.code && g.code === student.grade) ||
        (g.name === student.grade && (!student.section || g.section === student.section)) ||
        (g.code && student.gradeCode && g.code === student.gradeCode) ||
        ((g.name + ' - ' + g.section) === student.grade)
    );
    const pensumCourses = (STATE.pensum || []).filter(p => 
        p.gradeCode === student.grade || 
        (student.gradeCode && p.gradeCode === student.gradeCode) ||
        (gradeObj && p.grade === gradeObj.name && p.section === gradeObj.section) ||
        (p.grade === student.grade && (!student.section || p.section === student.section))
    );
    
    // Obtener todas las materias configuradas
    let subjects = pensumCourses.length > 0 ? pensumCourses.map(p => p.subject) : (Object.keys(student.grades || {}));
    subjects = [...new Set(subjects)];

    if (subjects.length === 0) {
        tbody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding:25px; color:var(--text-muted);">No hay asignaturas registradas para este grado y sección en el pensum.</td></tr>`;
        if (summaryBox) summaryBox.innerHTML = '<span>Sin calificaciones registradas.</span>';
        return;
    }

    let totalAvgSum = 0;
    let subjectCount = 0;
    let passedCount = 0;
    let failedCount = 0;

    tbody.innerHTML = subjects.map(sub => {
        const grades = (student.grades && student.grades[sub]) ? student.grades[sub] : [0, 0, 0, 0];
        const g1 = grades[0] || 0;
        const g2 = grades[1] || 0;
        const g3 = grades[2] || 0;
        const g4 = grades[3] || 0;
        const activeVals = [g1, g2, g3, g4].filter(v => v > 0);
        const finalAvg = activeVals.length > 0 ? Math.round(activeVals.reduce((a, b) => a + b, 0) / activeVals.length) : 0;

        if (finalAvg > 0) {
            totalAvgSum += finalAvg;
            subjectCount++;
            if (finalAvg >= 60) passedCount++;
            else failedCount++;
        }

        const isFail = (finalAvg > 0 && finalAvg < 60);

        return `
            <tr>
                <td style="font-weight:700; text-align:left; padding:8px 12px; color:#1e293b;">${sub}</td>
                <td style="text-align:center; font-weight:600;">${g1 > 0 ? g1 : '<span style="color:#94a3b8;">—</span>'}</td>
                <td style="text-align:center; font-weight:600;">${g2 > 0 ? g2 : '<span style="color:#94a3b8;">—</span>'}</td>
                <td style="text-align:center; font-weight:600;">${g3 > 0 ? g3 : '<span style="color:#94a3b8;">—</span>'}</td>
                <td style="text-align:center; font-weight:600;">${g4 > 0 ? g4 : '<span style="color:#94a3b8;">—</span>'}</td>
                <td style="text-align:center; font-weight:800; font-size:0.95rem; ${isFail ? 'color:#b91c1c; background:#fee2e2;' : (finalAvg >= 60 ? 'color:#15803d; background:#dcfce7;' : 'color:#0369a1;')}">${finalAvg > 0 ? finalAvg : '—'}</td>
                <td style="text-align:center;">
                    <span class="badge ${isFail ? 'badge-danger' : (finalAvg >= 60 ? 'badge-success' : 'badge-secondary')}" style="font-size:0.78rem;">
                        ${finalAvg >= 60 ? 'Aprobada' : (finalAvg > 0 ? 'Reprobada' : 'Pendiente')}
                    </span>
                </td>
            </tr>
        `;
    }).join('');

    const generalAverage = subjectCount > 0 ? Math.round(totalAvgSum / subjectCount) : 0;
    if (summaryBox) {
        summaryBox.innerHTML = `
            <div>
                <strong>Promedio General Acumulado:</strong> 
                <span class="badge ${generalAverage >= 60 ? 'badge-success' : 'badge-warning'}" style="font-size:1rem; font-weight:800; padding:4px 12px; margin-left:6px;">
                    ${generalAverage} pts
                </span>
            </div>
            <div style="display:flex; gap:12px; font-weight:700;">
                <span style="color:#15803d;"><i class="fa-solid fa-circle-check"></i> ${passedCount} Aprobadas</span>
                <span style="color:#b91c1c;"><i class="fa-solid fa-circle-xmark"></i> ${failedCount} Reprobadas</span>
                <span style="color:#0369a1;"><i class="fa-solid fa-book"></i> ${subjects.length} Total Materias</span>
            </div>
        `;
    }
}

function printStudentReportCardFromProfile(studentId) {
    if (!hasRolePermission('reports', STATE.currentRole)) {
        showToast("Acceso Restringido: Su rol actual no tiene autorización para acceder al Boletín de Calificaciones.", "warning");
        return;
    }
    if (!canRoleModify('reports', STATE.currentRole)) {
        showToast("Acceso Restringido: Su rol tiene permiso de solo consulta para el Boletín de Calificaciones.", "info");
        return;
    }

    if (!studentId) studentId = STATE.selectedStudentId;
    const s = (STATE.students || []).find(x => x.id === studentId);
    if (!s) {
        showToast("Estudiante no encontrado para imprimir boletín.", "warning");
        return;
    }

    const select = document.getElementById('reportStudentSelect');
    if (select) {
        select.value = studentId;
    }
    printStudentReportCardOfficial();
}

