function downloadFormattedExcelWorkbook(htmlContent, filename) {
    let cleanFileName = filename.replace(/\.xls[x]?$/i, '') + '.xlsx';

    // Parsear el HTML y remover elementos img para evitar errores en Excel
    const div = document.createElement('div');
    div.innerHTML = htmlContent.replace(/<img[^>]*>/gi, '');
    const tableEl = div.querySelector('table');

    if (window.XLSX && tableEl) {
        try {
            // Convertir la tabla limpia a libro binario .xlsx nativo de OpenXML
            const wb = XLSX.utils.table_to_book(tableEl, { raw: true, sheet: "ENCCO 1970" });
            const ws = wb.Sheets["ENCCO 1970"];
            if (ws) {
                // Configurar tamaño Oficio (Legal = 5) y ajuste a 1 sola página horizontal
                ws['!pageSetup'] = { paperSize: 5, orientation: 'landscape', fitToWidth: 1, fitToHeight: 1, scale: 70 };
                ws['!views'] = [{ showGridLines: true }];
            }
            XLSX.writeFile(wb, cleanFileName);
            return;
        } catch (err) {
            console.warn("SheetJS export fallback error:", err);
        }
    }

    // Respaldo secundario: Si SheetJS no está listo, descargar como .xls HTML compatible con 100% colores y ajuste a 1 hoja Oficio
    const legacyFileName = filename.replace(/\.xls[x]?$/i, '') + '.xls';
    const fullDocument = `
        <html xmlns:o="urn:schemas-microsoft-com:office:office" 
              xmlns:x="urn:schemas-microsoft-com:office:excel" 
              xmlns="http://www.w3.org/TR/REC-html40">
        <head>
            <meta http-equiv="Content-Type" content="text/html; charset=utf-8">
            <!--[if gte mso 9]>
            <xml>
             <x:ExcelWorkbook>
              <x:ExcelWorksheets>
               <x:ExcelWorksheet>
                <x:Name>ENCCO 1970</x:Name>
                <x:WorksheetOptions>
                 <x:DisplayGridlines/>
                 <x:FitToPage/>
                 <x:Print>
                  <x:FitWidth>1</x:FitWidth>
                  <x:FitHeight>1</x:FitHeight>
                  <x:ValidPrinterInfo/>
                  <x:PaperSizeIndex>5</x:PaperSizeIndex>
                  <x:Scale>70</x:Scale>
                  <x:HorizontalResolution>600</x:HorizontalResolution>
                  <x:VerticalResolution>600</x:VerticalResolution>
                 </x:Print>
                </x:WorksheetOptions>
               </x:ExcelWorksheet>
              </x:ExcelWorksheets>
             </x:ExcelWorkbook>
            </xml>
            <![endif]-->
            <style>
                @page {
                    size: 8.5in 14in landscape;
                    margin: 0.25in;
                    mso-header-data: "";
                    mso-footer-data: "";
                }
                br { mso-data-placement: same-cell; }
                table { width: 100%; border-collapse: collapse; font-family: 'Segoe UI', Calibri, Arial, sans-serif; font-size: 8.5pt; }
                td, th { border: 1pt solid #000000 !important; }
                .banner-cell { background-color: #0369a1 !important; color: #ffffff !important; font-size: 13pt; font-weight: bold; text-align: center; border: 1.5pt solid #000000 !important; vertical-align: middle; padding: 6px; }
                .version-cell { background-color: #0284c7 !important; color: #ffffff !important; font-size: 9.5pt; font-weight: bold; text-align: right; border: 1.5pt solid #000000 !important; vertical-align: middle; padding-right: 8px; }
                .meta-lbl { font-weight: bold; font-size: 9pt; color: #0369a1 !important; border: 1pt solid #000000 !important; border-left: 2pt solid #000000 !important; padding: 3px 5px; background-color: #f0f9ff !important; }
                .meta-val { font-size: 9pt; color: #0f172a; border: 1pt solid #000000 !important; padding: 3px 5px; background-color: #f0f9ff !important; }
                .box-num { font-size: 14pt; font-weight: 800; text-align: center; vertical-align: middle; border: 1.5pt solid #000000 !important; background-color: #ffffff; color: #0f172a; }
                .box-lbl { font-size: 8pt; font-weight: bold; text-align: center; vertical-align: middle; border: 1.5pt solid #000000 !important; background-color: #e0f2fe !important; color: #0369a1; text-transform: uppercase; }
                .th-blue { background-color: #0369a1 !important; color: #ffffff !important; font-weight: bold; text-align: center; border: 1.5pt solid #000000 !important; font-size: 9pt; vertical-align: middle; padding: 5px; text-transform: uppercase; }
                .th-sub { background-color: #ffffff !important; color: #0f172a !important; font-size: 8pt; font-weight: bold; text-align: center; border: 1pt solid #000000 !important; padding: 3px; }
                .th-zona { background-color: #e0f2fe !important; color: #0369a1 !important; font-weight: bold; text-align: center; border: 1.5pt solid #000000 !important; font-size: 9pt; vertical-align: middle; }
                .th-prueba { background-color: #fde4d0 !important; color: #9a3412 !important; font-weight: bold; text-align: center; border: 1.5pt solid #000000 !important; font-size: 9pt; vertical-align: middle; }
                .th-total { background-color: #0f172a !important; color: #ffffff !important; font-weight: bold; text-align: center; border: 1.5pt solid #000000 !important; font-size: 9.5pt; vertical-align: middle; }
                .td-num { font-weight: bold; text-align: center; background-color: #f8fafc !important; border: 1pt solid #000000 !important; font-size: 8.5pt; color: #000000; }
                .td-name { font-weight: normal; text-align: left; border: 1pt solid #000000 !important; font-size: 8.5pt; padding-left: 5px; color: #000000; mso-number-format: "\\@"; }
                .td-score { text-align: center; border: 1pt solid #000000 !important; font-size: 8.5pt; color: #000000; }
                .td-zona { text-align: center; font-weight: bold; background-color: #f0f9ff !important; border: 1pt solid #000000 !important; font-size: 8.5pt; color: #0369a1; }
                .td-prueba { text-align: center; border: 1pt solid #000000 !important; font-size: 8.5pt; color: #000000; }
                .td-pass { background-color: #f0f9ff !important; color: #0369a1 !important; font-weight: bold; text-align: center; border: 1.5pt solid #000000 !important; font-size: 9pt; }
                .td-fail { background-color: #fee2e2 !important; color: #b91c1c !important; font-weight: bold; text-align: center; border: 1.5pt solid #000000 !important; font-size: 9pt; }
            </style>
        </head>
        <body>
            ${htmlContent}
        </body>
        </html>
    `;

    const blob = new Blob([fullDocument], { type: 'application/vnd.ms-excel;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = legacyFileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

function readExcelFileRows(file, callback) {
    if (!file) return;

    if (window.XLSX) {
        const reader = new FileReader();
        reader.onload = function(evt) {
            try {
                const data = new Uint8Array(evt.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                const firstSheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[firstSheetName];
                const jsonRows = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '' });
                const rawLines = jsonRows.map(row => {
                    if (!Array.isArray(row)) return '';
                    return row.map(cell => {
                        const clean = String(cell !== undefined && cell !== null ? cell : '').replace(/\s+/g, ' ').trim();
                        return clean.includes(',') || clean.includes(';') ? `"${clean}"` : clean;
                    }).join(',');
                }).filter(r => r.replace(/,/g, '').trim().length > 0);

                callback(rawLines);
            } catch (err) {
                console.warn("SheetJS import parse error, using text fallback:", err);
                fallbackTextRead(file, callback);
            }
        };
        reader.readAsArrayBuffer(file);
    } else {
        fallbackTextRead(file, callback);
    }
}

function fallbackTextRead(file, callback) {
    const reader = new FileReader();
    reader.onload = function(evt) {
        const text = evt.target.result;
        const rawLines = parseImportFileRows(text);
        callback(rawLines);
    };
    reader.readAsText(file);
}

function exportStudentsOfficialExcel() {
    const careerFilter = document.getElementById('studentCareerFilterSelect')?.value || '';
    const gradeFilter = document.getElementById('gradeFilterSelect')?.value || '';
    const statusFilter = document.getElementById('statusFilterSelect')?.value || 'Activo';

    let students = STATE.students || [];
    if (statusFilter !== 'ALL') {
        students = students.filter(s => s.status === statusFilter);
    }
    if (gradeFilter) {
        students = students.filter(s => s.grade === gradeFilter);
    }

    students.sort((a, b) => {
        const lastA = (a.lastName || '').trim().toLowerCase();
        const lastB = (b.lastName || '').trim().toLowerCase();
        if (lastA !== lastB) return lastA.localeCompare(lastB);
        return (a.firstName || '').trim().toLowerCase().localeCompare((b.firstName || '').trim().toLowerCase());
    });

    const gradeObj = (STATE.gradesList || []).find(g => g.code === gradeFilter);
    const gradeTitle = gradeObj ? gradeObj.name : (gradeFilter ? gradeFilter : 'Nómina General');
    const sectionTitle = gradeObj ? gradeObj.section : 'A';
    const activeB = parseInt(STATE.config?.activeBimestre) || 2;
    const cycle = STATE.activeCycle || '2026';

    const rowsHtml = students.map((s, idx) => {
        const fullName = `${(s.lastName || '').toUpperCase()}, ${(s.firstName || '').toUpperCase()}`;
        return `
            <tr>
                <td class="td-num">${idx + 1}</td>
                <td class="td-score">${s.personalCode || '-'}</td>
                <td class="td-score">${s.cui || '-'}</td>
                <td class="td-score">${s.carne || '-'}</td>
                <td class="td-name">${fullName}</td>
                <td class="td-score">${s.phone || '-'}</td>
                <td class="td-name">${s.tutor || s.guardianName || '-'}</td>
                <td class="td-score">${s.tutorPhone || s.guardianPhone1 || '-'}</td>
                <td class="td-score" style="font-weight:bold; color:#15803d;">${s.status || 'Activo'}</td>
            </tr>
        `;
    }).join('');

    const htmlContent = `
        <table border="1">
            <tr>
                <td colspan="7" class="banner-cell">Escuela Nacional de Ciencias Comerciales</td>
                <td colspan="2" class="version-cell">${activeB}º Bimestre</td>
            </tr>
            <tr>
                <td class="meta-lbl" colspan="2">Documento:</td>
                <td class="meta-val" colspan="4">Nómina Oficial de Matrícula Estudiantil</td>
                <td class="box-num" rowspan="2">${gradeObj ? (gradeObj.name.match(/\d+/) ? gradeObj.name.match(/\d+/)[0] + 'º' : gradeObj.name) : 'Gral'}</td>
                <td class="box-num" rowspan="2">${sectionTitle}</td>
                <td class="box-num" rowspan="2">${activeB}º</td>
            </tr>
            <tr>
                <td class="meta-lbl" colspan="2">Responsable:</td>
                <td class="meta-val" colspan="4">Dirección General / Secretaría Académica ENCCO</td>
            </tr>
            <tr>
                <td class="meta-lbl" colspan="2">Ciclo Escolar:</td>
                <td class="meta-val" colspan="4">${cycle}</td>
                <td class="box-lbl">Grado</td>
                <td class="box-lbl">Sección</td>
                <td class="box-lbl">Bimestre</td>
            </tr>
            <tr>
                <th class="th-blue" style="width:40px;">Clave</th>
                <th class="th-blue" style="width:90px;">Cód. Personal</th>
                <th class="th-blue" style="width:110px;">CUI</th>
                <th class="th-blue" style="width:85px;">Carné</th>
                <th class="th-blue" style="width:260px;">Alumno (Apellidos y Nombres)</th>
                <th class="th-blue" style="width:85px;">Teléfono</th>
                <th class="th-blue" style="width:200px;">Padre / Encargado</th>
                <th class="th-blue" style="width:85px;">Tel. Encargado</th>
                <th class="th-blue" style="width:65px;">Estado</th>
            </tr>
            ${rowsHtml}
        </table>
    `;

    const fileName = `nomina_estudiantes_encc_${gradeFilter || 'completa'}_${cycle}.xls`;
    downloadFormattedExcelWorkbook(htmlContent, fileName);
    showToast(`Nómina de ${students.length} estudiantes exportada con formato y colores en Microsoft Excel.`, "success");
}

