function switchDbTab(tabName) {
    document.querySelectorAll('.db-tab-btn').forEach(btn => btn.classList.remove('active'));
    document.querySelectorAll('.db-tab-content').forEach(content => {
        content.classList.remove('active');
        content.style.display = 'none';
    });

    const activeBtn = document.getElementById(`dbTabBtn-${tabName}`);
    const activeContent = document.getElementById(`dbTab-${tabName}`);

    if (activeBtn) activeBtn.classList.add('active');
    if (activeContent) {
        activeContent.classList.add('active');
        activeContent.style.display = 'block';
    }
}

function copyDatabaseSQL() {
    if (navigator.clipboard) {
        navigator.clipboard.writeText(DATABASE_SQL_SCRIPT).then(() => {
            showToast("¡Script SQL del modelo copiado al portapapeles con éxito!", "success");
        }).catch(() => {
            copyFallbackSQL();
        });
    } else {
        copyFallbackSQL();
    }
}

function copyFallbackSQL() {
    const textarea = document.createElement('textarea');
    textarea.value = DATABASE_SQL_SCRIPT;
    document.body.appendChild(textarea);
    textarea.select();
    document.execCommand('copy');
    document.body.removeChild(textarea);
    showToast("¡Script SQL del modelo copiado al portapapeles!", "success");
}

