function exportDataBackupJSON() {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(STATE, null, 2));
    const downloadAnchor = document.createElement('a');
    downloadAnchor.setAttribute("href", dataStr);
    downloadAnchor.setAttribute("download", `ENCCO_Respaldo_BaseDatos_${new Date().toISOString().slice(0,10)}.json`);
    document.body.appendChild(downloadAnchor);
    downloadAnchor.click();
    downloadAnchor.remove();
    showToast("¡Copia de seguridad JSON descargada con éxito!", "success");
}

function importDataBackupJSON(e) {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = function(evt) {
        try {
            const data = JSON.parse(evt.target.result);
            if (data.users || data.students || data.gradesList) {
                STATE.users = data.users || STATE.users;
                STATE.careers = data.careers || STATE.careers;
                STATE.cycles = data.cycles || STATE.cycles || [];
                STATE.activeCycle = data.activeCycle || STATE.activeCycle || '';
                STATE.gradesList = data.gradesList || STATE.gradesList;
                STATE.pensumCatalog = data.pensumCatalog || STATE.pensumCatalog;
                STATE.students = data.students || STATE.students;
                STATE.pensum = data.pensum || STATE.pensum;
                STATE.announcements = data.announcements || STATE.announcements;
                STATE.disciplineReports = data.disciplineReports || STATE.disciplineReports;
                STATE.attendanceRecords = data.attendanceRecords || STATE.attendanceRecords || {};
                saveStateToLocalStorage();
                updateCycleSelects();
                updateCareerSelects();
                updateGradeSelects();
                renderCurrentView();
                showToast("¡Base de datos restaurada correctamente desde el respaldo JSON!", "success");
            } else {
                showToast("El archivo JSON no tiene el formato de respaldo válido de ENCCO.", "danger");
            }
        } catch (err) {
            showToast("Error al procesar el archivo JSON de respaldo.", "danger");
        }
    };
    reader.readAsText(file);
    e.target.value = '';
}

function populateReportStudentSelect() {
    if (!hasRolePermission('reports', STATE.currentRole)) {
        return;
    }

    const gradeFilter = document.getElementById('reportGradeFilter');
    const sectionFilter = document.getElementById('reportSectionFilter');

    // Cargar opciones de Grado disponibles
    const allStudents = STATE.students || [];
    let distinctGrades = Array.from(new Set(allStudents.map(s => s.grade).filter(Boolean))).sort();
    if (distinctGrades.length === 0) {
        distinctGrades = ['4to Perito Contador', '5to Perito Contador', '6to Perito Contador'];
    }

    if (gradeFilter) {
        const curGrade = gradeFilter.value;
        gradeFilter.innerHTML = '<option value="">-- Todos los Grados --</option>' + 
            distinctGrades.map(g => `<option value="${g}" ${g === curGrade ? 'selected' : ''}>${g}</option>`).join('');
    }

    // Cargar opciones de Sección disponibles
    const distinctSections = ['Sección A', 'Sección B', 'Sección C', 'Sección D'];
    if (sectionFilter) {
        const curSection = sectionFilter.value;
        sectionFilter.innerHTML = '<option value="">-- Todas las Secciones --</option>' + 
            distinctSections.map(sec => `<option value="${sec}" ${sec === curSection ? 'selected' : ''}>${sec}</option>`).join('');
    }
    filterAndPopulateReportStudents();
}
