function getFilteredReportStudents() {
    let students = STATE.students || [];
    const gradeVal = document.getElementById('reportGradeFilter')?.value || '';
    const sectionVal = document.getElementById('reportSectionFilter')?.value || '';

    if (STATE.currentRole === 'estudiante') {
        const currentUserId = STATE.currentUser?.id;
        const currentCarne = STATE.currentUser?.username || STATE.currentUser?.carne;
        students = students.filter(s => s.id === currentUserId || (currentCarne && s.carne === currentCarne));
    } else if (STATE.currentRole === 'docente') {
        const currentUser = STATE.currentUser || STATE.users[0];
        const teacherName = (currentUser.name || '').toLowerCase();
        const teacherPensum = (STATE.pensum || []).filter(p => 
            (p.teacherId && p.teacherId === currentUser.id) || 
            (p.teacher && p.teacher.toLowerCase().includes(teacherName)) || 
            (p.teacherName && p.teacherName.toLowerCase().includes(teacherName))
        );
        const myGrades = Array.from(new Set(teacherPensum.map(p => p.grade || p.gradeCode)));
        if (myGrades.length > 0) {
            students = students.filter(s => myGrades.includes(s.grade) || myGrades.some(g => (s.gradeLabel || '').includes(g) || (s.gradeCode || '').includes(g)));
        }
    }

    if (gradeVal) {
        students = students.filter(s => s.grade === gradeVal || (s.gradeLabel && s.gradeLabel.includes(gradeVal)));
    }
    if (sectionVal) {
        students = students.filter(s => s.section === sectionVal || (s.gradeLabel && s.gradeLabel.includes(sectionVal)));
    }

    return students.sort((a, b) => (a.lastName || '').localeCompare(b.lastName || ''));
}
window.getFilteredReportStudents = getFilteredReportStudents;

function filterAndPopulateReportStudents() {
    const select = document.getElementById('reportStudentSelect');
    const students = getFilteredReportStudents();

    if (!select) return;

    if (students.length === 0) {
        select.innerHTML = '<option value="">-- No hay estudiantes para este filtro --</option>';
        const area = document.getElementById('reportCardPrintArea');
        if (area) {
            area.innerHTML = '<div style="text-align:center; padding:40px 20px; color:#64748b;"><i class="fa-solid fa-circle-exclamation" style="font-size:2.2rem; margin-bottom:12px; color:#94a3b8; display:block;"></i>No se encontraron estudiantes para el grado y sección seleccionados.</div>';
        }
        return;
    }

    select.innerHTML = students.map(s => `
        <option value="${s.id}">${s.lastName}, ${s.firstName} (${s.carne || s.personalCode || '—'}) - ${formatStudentGradeAndSection(s)}</option>
    `).join('');

    previewStudentReportCard(students[0].id);
}
window.filterAndPopulateReportStudents = filterAndPopulateReportStudents;

function getPensumCatalogOrder(subjectName, studentGrade = '') {
    const catalog = STATE.pensumCatalog || [];
    const cleanStr = s => (s || '').toLowerCase()
        .normalize("NFD").replace(/[̀-ͯ]/g, "")
        .replace(/[^a-z0-9]/g, '');

    const cleanSub = cleanStr(subjectName);
    const cleanGrade = cleanStr(studentGrade);

    // 1. Coincidencia prioritaria en catálogo dentro del mismo grado
    const inGrade = catalog.filter(p => {
        const pGrade = cleanStr(p.grade || p.gradeCode);
        return pGrade && (pGrade.includes(cleanGrade) || cleanGrade.includes(pGrade));
    });

    let match = inGrade.find(p => {
        const pClean = cleanStr(p.name || p.subject);
        return pClean === cleanSub || pClean.includes(cleanSub) || cleanSub.includes(pClean);
    });

    // 2. Coincidencia global en catálogo
    if (!match) {
        match = catalog.find(p => {
            const pClean = cleanStr(p.name || p.subject);
            return pClean === cleanSub || pClean.includes(cleanSub) || cleanSub.includes(pClean);
        });
    }

    if (match) {
        const orderNum = parseInt(match.sortOrder || match.order);
        if (!isNaN(orderNum)) return orderNum;
        if (match.code) {
            const codeNum = parseInt(match.code.replace(/[^0-9]/g, ''));
            if (!isNaN(codeNum)) return codeNum;
        }
        const catIdx = catalog.indexOf(match);
        if (catIdx !== -1) return catIdx + 1;
    }

    // 3. Diccionario canónico de respaldo
    if (typeof CANONICAL_CNB_28_DICTIONARY !== 'undefined') {
        const cMatch = CANONICAL_CNB_28_DICTIONARY.find(c => {
            const cClean = cleanStr(c.full);
            return cClean === cleanSub || c.aliases.some(a => cleanStr(a) === cleanSub);
        });
        if (cMatch) {
            return CANONICAL_CNB_28_DICTIONARY.indexOf(cMatch) + 1;
        }
    }

    return 999;
}
window.getPensumCatalogOrder = getPensumCatalogOrder;

function getReportCardSubjects(student) {
    if (!student) return [];
    const cleanStr = s => (s || '').toLowerCase()
        .normalize("NFD").replace(/[̀-ͯ]/g, "")
        .replace(/[^a-z0-9]/g, '');

    const sGradeClean = cleanStr(student.grade || student.gradeLabel || student.gradeCode || '');

    // 1. Obtener las materias oficiales del Editor de Pensum para este grado
    let subjects = [];
    const catalogCourses = (STATE.pensumCatalog || []).filter(p => {
        const pGradeClean = cleanStr(p.grade || p.gradeCode || '');
        return pGradeClean && (pGradeClean.includes(sGradeClean) || sGradeClean.includes(pGradeClean));
    });

    catalogCourses.forEach(c => {
        const cName = (c.name || c.subject || '').trim();
        if (cName && !subjects.includes(cName)) {
            subjects.push(cName);
        }
    });

    // 2. Si no hubiera en pensumCatalog, buscar en STATE.pensum (asignaciones)
    if (subjects.length === 0) {
        const pensumCourses = (STATE.pensum || []).filter(p => {
            const pGradeClean = cleanStr(p.grade || p.gradeCode || '');
            return pGradeClean && (pGradeClean.includes(sGradeClean) || sGradeClean.includes(pGradeClean));
        });
        pensumCourses.forEach(p => {
            const pName = (p.subject || '').trim();
            if (pName && !subjects.includes(pName)) {
                subjects.push(pName);
            }
        });
    }

    // 3. Fallback canónico si estuviese vacío
    if (subjects.length === 0 && typeof CANONICAL_CNB_28_DICTIONARY !== 'undefined') {
        let gNum = 5;
        if (sGradeClean.includes('4') || sGradeClean.includes('cuarto')) gNum = 4;
        else if (sGradeClean.includes('6') || sGradeClean.includes('sexto')) gNum = 6;
        subjects = CANONICAL_CNB_28_DICTIONARY.filter(c => c.grade === gNum).map(c => c.full);
    }

    // 4. ORDENAMIENTO ESTRICTO: Según el # Orden oficial del Editor de Pensum
    subjects.sort((a, b) => getPensumCatalogOrder(a, student.grade) - getPensumCatalogOrder(b, student.grade));

    return subjects;
}
window.getReportCardSubjects = getReportCardSubjects;

function getReportCardSubjectGrades(student, subject) {
    let b1 = 0, b2 = 0, b3 = 0, b4 = 0;
    const cleanStr = s => (s || '').toLowerCase()
        .normalize("NFD").replace(/[̀-ͯ]/g, "")
        .replace(/[^a-z0-9]/g, '');
    const cleanTarget = cleanStr(subject);

    if (student.grades) {
        if (student.grades[subject]) {
            b1 = student.grades[subject][0] || 0;
            b2 = student.grades[subject][1] || 0;
            b3 = student.grades[subject][2] || 0;
            b4 = student.grades[subject][3] || 0;
        } else {
            // Búsqueda flexible por nombre normalizado
            for (const k of Object.keys(student.grades)) {
                const cK = cleanStr(k);
                if (cK === cleanTarget || (cK.length > 5 && (cK.includes(cleanTarget) || cleanTarget.includes(cK)))) {
                    b1 = student.grades[k][0] || 0;
                    b2 = student.grades[k][1] || 0;
                    b3 = student.grades[k][2] || 0;
                    b4 = student.grades[k][3] || 0;
                    break;
                }
            }
        }
    }

    // Si b1 es 0, consultar el mapa maestro oficial del 1er Bimestre
    if (b1 === 0 && typeof getOfficialBim1Details === 'function') {
        let off = getOfficialBim1Details(student, subject);
        if (!off) {
            // Intentar con variantes canónicas
            if (typeof CANONICAL_CNB_28_DICTIONARY !== 'undefined') {
                const cItem = CANONICAL_CNB_28_DICTIONARY.find(c => cleanStr(c.full) === cleanTarget || c.aliases.some(a => cleanStr(a) === cleanTarget));
                if (cItem) {
                    off = getOfficialBim1Details(student, cItem.full);
                    if (!off) {
                        for (const al of cItem.aliases) {
                            off = getOfficialBim1Details(student, al);
                            if (off) break;
                        }
                    }
                }
            }
        }
        if (off && off.total > 0) {
            b1 = off.total;
            if (!student.grades) student.grades = {};
            if (!student.grades[subject]) student.grades[subject] = [b1, 0, 0, 0];
            else student.grades[subject][0] = b1;
        }
    }
    if (b1 === 0 && typeof getAdditionalNomina2026Details === 'function') {
        const offNom1 = getAdditionalNomina2026Details(student, subject, 1);
        if (offNom1 && offNom1.total > 0) {
            b1 = offNom1.total;
            if (!student.grades) student.grades = {};
            if (!student.grades[subject]) student.grades[subject] = [b1, b2, b3, b4];
            else student.grades[subject][0] = b1;
        }
    }

    // Si b2 es 0, consultar el mapa maestro oficial del 2do Bimestre
    if (b2 === 0 && typeof getOfficialBim2Details === 'function') {
        let off2 = getOfficialBim2Details(student, subject);
        if (!off2) {
            // Intentar con variantes canónicas
            if (typeof CANONICAL_CNB_28_DICTIONARY !== 'undefined') {
                const cItem = CANONICAL_CNB_28_DICTIONARY.find(c => cleanStr(c.full) === cleanTarget || c.aliases.some(a => cleanStr(a) === cleanTarget));
                if (cItem) {
                    off2 = getOfficialBim2Details(student, cItem.full);
                    if (!off2) {
                        for (const al of cItem.aliases) {
                            off2 = getOfficialBim2Details(student, al);
                            if (off2) break;
                        }
                    }
                }
            }
        }
        if (off2 && off2.total > 0) {
            b2 = off2.total;
            if (!student.grades) student.grades = {};
            if (!student.grades[subject]) student.grades[subject] = [b1, b2, 0, 0];
            else student.grades[subject][1] = b2;
        }
    }
    if (b2 === 0 && typeof getAdditionalNomina2026Details === 'function') {
        const offNom2 = getAdditionalNomina2026Details(student, subject, 2);
        if (offNom2 && offNom2.total > 0) {
            b2 = offNom2.total;
            if (!student.grades) student.grades = {};
            if (!student.grades[subject]) student.grades[subject] = [b1, b2, b3, b4];
            else student.grades[subject][1] = b2;
        }
    }

    const activeVals = [b1, b2, b3, b4].filter(v => v > 0);
    const avg = activeVals.length > 0 ? Math.round(activeVals.reduce((a, b) => a + b, 0) / activeVals.length) : 0;
    return { b1, b2, b3, b4, avg };
}
window.getReportCardSubjectGrades = getReportCardSubjectGrades;

function buildStudentReportCardInnerHtml(s) {
    if (!s) return '';
    const gradeObj = (STATE.gradesList || []).find(g => 
        (g.code && g.code === s.grade) ||
        (g.name === s.grade && (!s.section || g.section === s.section)) ||
        (g.code && s.gradeCode && g.code === s.gradeCode)
    );
    const gradeName = gradeObj ? `${gradeObj.name} (${gradeObj.section})` : formatStudentGradeAndSection(s);
    const subjects = getReportCardSubjects(s);

    const activeBim = parseInt(STATE.config?.activeBimestre) || 1;

    let totalAvgSum = 0;
    let subjectCount = 0;

    const rowsHtml = subjects.map((sub, idx) => {
        const g = getReportCardSubjectGrades(s, sub);
        if (g.avg > 0) {
            totalAvgSum += g.avg;
            subjectCount++;
        }
        const isB1Fail = (g.b1 > 0 && g.b1 < 60);
        const isB2Fail = (g.b2 > 0 && g.b2 < 60);
        const isB3Fail = (g.b3 > 0 && g.b3 < 60);
        const isB4Fail = (g.b4 > 0 && g.b4 < 60);
        const isAvgFail = (g.avg > 0 && g.avg < 60);

        const resultText = g.avg >= 60 ? 'APROBADO' : (g.avg > 0 ? 'REPROBADO' : 'PENDIENTE');
        const resultColor = g.avg >= 60 ? '#15803d' : (g.avg > 0 ? '#dc2626' : '#64748b');

        return `
            <tr>
                <td style="text-align:center; font-weight:700; width:28px; border:1px solid #000000; padding:4px 2px; font-size:9px;">${idx + 1}</td>
                <td style="font-weight:700; padding:4px 6px; text-align:left; border:1px solid #000000; font-size:9.5px; color:#0f172a;">${sub}</td>
                <td style="text-align:center; font-size:10px; font-weight:${isB1Fail ? '800' : '700'}; color:${isB1Fail ? '#dc2626' : (g.b1 > 0 ? '#000000' : '#64748b')}; border:1px solid #000000; width:40px;">${g.b1 > 0 ? g.b1 : '—'}</td>
                <td style="text-align:center; font-size:10px; font-weight:${isB2Fail ? '800' : '700'}; color:${isB2Fail ? '#dc2626' : (g.b2 > 0 ? '#000000' : '#64748b')}; border:1px solid #000000; width:40px;">${g.b2 > 0 ? g.b2 : '—'}</td>
                <td style="text-align:center; font-size:10px; font-weight:${isB3Fail ? '800' : '700'}; color:${isB3Fail ? '#dc2626' : (g.b3 > 0 ? '#000000' : '#64748b')}; border:1px solid #000000; width:40px;">${g.b3 > 0 ? g.b3 : '—'}</td>
                <td style="text-align:center; font-size:10px; font-weight:${isB4Fail ? '800' : '700'}; color:${isB4Fail ? '#dc2626' : (g.b4 > 0 ? '#000000' : '#64748b')}; border:1px solid #000000; width:40px;">${g.b4 > 0 ? g.b4 : '—'}</td>
                <td style="text-align:center; font-weight:800; font-size:10.5px; border:1px solid #000000; width:50px; ${isAvgFail ? 'color:#dc2626; background:#fee2e2;' : 'color:#0369a1; background:#f0f9ff;'}">${g.avg > 0 ? g.avg : '—'}</td>
                <td style="text-align:center; font-weight:800; font-size:9px; border:1px solid #000000; width:72px; color:${resultColor};">${resultText}</td>
            </tr>
        `;
    }).join('');

    const overallAvg = subjectCount > 0 ? Math.round(totalAvgSum / subjectCount) : 0;
    const isOverallFail = (overallAvg > 0 && overallAvg < 60);

    const directorUser = (STATE.users || []).find(u => u.role === 'director');
    const dirName = (directorUser && directorUser.name) ? directorUser.name : (STATE.schoolHeader?.directorName || 'Licda. Mirza Elizabeth Aragón Polanco de Hernández');
    const dirTitle = (STATE.schoolHeader?.directorTitle) || (dirName.toLowerCase().includes('licda') ? 'Directora del Plantel' : 'Director del Plantel');

    return `
        <div class="report-half-letter-sheet" style="background:#ffffff; color:#000000; width:100%; box-sizing:border-box; font-family:'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">
            <!-- ENCABEZADO INSTITUCIONAL -->
            <div style="display:flex; align-items:center; justify-content:space-between; border-bottom:2.5px solid #0369a1; padding-bottom:8px; margin-bottom:8px; gap:10px;">
                <div style="width:58px; height:58px; display:flex; align-items:center; justify-content:center; flex-shrink:0;">
                    <img src="logo.png" alt="Escudo Oficial ENCCO" onerror="this.src='portada-comercio-principal.webp'" style="max-width:100%; max-height:100%; object-fit:contain;">
                </div>
                <div style="flex:1; text-align:center;">
                    <div style="font-size:8px; font-weight:800; letter-spacing:0.5px; color:#1e293b; text-transform:uppercase;">MINISTERIO DE EDUCACIÓN — GUATEMALA</div>
                    <div style="font-size:11.5px; font-weight:900; color:#0369a1; margin:1px 0; text-transform:uppercase; line-height:1.15;">ESCUELA NACIONAL DE CIENCIAS COMERCIALES</div>
                    <div style="font-size:7.5px; font-weight:700; color:#475569; letter-spacing:0.3px;">JUTIAPA | FUNDADA EN 1970 — NIVEL MEDIO Y BÁSICO</div>
                    <div style="display:inline-block; background:#0369a1; color:#ffffff; font-size:8px; font-weight:800; padding:2px 10px; border-radius:10px; margin-top:3px; letter-spacing:0.3px; -webkit-print-color-adjust:exact; print-color-adjust:exact;">TARJETA OFICIAL DE CALIFICACIONES — CICLO LECTIVO ${STATE.activeCycle || '2026'}</div>
                </div>
                <div style="width:52px; text-align:center; flex-shrink:0;">
                    <div style="background:#f0f9ff; border:1.5px solid #0284c7; border-radius:6px; padding:3px 2px; text-align:center; -webkit-print-color-adjust:exact; print-color-adjust:exact;">
                        <span style="display:block; font-size:13px; font-weight:900; color:#0284c7; line-height:1;">${activeBim}.º</span>
                        <span style="display:block; font-size:6.5px; font-weight:800; color:#0f172a; line-height:1.1; text-transform:uppercase;">BIMESTRE<br>ACTIVO</span>
                    </div>
                </div>
            </div>

            <!-- DATOS DEL ESTUDIANTE -->
            <div style="display:grid; grid-template-columns:1fr 1fr; gap:3px 8px; background:#f8fafc; border:1px solid #cbd5e1; border-left:3.5px solid #0369a1; padding:5px 8px; font-size:8.5px; line-height:1.35; margin-bottom:8px; border-radius:3px; -webkit-print-color-adjust:exact; print-color-adjust:exact;">
                <div><strong style="color:#0369a1; font-weight:800;">Estudiante:</strong> <span style="font-weight:900; color:#0f172a; text-transform:uppercase;">${s.lastName}, ${s.firstName}</span></div>
                <div><strong style="color:#0369a1; font-weight:800;">Carné Oficial:</strong> <span>${s.carne || 'ENCCO-2026'}</span></div>
                <div><strong style="color:#0369a1; font-weight:800;">Código Personal:</strong> <span>${s.personalCode || '—'}</span></div>
                <div><strong style="color:#0369a1; font-weight:800;">Grado y Sección:</strong> <span>${gradeName}</span></div>
                <div><strong style="color:#0369a1; font-weight:800;">Carrera:</strong> <span>${s.career || 'Perito Contador'}</span></div>
                <div><strong style="color:#0369a1; font-weight:800;">Ciclo / Sede:</strong> <span>${STATE.activeCycle || '2026'} — Jornada Matutina</span></div>
            </div>

            <!-- TABLA DE CALIFICACIONES (4 BIMESTRES, PROMEDIO Y RESULTADO) -->
            <table style="width:100%; border-collapse:collapse; font-size:9.5px; border:1.5px solid #000000; margin-bottom:8px;">
                <thead>
                    <tr>
                        <th style="width:28px; background-color:#0369a1 !important; color:#ffffff !important; font-weight:800; font-size:8px; text-align:center; padding:4px 2px; border:1px solid #000000; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">No.</th>
                        <th style="text-align:left; padding-left:8px; background-color:#0369a1 !important; color:#ffffff !important; font-weight:800; font-size:8px; border:1px solid #000000; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">Asignatura / Área Curricular</th>
                        <th style="width:40px; background-color:#0369a1 !important; color:#ffffff !important; font-weight:800; font-size:8px; text-align:center; border:1px solid #000000; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">I Bim</th>
                        <th style="width:40px; background-color:#0369a1 !important; color:#ffffff !important; font-weight:800; font-size:8px; text-align:center; border:1px solid #000000; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">II Bim</th>
                        <th style="width:40px; background-color:#0369a1 !important; color:#ffffff !important; font-weight:800; font-size:8px; text-align:center; border:1px solid #000000; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">III Bim</th>
                        <th style="width:40px; background-color:#0369a1 !important; color:#ffffff !important; font-weight:800; font-size:8px; text-align:center; border:1px solid #000000; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">IV Bim</th>
                        <th style="width:50px; background-color:#0369a1 !important; color:#ffffff !important; font-weight:800; font-size:8px; text-align:center; border:1px solid #000000; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">Prom.</th>
                        <th style="width:72px; background-color:#0369a1 !important; color:#ffffff !important; font-weight:800; font-size:8px; text-align:center; border:1px solid #000000; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">Resultado</th>
                    </tr>
                </thead>
                <tbody>
                    ${rowsHtml}
                </tbody>
                <tfoot>
                    <tr style="background:#f1f5f9; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
                        <td colspan="6" style="text-align:right; font-weight:800; padding:4px 8px; border:1px solid #000000; font-size:9.5px;">PROMEDIO GENERAL ACUMULADO:</td>
                        <td style="text-align:center; font-weight:900; font-size:11px; border:1px solid #000000; color:${isOverallFail ? '#dc2626' : '#0369a1'}; background:${isOverallFail ? '#fee2e2' : '#e0f2fe'}; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">${overallAvg > 0 ? overallAvg : '—'}</td>
                        <td style="text-align:center; font-weight:800; font-size:9px; border:1px solid #000000; color:${overallAvg >= 60 ? '#15803d' : (overallAvg > 0 ? '#dc2626' : '#64748b')};">${overallAvg >= 60 ? 'PROMOVIDO' : (overallAvg > 0 ? 'EN RIESGO' : 'EN CURSO')}</td>
                    </tr>
                </tfoot>
            </table>

            <!-- BLOQUE DE FIRMA ÚNICA EXCLUSIVA DE LA DIRECCIÓN -->
            <div style="display:flex; justify-content:center; align-items:flex-end; margin-top:30px; padding-bottom:6px;">
                <div style="width:280px; text-align:center; position:relative;">
                    <img src="firma_director_sello.png" alt="Sello y Firma de Dirección" style="position:absolute; bottom:6px; left:50%; transform:translateX(-50%); width:140px; height:auto; pointer-events:none; opacity:0.96; filter:drop-shadow(0 1px 2px rgba(0,0,0,0.12));">
                    <div style="border-top:1.5px solid #000000; margin-top:55px; padding-top:4px;">
                        <div style="font-size:9.5px; font-weight:800; color:#0f172a;">${dirName}</div>
                        <div style="font-size:8.5px; font-weight:700; color:#475569;">${dirTitle}</div>
                        <div style="font-size:7.5px; font-weight:600; color:#64748b;">Escuela Nacional de Ciencias Comerciales — Jutiapa</div>
                    </div>
                </div>
            </div>

            <!-- PIE DE PÁGINA INSTITUCIONAL -->
            <div style="display:flex; justify-content:space-between; border-top:1px dotted #94a3b8; padding-top:4px; font-size:7.5px; color:#64748b; font-weight:600; margin-top:6px;">
                <span>ENCCO JUTIAPA • Sistema de Control Académico Oficial</span>
                <span>Fecha de emisión: ${new Date().toLocaleDateString('es-GT')}</span>
            </div>
        </div>
    `;
}
window.buildStudentReportCardInnerHtml = buildStudentReportCardInnerHtml;

function previewStudentReportCard(studentId) {
    const s = (STATE.students || []).find(x => x.id === studentId);
    const container = document.getElementById('reportCardPrintArea');
    if (!container) return;

    if (!s) {
        container.innerHTML = '<div style="text-align:center; padding:30px; color:#64748b;">Seleccione un estudiante para previsualizar su boletín oficial.</div>';
        return;
    }

    container.innerHTML = buildStudentReportCardInnerHtml(s);
}
window.previewStudentReportCard = previewStudentReportCard;

function printStudentReportCardOfficial(targetStudentId) {
    if (!hasRolePermission('reports', STATE.currentRole)) {
        showToast("Acceso Restringido: Su rol actual no tiene autorización para emitir boletines de calificaciones.", "warning");
        return;
    }

    if (!canRoleModify('reports', STATE.currentRole)) {
        showToast("Acceso Restringido: Su rol tiene permiso de solo consulta para el Boletín de Calificaciones. La impresión oficial requiere autorización administrativa.", "info");
        return;
    }

    const studentId = targetStudentId || document.getElementById('reportStudentSelect')?.value;
    const s = (STATE.students || []).find(x => x.id === studentId);
    if (!s) {
        showToast("Seleccione un estudiante para imprimir su boletín.", "warning");
        return;
    }

    const printWin = window.open('', '_blank');
    if (!printWin) {
        showToast("Permita las ventanas emergentes en su navegador para emitir el boletín en PDF.", "warning");
        return;
    }

    const cardHtml = buildStudentReportCardInnerHtml(s);

    printWin.document.write(`
        <!DOCTYPE html>
        <html lang="es">
        <head>
            <meta charset="UTF-8">
            <base href="${window.location.href}">
            <title>Boletín Oficial - ${s.lastName}, ${s.firstName} (Media Hoja Carta)</title>
            <style>
                @page {
                    size: 8.5in 5.5in;
                    margin: 4mm 6mm;
                }
                * { box-sizing: border-box; }
                body {
                    font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
                    color: #000000;
                    margin: 0;
                    padding: 0;
                    background: #ffffff;
                    width: 100%;
                    -webkit-print-color-adjust: exact !important;
                    print-color-adjust: exact !important;
                }
                .report-half-letter-sheet {
                    width: 100%;
                    box-sizing: border-box;
                    padding: 4px 6px;
                }
                @media print {
                    .no-print { display: none !important; }
                    body { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
                }
            </style>
        </head>
        <body>
            ${cardHtml}
        </body>
        </html>
    `);

    printWin.document.close();
    setTimeout(() => {
        printWin.focus();
        printWin.print();
    }, 300);
}
window.printStudentReportCardOfficial = printStudentReportCardOfficial;

function printBatchReportCardsOfficial() {
    if (!hasRolePermission('reports', STATE.currentRole)) {
        showToast("Acceso Restringido: Su rol actual no tiene autorización para emitir boletines de calificaciones.", "warning");
        return;
    }

    if (!canRoleModify('reports', STATE.currentRole)) {
        showToast("Acceso Restringido: Su rol tiene permiso de solo consulta para el Boletín de Calificaciones. La impresión oficial requiere autorización administrativa.", "info");
        return;
    }

    const students = getFilteredReportStudents();
    if (!students || students.length === 0) {
        showToast("No hay estudiantes para imprimir con el filtro seleccionado.", "warning");
        return;
    }

    const gradeVal = document.getElementById('reportGradeFilter')?.value || 'Todos los Grados';
    const sectionVal = document.getElementById('reportSectionFilter')?.value || 'Todas las Secciones';

    const printWin = window.open('', '_blank');
    if (!printWin) {
        showToast("Permita las ventanas emergentes en su navegador para emitir los boletines en PDF.", "warning");
        return;
    }

    const cardsHtml = students.map((s, idx) => `
        <div class="student-page-break">
            ${buildStudentReportCardInnerHtml(s)}
        </div>
    `).join('');

    printWin.document.write(`
        <!DOCTYPE html>
        <html lang="es">
        <head>
            <meta charset="UTF-8">
            <base href="${window.location.href}">
            <title>Lote de Boletines Oficiales - ${gradeVal} ${sectionVal} (${students.length} Estudiantes)</title>
            <style>
                @page {
                    size: 8.5in 5.5in;
                    margin: 4mm 6mm;
                }
                * { box-sizing: border-box; }
                body {
                    font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
                    color: #000000;
                    margin: 0;
                    padding: 0;
                    background: #ffffff;
                    width: 100%;
                    -webkit-print-color-adjust: exact !important;
                    print-color-adjust: exact !important;
                }
                .student-page-break {
                    page-break-after: always;
                    break-after: page;
                    width: 100%;
                    box-sizing: border-box;
                    padding: 4px 6px;
                    display: flex;
                    flex-direction: column;
                    justify-content: space-between;
                }
                .student-page-break:last-child {
                    page-break-after: avoid;
                    break-after: avoid;
                }
                @media print {
                    .no-print { display: none !important; }
                    body { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
                }
            </style>
        </head>
        <body>
            ${cardsHtml}
        </body>
        </html>
    `);

    printWin.document.close();
    setTimeout(() => {
        printWin.focus();
        printWin.print();
    }, 450);
}
window.printBatchReportCardsOfficial = printBatchReportCardsOfficial;

function openSectionStudentsModal(gradeCode) {
    STATE.activeSectionModalGrade = gradeCode;
    const gradeObj = (STATE.gradesList || []).find(g => g.code === gradeCode || g.id === gradeCode || g.name === gradeCode);
    const title = document.getElementById('sectionStudentsGradeName');
    const subtitle = document.getElementById('sectionStudentsSubtitle');
    const badge = document.getElementById('sectionStudentsCountBadge');
    const tbody = document.getElementById('sectionStudentsTableBody');

    const students = (typeof getSortedGradebookStudents === 'function') ? 
        getSortedGradebookStudents(gradeCode, gradeObj) : 
        (STATE.students || []).filter(s => s.grade === gradeCode || (gradeObj && s.grade === gradeObj.name));

    const secClean = (gradeObj?.section || '').toLowerCase().startsWith('secci') ? gradeObj.section : ('Sección ' + (gradeObj?.section || 'A'));
    if (title) title.textContent = gradeObj ? `${gradeObj.name} - ${secClean}` : gradeCode;
    if (subtitle) subtitle.textContent = `Carrera: ${gradeObj?.career || 'Perito Contador'} | Jornada: ${gradeObj?.shift || 'Matutina'}`;
    if (badge) badge.textContent = `${students.length} Estudiantes`;

    if (tbody) {
        tbody.innerHTML = students.map((s, idx) => `
            <tr>
                <td style="text-align:center;"><strong>${idx + 1}</strong></td>
                <td style="text-align:center;"><img src="${s.photo || 'https://ui-avatars.com/api/?name='+encodeURIComponent((s.firstName||'')+' '+(s.lastName||''))}" style="width:28px; height:28px; border-radius:50%; object-fit:cover;"></td>
                <td><code>${s.carne || s.personalCode || '---'}</code></td>
                <td><strong>${s.lastName || ''}, ${s.firstName || s.name || ''}</strong></td>
                <td style="text-align:center;">${s.age || (typeof calculateStudentAge === 'function' ? calculateStudentAge(s.birthDate) : '—') || '—'}</td>
                <td>${s.tutorPhone || s.phone || 'Sin teléfono'}</td>
                <td><span class="badge ${s.status === 'Activo' ? 'badge-success' : 'badge-danger'}">${s.status || 'Activo'}</span></td>
            </tr>
        `).join('') || `<tr><td colspan="7" style="text-align:center; padding:20px; color:#64748b;">No hay estudiantes asignados a esta sección.</td></tr>`;
    }

    showModalById('sectionStudentsModal');
}
window.openSectionStudentsModal = openSectionStudentsModal;

// ==========================================================================
// 🎓 CIERRE DE CICLO ESCOLAR, PROMOCIÓN DE ESTUDIANTES Y APERTURA DE NUEVO CICLO
// (EXCLUSIVO DIRECCIÓN, SECRETARÍA Y ADMINISTRACIÓN)
// ==========================================================================

function checkPromotionPermissions() {
    const role = STATE.currentRole;
    if (role !== 'admin' && role !== 'director' && role !== 'secretaria') {
        showToast("Acceso denegado: El cierre de ciclo y promoción es una potestad exclusiva de Dirección y Secretaría.", "danger");
        return false;
    }
    return true;
}

function openCyclePromotionModal(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (!checkEnrolmentPermissions()) return;
    populatePromotionCycleSelects();
    renderPromotionStudentsTable();
    showModalById('cyclePromotionModal');
}

function closeDisciplineResolutionModal() {
    const modal = document.getElementById('disciplineResolutionModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

function saveDisciplineResolutionForm(e) {
    if (e && e.preventDefault) e.preventDefault();

    const idInput = document.getElementById('discResModalReportId');
    const statusSelect = document.getElementById('discResStatusSelect');
    const actionSelect = document.getElementById('discResActionType');
    const resTextarea = document.getElementById('discResResolutionText');

    const reportId = idInput ? idInput.value : '';
    const status = statusSelect ? statusSelect.value : 'Resuelto';
    const actionType = actionSelect ? actionSelect.value : 'Citación de Padres de Familia';
    const resolutionText = resTextarea ? resTextarea.value.trim() : '';

    if (!resolutionText) {
        showToast('Debe ingresar el dictamen o resolución de la falta disciplinaria.', 'warning');
        return;
    }

    let list = STATE.disciplineReports || STATE.discipline || [];
    const rep = list.find(r => r.id === reportId);
    if (rep) {
        rep.status = status;
        rep.resolutionStatus = status;
        rep.actionType = actionType;
        rep.resolution = resolutionText;
        rep.resolutionText = resolutionText;
        rep.resolutionDate = new Date().toISOString();
        rep.resolvedBy = STATE.currentUser ? STATE.currentUser.name : 'Profesor Auxiliar';
    }

    saveStateToLocalStorage();
    closeDisciplineResolutionModal();
    renderDisciplineTable();
    showToast('Resolución disciplinaria registrada y guardada exitosamente.', 'success');
}




// ──────────────────────────────────────────────────────────────────────────
// 🖨️ MOTOR UNIVERSAL DE VISTA PREVIA E IMPRESIÓN DIRECTA EN PANTALLA
// ──────────────────────────────────────────────────────────────────────────

function closePrintDocumentModal() {
    const modal = document.getElementById('printDocumentModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

function renderAndShowPrintDocument(title, htmlContent, orientation = 'portrait') {
    const modal = document.getElementById('printDocumentModal');
    const titleEl = document.getElementById('printModalTitle');
    const contentEl = document.getElementById('printDocumentContent');
    const paperEl = document.getElementById('printDocumentPaper');

    if (!modal || !contentEl) {
        console.warn("No se encontró el contenedor modal de impresión.");
        return;
    }

    if (titleEl) titleEl.textContent = title;
    contentEl.innerHTML = htmlContent;

    if (paperEl) {
        if (orientation === 'landscape') {
            paperEl.style.maxWidth = '1050px';
        } else {
            paperEl.style.maxWidth = '900px';
        }
    }

    modal.classList.add('active');
    modal.style.setProperty('display', 'flex', 'important');
}

function executeNativeDocumentPrint() {
    const content = document.getElementById('printDocumentContent');
    if (!content) return;

    let iframe = document.getElementById('enccPrintIframe');
    if (!iframe) {
        iframe = document.createElement('iframe');
        iframe.id = 'enccPrintIframe';
        iframe.style.position = 'fixed';
        iframe.style.right = '0';
        iframe.style.bottom = '0';
        iframe.style.width = '0';
        iframe.style.height = '0';
        iframe.style.border = '0';
        document.body.appendChild(iframe);
    }

    const doc = iframe.contentWindow.document;
    doc.open();
    doc.write(`
        <!DOCTYPE html>
        <html lang="es">
        <head>
            <meta charset="UTF-8">
            <title>Impresión Oficial - ENCCO</title>
            <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
            <style>
                @page { size: 8.5in 13in portrait; margin: 6mm; }
                body { font-family: 'Segoe UI', Calibri, Arial, sans-serif; color: #000; margin: 0; padding: 0; background: #fff; font-size: 10px; }
                table { width: 100%; border-collapse: collapse; margin-top: 6px; }
                th, td { border: 1px solid #334155; padding: 4px 6px; }
                th { background-color: #0369a1 !important; color: #ffffff !important; font-weight: bold; text-align: center; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                @media print {
                    body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                }
            </style>
        </head>
        <body>
            ${content.innerHTML}
        </body>
        </html>
    `);
    doc.close();

    setTimeout(() => {
        iframe.contentWindow.focus();
        iframe.contentWindow.print();
    }, 400);
}

