function openCareerModal() {
    if (STATE.currentRole === 'docente' || STATE.currentRole === 'estudiante') {
        showToast('Acceso denegado: El personal docente no tiene acceso a gestionar carreras.', 'warning');
        return;
    }
    if (!checkEnrolmentPermissions()) return;
    normalizeCareers();
    resetCareerForm();
    renderCareerList();
    const modal = document.getElementById('careerModal');
    if (modal) showModalById(modal.id || 'careerModal');
}

function closeCareerModal() {
    const modal = document.getElementById('careerModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

function renderCareerList() {
    normalizeCareers();
    const box = document.getElementById('careerListDisplay');
    if (!box) return;

    if (!STATE.careers || STATE.careers.length === 0) {
        box.innerHTML = `
            <div style="text-align:center; padding:14px; color:var(--text-muted); font-size:0.85rem;">
                <i class="fa-solid fa-graduation-cap" style="font-size:1.4rem; display:block; margin-bottom:4px; color:var(--brand-orange);"></i>
                No hay carreras registradas en la institución. Registre una nueva carrera con el formulario inferior.
            </div>
        `;
        return;
    }

    box.innerHTML = STATE.careers.map(c => `
        <div style="display:flex; justify-content:space-between; align-items:center; background:var(--bg-main); padding:8px 12px; border-radius:var(--radius-sm); border:1px solid var(--border-color);">
            <div>
                <strong style="color:var(--text-primary); font-size:0.92rem;"><i class="fa-solid fa-graduation-cap" style="color:var(--brand-green);"></i> ${c.name}</strong><br>
                <small style="color:var(--text-muted); font-size:0.78rem;">Duración: ${c.duration || '3 Años'}</small>
            </div>
            <div style="display:flex; gap:6px;">
                <button class="btn btn-secondary btn-sm" onclick="openEditCareerModal('${c.id}')" title="Editar Carrera" style="padding:4px 8px;"><i class="fa-solid fa-pen"></i> Editar</button>
                <button class="btn btn-secondary btn-sm" style="color:var(--danger); padding:4px 8px;" onclick="deleteCareer('${c.id}')" title="Eliminar Carrera"><i class="fa-solid fa-trash"></i> Eliminar</button>
            </div>
        </div>
    `).join('');
}

function openEditCareerModal(careerId) {
    if (!checkEnrolmentPermissions()) return;
    normalizeCareers();
    const career = STATE.careers.find(c => c.id === careerId);
    if (!career) return;

    document.getElementById('careerFormId').value = career.id;
    document.getElementById('careerFormHeaderTitle').innerHTML = `<i class="fa-solid fa-pen-to-square"></i> Editar Carrera "${career.name}"`;
    document.getElementById('newCareerName').value = career.name;
    document.getElementById('newCareerDuration').value = career.duration || '3 Años';
    document.getElementById('cancelCareerEditBtn').style.display = 'inline-block';
    document.getElementById('careerSubmitBtn').innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Guardar Cambios';
}

function resetCareerForm() {
    const idEl = document.getElementById('careerFormId');
    const headerTitle = document.getElementById('careerFormHeaderTitle');
    const nameEl = document.getElementById('newCareerName');
    const durEl = document.getElementById('newCareerDuration');
    const cancelBtn = document.getElementById('cancelCareerEditBtn');
    const submitBtn = document.getElementById('careerSubmitBtn');

    if (idEl) idEl.value = '';
    if (headerTitle) headerTitle.innerHTML = '<i class="fa-solid fa-circle-plus"></i> Registrar Nueva Carrera';
    if (nameEl) nameEl.value = '';
    if (durEl) durEl.value = '';
    if (cancelBtn) cancelBtn.style.display = 'none';
    if (submitBtn) submitBtn.innerHTML = '<i class="fa-solid fa-plus"></i> Registrar Carrera';
}

function saveCareerForm(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (!checkEnrolmentPermissions()) return;

    normalizeCareers();
    const careerId = document.getElementById('careerFormId')?.value;
    const name = document.getElementById('newCareerName')?.value.trim();
    const duration = document.getElementById('newCareerDuration')?.value.trim();

    if (!name) {
        showToast("Ingrese el nombre de la carrera.", "warning");
        return;
    }

    if (careerId) {
        const career = STATE.careers.find(c => c.id === careerId);
        if (career) {
            const oldName = career.name;
            career.name = name;
            career.duration = duration || '3 Años';
            career.code = name.toUpperCase().replace(/\s+/g, '_');

            // Actualizar referencias en pensum y grados
            (STATE.pensum || []).forEach(p => {
                if (p.career === oldName) p.career = name;
            });
            (STATE.gradesList || []).forEach(g => {
                if (g.career === oldName) g.career = name;
            });

            showToast(`Carrera "${name}" actualizada correctamente.`, "success"); closeCareerModal(); hideModalById('careerModal');
        }
    } else {
        const exists = STATE.careers.some(c => c.name.toLowerCase() === name.toLowerCase());
        if (exists) {
            showToast(`La carrera "${name}" ya se encuentra registrada en la institución.`, "warning");
            return;
        }

        STATE.careers.push({
            id: 'car-' + Date.now(),
            name,
            code: name.toUpperCase().replace(/\s+/g, '_'),
            duration: duration || '3 Años'
        });
        showToast(`Nueva carrera "${name}" agregada exitosamente.`, "success");
    }

    saveStateToLocalStorage();
    resetCareerForm();
    renderCareerList();
    updateCareerSelects();
    renderGradesTable();
    renderPensumCatalogTable();
    renderAssignmentsTable();
}

function deleteCareer(careerId) {
    if (!checkEnrolmentPermissions()) return;
    normalizeCareers();
    const career = STATE.careers.find(c => c.id === careerId);
    if (!career) return;

    if (confirm(`¿Está seguro de eliminar la carrera "${career.name}"? Tenga en cuenta que afectará las asignaturas y grados asociados.`)) {
        STATE.careers = STATE.careers.filter(c => c.id !== careerId);
        saveStateToLocalStorage();
        resetCareerForm();
        renderCareerList();
        updateCareerSelects();
        renderGradesTable();
        renderPensumCatalogTable();
        renderAssignmentsTable();
        showToast(`Carrera "${career.name}" eliminada del sistema.`, "info");
    }
}

// ==========================================================================
// 7B. ADMIN Y GESTIÓN COMPLETA DE CICLOS LECTIVOS ESCOLARES
// ==========================================================================


function openCycleModal(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (!checkEnrolmentPermissions()) return;
    resetCycleForm();
    renderCycleList();
    showModalById('cycleModal');
}

function closeCycleModal() {
    const modal = document.getElementById('cycleModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

function renderCycleList() {
    const box = document.getElementById('cycleListDisplay');
    if (!box) return;

    const cycles = STATE.cycles || [];
    if (cycles.length === 0) {
        box.innerHTML = `
            <div style="text-align:center; padding:16px; color:var(--text-muted); font-size:0.85rem;">
                <i class="fa-solid fa-calendar-xmark" style="font-size:1.4rem; display:block; margin-bottom:4px; color:var(--brand-orange);"></i>
                No hay ciclos lectivos ingresados aún. Use el formulario inferior para ingresar el primer ciclo escolar oficial.
            </div>
        `;
        return;
    }

    box.innerHTML = cycles.map(c => {
        const isCurrentActive = (c.name === STATE.activeCycle);
        return `
        <div style="display:flex; justify-content:space-between; align-items:center; background:var(--bg-main); padding:8px 12px; border-radius:var(--radius-sm); border:1px solid ${isCurrentActive ? 'var(--brand-green)' : 'var(--border-color)'};">
            <div>
                <strong><i class="fa-solid fa-calendar-check" style="color:${isCurrentActive ? 'var(--brand-green)' : 'var(--text-muted)'};"></i> Ciclo ${c.name}</strong>
                ${isCurrentActive ? '<span class="badge badge-success" style="font-size:0.7rem; margin-left:6px;">En Uso</span>' : ''}
                ${c.status === 'Activo' && !isCurrentActive ? '<span class="badge badge-primary" style="font-size:0.7rem; margin-left:6px;">Activo</span>' : ''}
                <br>
                <small style="color:var(--text-muted);">${c.description || 'Ciclo Escolar Oficial'}</small>
            </div>
            <div style="display:flex; gap:6px; align-items:center;">
                ${!isCurrentActive ? `
                    <button class="btn btn-accent btn-sm" onclick="setCycleActive('${c.id}')" title="Seleccionar y activar este ciclo"><i class="fa-solid fa-check"></i> Activar</button>
                ` : ''}
                <button class="btn btn-secondary btn-sm" onclick="openEditCycleModal('${c.id}')" title="Editar Ciclo"><i class="fa-solid fa-pen"></i></button>
                <button class="btn btn-secondary btn-sm" style="color:var(--danger);" onclick="deleteCycle('${c.id}')" title="Eliminar Ciclo"><i class="fa-solid fa-trash"></i></button>
            </div>
        </div>
    `}).join('');
}

function openEditCycleModal(cycleId) {
    if (!checkEnrolmentPermissions()) return;
    const c = (STATE.cycles || []).find(x => x.id === cycleId);
    if (!c) return;

    document.getElementById('cycleFormId').value = c.id;
    document.getElementById('cycleFormHeaderTitle').innerHTML = `<i class="fa-solid fa-pen-to-square"></i> Editar Ciclo "${c.name}"`;
    document.getElementById('newCycleName').value = c.name;
    document.getElementById('newCycleStatus').value = c.status || 'Activo';
    document.getElementById('newCycleDescription').value = c.description || '';
    document.getElementById('cancelCycleEditBtn').style.display = 'inline-block';
    document.getElementById('cycleSubmitBtn').innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Guardar Cambios';
}

function resetCycleForm() {
    document.getElementById('cycleFormId').value = '';
    document.getElementById('cycleFormHeaderTitle').innerHTML = '<i class="fa-solid fa-circle-plus"></i> Ingresar Nuevo Ciclo Lectivo';
    document.getElementById('newCycleName').value = '';
    document.getElementById('newCycleStatus').value = 'Activo';
    document.getElementById('newCycleDescription').value = '';
    document.getElementById('cancelCycleEditBtn').style.display = 'none';
    document.getElementById('cycleSubmitBtn').innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Guardar Ciclo Lectivo';
}

function saveCycleForm(e) {
    e.preventDefault();
    if (!checkEnrolmentPermissions()) return;
    const cycleId = document.getElementById('cycleFormId').value;
    const name = document.getElementById('newCycleName').value.trim();
    const status = document.getElementById('newCycleStatus').value;
    const description = document.getElementById('newCycleDescription').value.trim();

    if (!STATE.cycles) STATE.cycles = [];

    if (cycleId) {
        const c = STATE.cycles.find(x => x.id === cycleId);
        if (c) {
            const oldName = c.name;
            c.name = name;
            c.status = status;
            c.description = description;
            if (STATE.activeCycle === oldName) {
                STATE.activeCycle = name;
            }
            showToast(`Ciclo escolar "${name}" actualizado correctamente.`, "success"); closeCycleModal(); hideModalById('cycleModal');
        }
    } else {
        // Verificar si ya existe
        if (STATE.cycles.some(x => x.name.toLowerCase() === name.toLowerCase())) {
            showToast(`El ciclo "${name}" ya se encuentra registrado.`, "warning");
            return;
        }

        const newCycle = {
            id: 'cyc-' + Date.now(),
            name,
            status,
            description
        };
        STATE.cycles.push(newCycle);

        // Si es el primer ciclo o se marcó como activo, hacerlo el ciclo activo
        if (STATE.cycles.length === 1 || status === 'Activo') {
            STATE.activeCycle = name;
        }
        showToast(`Ciclo escolar "${name}" ingresado exitosamente.`, "success");
    }

    saveStateToLocalStorage();
    resetCycleForm();
    renderCycleList();
    updateCycleSelects();
    renderCurrentView();
    if (typeof enforceViewReadOnlyMode === 'function') enforceViewReadOnlyMode(viewName);
}

function setCycleActive(cycleId) {
    const c = (STATE.cycles || []).find(x => x.id === cycleId);
    if (!c) return;
    STATE.activeCycle = c.name;
    saveStateToLocalStorage();
    renderCycleList();
    updateCycleSelects();
    showToast(`Ciclo escolar activo cambiado a: ${c.name}`, "info");
    renderCurrentView();
    if (typeof enforceViewReadOnlyMode === 'function') enforceViewReadOnlyMode(viewName);
}

function deleteCycle(cycleId) {
    if (!checkEnrolmentPermissions()) return;
    const c = (STATE.cycles || []).find(x => x.id === cycleId);
    if (!c) return;

    if (confirm(`¿Está seguro de eliminar el ciclo escolar "${c.name}"?`)) {
        STATE.cycles = (STATE.cycles || []).filter(x => x.id !== cycleId);
        if (STATE.cycles.length === 0) {
            STATE.cycles = [{ id: 'cyc-2026', name: '2026', status: 'Activo' }];
        }
        if (STATE.activeCycle === c.name) {
            STATE.activeCycle = STATE.cycles[0] ? STATE.cycles[0].name : '2026';
        }
        saveStateToLocalStorage();
        renderCycleList();
        updateCycleSelects();
        populateAttendanceSelects(false);
        updateUserAlertsUI();
        renderCurrentDashboardAlerts();
        showToast(`Ciclo escolar "${c.name}" eliminado del sistema.`, "info");
        renderCurrentView();
    }
}

// ==========================================================================
function isCourseAssignedToTeacher(p, user) {
    if (!p || !user) return false;
    if (p.teacherId && p.teacherId === user.id) return true;
    if (!p.teacher || !user.name) return false;
    const cleanStr = s => s.toLowerCase()
        .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
        .replace(/^(licda\.|lic\.|pem\.|prof\.|profesor|profesora|ma\.|ing\.|dr\.|dra\.)\s*/gi, "")
        .replace(/[\.,]/g, "")
        .trim();
    const cleanCourseTeacher = cleanStr(p.teacher);
    const cleanUserName = cleanStr(user.name);
    if (!cleanCourseTeacher || !cleanUserName) return false;
    if (cleanCourseTeacher === cleanUserName) return true;
    if (cleanCourseTeacher.includes(cleanUserName) || cleanUserName.includes(cleanCourseTeacher)) return true;
    
    const wordsCourse = cleanCourseTeacher.split(/\s+/).filter(w => w.length > 2);
    const wordsUser = cleanUserName.split(/\s+/).filter(w => w.length > 2);
    const matched = wordsCourse.filter(w => wordsUser.includes(w));
    return matched.length >= 2;
}
window.isCourseAssignedToTeacher = isCourseAssignedToTeacher;

// 8. LIBRO DE CALIFICACIONES SEGÚN LA CLASE DEL DOCENTE O ADMINISTRADOR
// ==========================================================================
function populateTeacherCourseSelect() {
    const select = document.getElementById('teacherCourseSelect');
    if (!select) return;

    const currentUser = STATE.currentUser || STATE.users.find(u => u.role === 'docente') || STATE.users[0];
    const isDocente = (STATE.currentRole === 'docente');

    let html = '';

    if (isDocente && currentUser) {
        // Los maestros SOLO pueden ver las clases a las que están asignados
        const myClasses = (STATE.pensum || []).filter(p => isCourseAssignedToTeacher(p, currentUser));

        if (myClasses.length > 0) {
            html += `<optgroup label="⭐ Mis Clases y Secciones Asignadas (${currentUser.name})">`;
            myClasses.forEach(p => {
                html += `<option value="${p.id}">${p.subject} — ${p.grade} (${p.section}) [${p.career}]</option>`;
            });
            html += `</optgroup>`;
        } else {
            html += `<optgroup label="⭐ Mis Clases Asignadas (${currentUser.name})"><option value="">-- Sin clases asignadas a su cuenta --</option></optgroup>`;
        }
    } else {
        // ADMIN / DIRECTOR / SECRETARIA PUEDE VER Y EDITAR CUALQUIER ASIGNATURA Y SECCIÓN
        html += `<optgroup label="🛡️ Acceso Administrativo — Todas las Clases y Secciones de la Escuela">`;
        (STATE.pensum || []).forEach(p => {
            html += `<option value="${p.id}">${p.subject} — ${p.grade} (${p.section}) — Catedrático: ${p.teacher} [${p.career}]</option>`;
        });
        html += `</optgroup>`;
    }

    select.innerHTML = html;
}

function populateGradebookBimestreSelect() {
    const select = document.getElementById('gradebookBimestreSelect');
    const notice = document.getElementById('gradebookTeacherBimestreNotice');
    const noticeText = document.getElementById('gradebookTeacherBimestreNoticeText');
    if (!select) return;

    const isDocente = (STATE.currentRole === 'docente');
    const activeB = parseInt(STATE.config?.activeBimestre) || 2;
    const bNames = {
        1: 'Unidad 1 / I Bimestre',
        2: 'Unidad 2 / II Bimestre',
        3: 'Unidad 3 / III Bimestre',
        4: 'Unidad 4 / IV Bimestre'
    };

    if (isDocente) {
        // Los maestros solo pueden ver y calificar el bimestre que esté activo
        select.innerHTML = `<option value="${activeB}" selected>${bNames[activeB] || `Unidad ${activeB}`} [ACTIVO]</option>`;
        select.disabled = true;
        select.style.backgroundColor = '#f8fafc';
        select.style.cursor = 'not-allowed';

        if (notice && noticeText) {
            notice.style.display = 'block';
            noticeText.innerHTML = `<i class="fa-solid fa-circle-check"></i> <strong>Bimestre Activo Oficial:</strong> ${bNames[activeB] || `Unidad ${activeB}`} (Establecido por Dirección y Secretaría).`;
        }
    } else {
        // Secretaría, Dirección y Administración pueden seleccionar y auditar cualquier bimestre
        select.innerHTML = `
            <option value="1">Unidad 1 / I Bimestre ${activeB === 1 ? '⭐ (Activo)' : ''}</option>
            <option value="2">Unidad 2 / II Bimestre ${activeB === 2 ? '⭐ (Activo)' : ''}</option>
            <option value="3">Unidad 3 / III Bimestre ${activeB === 3 ? '⭐ (Activo)' : ''}</option>
            <option value="4">Unidad 4 / IV Bimestre ${activeB === 4 ? '⭐ (Activo)' : ''}</option>
        `;
        select.value = activeB.toString();
        select.disabled = false;
        select.style.backgroundColor = '#ffffff';
        select.style.cursor = 'pointer';

        if (notice) {
            notice.style.display = 'none';
        }
    }

    renderTeacherGradeProgressTable();
}

// ==========================================================================
// 🛡️ CONTROL DIRECTIVO: SUPERVISIÓN Y AUDITORÍA DE INGRESO DE NOTAS POR DOCENTE (V73)
// ==========================================================================

function getTeacherAssignedCourses(teacherObj) {
    if (!teacherObj) return [];
    return (STATE.pensum || []).filter(p => isCourseAssignedToTeacher(p, teacherObj));
}

function calculateClassBimesterMetrics(c, bimester) {
    const studentsInGrade = (typeof getSortedGradebookStudents === 'function') ? 
        getSortedGradebookStudents(c.gradeCode, c).filter(s => isStudentActive(s)) : 
        (STATE.students || []).filter(s => isStudentActive(s));
    const totalStudents = studentsInGrade.length;
    if (totalStudents === 0) {
        return { total: 0, withGrades: 0, pct: 0, label: '<span style="color:var(--text-muted); font-size:0.75rem;">Sin alumnos</span>' };
    }

    let withGrades = 0;
    studentsInGrade.forEach(s => {
        const gVal = (s.grades && s.grades[c.subject]) ? s.grades[c.subject][bimester - 1] : 0;
        const dVal = (s.gradebookDetails && s.gradebookDetails[c.subject] && s.gradebookDetails[c.subject][bimester]) ? s.gradebookDetails[c.subject][bimester] : null;
        if (gVal > 0 || (dVal && (dVal.exam > 0 || (dVal.activities && dVal.activities.some(a => (parseInt(a) || 0) > 0))))) {
            withGrades++;
        }
    });

    const pct = Math.round((withGrades / totalStudents) * 100);
    let badgeHtml = '';
    if (pct >= 90) {
        badgeHtml = `<span class="badge" style="background:#dcfce7; color:#15803d; font-weight:800; padding:4px 8px; font-size:0.75rem;" title="${withGrades} de ${totalStudents} alumnos con notas ingresadas"><i class="fa-solid fa-circle-check"></i> ${pct}% (${withGrades}/${totalStudents})</span>`;
    } else if (pct > 0) {
        badgeHtml = `<span class="badge" style="background:#fef3c7; color:#b45309; font-weight:800; padding:4px 8px; font-size:0.75rem;" title="${withGrades} de ${totalStudents} alumnos con notas ingresadas"><i class="fa-solid fa-spinner"></i> ${pct}% (${withGrades}/${totalStudents})</span>`;
    } else {
        badgeHtml = `<span class="badge" style="background:#fee2e2; color:#dc2626; font-weight:800; padding:4px 8px; font-size:0.75rem;" title="0 de ${totalStudents} alumnos con notas ingresadas"><i class="fa-solid fa-clock"></i> 0% (0/${totalStudents})</span>`;
    }

    return { total: totalStudents, withGrades, pct, label: badgeHtml };
}

function calculateTeacherAllClassesBimesterMetrics(coursesList, bimester) {
    if (!Array.isArray(coursesList) || coursesList.length === 0) {
        return { total: 0, withGrades: 0, pct: 0, label: '<span style="color:var(--text-muted); font-size:0.75rem;">Sin cátedras</span>' };
    }

    let grandTotal = 0;
    let grandWithGrades = 0;

    coursesList.forEach(c => {
        const m = calculateClassBimesterMetrics(c, bimester);
        grandTotal += m.total;
        grandWithGrades += m.withGrades;
    });

    if (grandTotal === 0) {
        return { total: 0, withGrades: 0, pct: 0, label: '<span style="color:var(--text-muted); font-size:0.75rem;">Sin alumnos</span>' };
    }

    const pct = Math.round((grandWithGrades / grandTotal) * 100);
    let badgeHtml = '';
    if (pct >= 90) {
        badgeHtml = `<span class="badge" style="background:#dcfce7; color:#15803d; font-weight:800; padding:4px 8px; font-size:0.75rem;" title="Total: ${grandWithGrades} de ${grandTotal} notas ingresadas en todas las cátedras"><i class="fa-solid fa-circle-check"></i> ${pct}% Ingresado</span>`;
    } else if (pct > 0) {
        badgeHtml = `<span class="badge" style="background:#fef3c7; color:#b45309; font-weight:800; padding:4px 8px; font-size:0.75rem;" title="Total: ${grandWithGrades} de ${grandTotal} notas ingresadas en todas las cátedras"><i class="fa-solid fa-spinner"></i> ${pct}% En avance</span>`;
    } else {
        badgeHtml = `<span class="badge" style="background:#fee2e2; color:#dc2626; font-weight:800; padding:4px 8px; font-size:0.75rem;" title="Pendiente en todas las cátedras"><i class="fa-solid fa-clock"></i> 0% Pendiente</span>`;
    }

    return { total: grandTotal, withGrades: grandWithGrades, pct, label: badgeHtml };
}

