function populateAttendanceTeacherFilter() {
    const teacherSelect = document.getElementById('attendanceTeacherSelect');
    const filterGroup = document.getElementById('attendanceTeacherFilterGroup');
    const directorBanner = document.getElementById('attendanceDirectorBanner');
    if (!teacherSelect || !filterGroup) return;

    const isDirectorOrAdmin = (STATE.currentRole === 'director' || STATE.currentRole === 'admin' || STATE.currentRole === 'secretaria');

    if (!isDirectorOrAdmin) {
        filterGroup.style.display = 'none';
        if (directorBanner) directorBanner.style.display = 'none';
        return;
    }

    filterGroup.style.display = 'block';
    if (directorBanner) directorBanner.style.display = 'flex';

    const currentVal = teacherSelect.value;
    const teachers = (STATE.users || []).filter(u => u.role === 'docente' || u.role === 'admin' || u.role === 'director' || u.role === 'secretaria');

    let html = `<option value="">⭐ General por Grado (Todos los Maestros)</option>`;
    if (teachers.length > 0) {
        html += `<optgroup label="👨‍🏫 Catedráticos del Plantel">`;
        teachers.forEach(t => {
            html += `<option value="${t.id}">👨‍🏫 ${t.name} — ${t.title || t.role}</option>`;
        });
        html += `</optgroup>`;
    }

    teacherSelect.innerHTML = html;
    if (currentVal && Array.from(teacherSelect.options).some(o => o.value === currentVal)) {
        teacherSelect.value = currentVal;
    }
}

function onAttendanceTeacherFilterChange() {
    const teacherSelect = document.getElementById('attendanceTeacherSelect');
    const selectedTeacherId = teacherSelect ? teacherSelect.value : '';

    populateAttendanceSelects(true, selectedTeacherId);
    updateAttendanceCoursesList();
    loadAttendanceList();
}

function populateAttendanceSelects(resetSelection = false, filterTeacherId = null) {
    populateAttendanceTeacherFilter();

    const gradeSelect = document.getElementById('attendanceGradeSelect');
    const teacherSelect = document.getElementById('attendanceTeacherSelect');
    if (!gradeSelect) return;

    const currentUser = STATE.currentUser || STATE.users[0];
    const isDocente = (STATE.currentRole === 'docente');
    const isDirectorOrAdmin = (STATE.currentRole === 'director' || STATE.currentRole === 'admin' || STATE.currentRole === 'secretaria');
    const currentSelectedGrade = gradeSelect.value;

    const activeTeacherId = filterTeacherId !== null ? filterTeacherId : (teacherSelect ? teacherSelect.value : '');
    const activeTeacherObj = (STATE.users || []).find(u => u.id === activeTeacherId);

    let gradeOptionsHtml = '';

    if (isDocente && currentUser && !isDirectorOrAdmin) {
        const myClasses = (STATE.pensum || []).filter(p => 
            p.teacherId === currentUser.id || 
            (p.teacher && p.teacher.toLowerCase() === currentUser.name.toLowerCase()) ||
            (currentUser.name && p.teacher && p.teacher.toLowerCase().includes(currentUser.name.toLowerCase()))
        );

        const uniqueGrades = new Map();
        myClasses.forEach(c => {
            const key = c.gradeCode || c.grade;
            if (!uniqueGrades.has(key)) {
                uniqueGrades.set(key, {
                    code: key,
                    name: c.grade,
                    section: c.section || 'A',
                    career: c.career || 'Perito Contador'
                });
            }
        });

        if (uniqueGrades.size > 0) {
            gradeOptionsHtml += `<optgroup label="📋 Mis Grados Asignados (${currentUser.name})">`;
            uniqueGrades.forEach(g => {
                gradeOptionsHtml += `<option value="${g.code}">${g.name} (${g.section}) — ${g.career}</option>`;
            });
            gradeOptionsHtml += `</optgroup>`;
        } else {
            // Si el docente aún no tiene cátedras directas, mostrar todos los grados para facilitar registro
            (STATE.gradesList || []).forEach(g => {
                gradeOptionsHtml += `<option value="${g.code}">${g.name} (${g.section}) — ${g.career}</option>`;
            });
        }
    } else if (isDirectorOrAdmin && activeTeacherObj) {
        // SUPERVISIÓN POR MAESTRO ESPECÍFICO
        const teacherClasses = (STATE.pensum || []).filter(p => 
            p.teacherId === activeTeacherObj.id || 
            (p.teacher && p.teacher.toLowerCase() === activeTeacherObj.name.toLowerCase()) ||
            (activeTeacherObj.name && p.teacher && p.teacher.toLowerCase().includes(activeTeacherObj.name.toLowerCase()))
        );

        const uniqueGrades = new Map();
        teacherClasses.forEach(c => {
            const key = c.gradeCode || c.grade;
            if (!uniqueGrades.has(key)) {
                uniqueGrades.set(key, {
                    code: key,
                    name: c.grade,
                    section: c.section || 'A',
                    career: c.career || 'Perito Contador'
                });
            }
        });

        if (uniqueGrades.size > 0) {
            gradeOptionsHtml += `<optgroup label="👨‍🏫 Grados A Cargo de: ${activeTeacherObj.name}">`;
            uniqueGrades.forEach(g => {
                gradeOptionsHtml += `<option value="${g.code}">${g.name} (${g.section}) — ${g.career}</option>`;
            });
            gradeOptionsHtml += `</optgroup>`;
        } else {
            gradeOptionsHtml = `<option value="">-- El catedrático ${activeTeacherObj.name} no posee clases asignadas --</option>`;
        }
    } else {
        // MODO GENERAL POR GRADO: DIRECCIÓN TIENE ACCESO A TODOS LOS 12 GRADOS Y SECCIONES
        gradeOptionsHtml += `<optgroup label="⭐ General por Grado y Sección (Todos los Maestros)">`;
        (STATE.gradesList || []).forEach(g => {
            gradeOptionsHtml += `<option value="${g.code}">${g.name} (${g.section}) — ${g.career}</option>`;
        });
        gradeOptionsHtml += `</optgroup>`;
    }

    gradeSelect.innerHTML = gradeOptionsHtml;

    if (!resetSelection && currentSelectedGrade && Array.from(gradeSelect.options || []).some(o => o.value === currentSelectedGrade)) {
        gradeSelect.value = currentSelectedGrade;
    } else if (gradeSelect.options && gradeSelect.options.length > 0) {
        gradeSelect.selectedIndex = 0;
    }

    updateAttendanceCoursesList();
}

function onAttendanceGradeChange() {
    updateAttendanceCoursesList();
    loadAttendanceList();
}

function updateAttendanceCoursesList() {
    const gradeSelect = document.getElementById('attendanceGradeSelect');
    const courseSelect = document.getElementById('attendanceCourseSelect');
    const teacherSelect = document.getElementById('attendanceTeacherSelect');
    if (!gradeSelect || !courseSelect) return;

    const selGrade = gradeSelect.value;
    const currentUser = STATE.currentUser || STATE.users[0];
    const isDocente = (STATE.currentRole === 'docente');
    const isDirectorOrAdmin = (STATE.currentRole === 'director' || STATE.currentRole === 'admin' || STATE.currentRole === 'secretaria');
    const activeTeacherId = teacherSelect ? teacherSelect.value : '';
    const activeTeacherObj = (STATE.users || []).find(u => u.id === activeTeacherId);

    const qGradeObj = (STATE.gradesList || []).find(g => g.code === selGrade || g.id === selGrade || g.name === selGrade);
    const rawQ = `${selGrade || ''} ${qGradeObj ? (qGradeObj.name + ' ' + qGradeObj.section) : ''}`.toUpperCase();
    let qGradeNum = 0;
    if (rawQ.includes('6') || rawQ.includes('SEXTO') || rawQ.includes('6TO')) qGradeNum = 6;
    else if (rawQ.includes('5') || rawQ.includes('QUINTO') || rawQ.includes('5TO')) qGradeNum = 5;
    else if (rawQ.includes('4') || rawQ.includes('CUARTO') || rawQ.includes('4TO')) qGradeNum = 4;
    const qSec = getCleanSectionLetter(qGradeObj ? qGradeObj.section : selGrade);

    let coursesHtml = `<option value="GENERAL">📑 Control General de Asistencia (Jornada Diaria)</option>`;
    
    let matchingPensum = (STATE.pensum || []).filter(p => {
        const rawP = `${p.grade || ''} ${p.gradeCode || ''}`.toUpperCase();
        let pGradeNum = 0;
        if (rawP.includes('6') || rawP.includes('SEXTO') || rawP.includes('6TO')) pGradeNum = 6;
        else if (rawP.includes('5') || rawP.includes('QUINTO') || rawP.includes('5TO')) pGradeNum = 5;
        else if (rawP.includes('4') || rawP.includes('CUARTO') || rawP.includes('4TO')) pGradeNum = 4;
        const pSec = getCleanSectionLetter(p.section || p.gradeCode || rawP);

        if (qGradeNum > 0 && pGradeNum > 0 && qGradeNum !== pGradeNum) return false;
        if (qSec && pSec && qSec !== pSec) return false;
        return true;
    });

    if (isDocente && currentUser && !isDirectorOrAdmin) {
        matchingPensum = matchingPensum.filter(p => 
            p.teacherId === currentUser.id || 
            (p.teacher && p.teacher.toLowerCase() === currentUser.name.toLowerCase()) ||
            (currentUser.name && p.teacher && p.teacher.toLowerCase().includes(currentUser.name.toLowerCase()))
        );
    } else if (isDirectorOrAdmin && activeTeacherObj) {
        matchingPensum = matchingPensum.filter(p => 
            p.teacherId === activeTeacherObj.id || 
            (p.teacher && p.teacher.toLowerCase() === activeTeacherObj.name.toLowerCase()) ||
            (activeTeacherObj.name && p.teacher && p.teacher.toLowerCase().includes(activeTeacherObj.name.toLowerCase()))
        );
    }

    if (matchingPensum.length > 0) {
        const groupTitle = (isDirectorOrAdmin && activeTeacherObj) 
            ? `📚 Cátedras de ${activeTeacherObj.name}`
            : (isDirectorOrAdmin ? '📚 Todas las Clases Asignadas a este Grado' : '📚 Mis Clases Asignadas');

        coursesHtml += `<optgroup label="${groupTitle}">`;
        matchingPensum.forEach(p => {
            const teacherLabel = p.teacher ? ` — Catedrático: ${p.teacher}` : ' (Sin docente)';
            coursesHtml += `<option value="${p.id}">📘 ${p.subject}${isDirectorOrAdmin ? teacherLabel : ''}</option>`;
        });
        coursesHtml += `</optgroup>`;
    }

    courseSelect.innerHTML = coursesHtml;
}

function getAttendanceRecordKey(gradeCode, month, courseId) {
    const cycleKey = STATE.activeCycle || '2026';
    if (courseId && courseId !== 'GENERAL') {
        return `${cycleKey}_M${month}_${gradeCode}_${courseId}`;
    }
    return `${cycleKey}_M${month}_${gradeCode}`;
}

function loadAttendanceList() {
    const gradeSelect = document.getElementById('attendanceGradeSelect');
    const monthSelect = document.getElementById('attendanceMonthSelect');
    const courseSelect = document.getElementById('attendanceCourseSelect');
    const head = document.getElementById('attendanceExcelGridHead');
    const body = document.getElementById('attendanceExcelGridBody');
    const foot = document.getElementById('attendanceExcelGridFoot');
    const statsSummary = document.getElementById('attendanceStatsSummary');
    const directorBanner = document.getElementById('attendanceDirectorBanner');
    const currentTeacherBadge = document.getElementById('attendanceCurrentTeacherBadge');

    if (!gradeSelect || !head || !body) return;

    if (!gradeSelect.options || gradeSelect.options.length === 0 || gradeSelect.innerHTML.includes('Sin grados registrados')) {
        populateAttendanceSelects(false);
    }

    const gradeCode = gradeSelect.value;
    const month = parseInt(monthSelect ? monthSelect.value : '8') || 8;
    const courseId = courseSelect ? courseSelect.value : 'GENERAL';
    const year = 2026;
    const daysInMonth = new Date(year, month, 0).getDate();
    const dayNames = ['D', 'L', 'M', 'M', 'J', 'V', 'S'];

    const isDirectorOrAdmin = (STATE.currentRole === 'director' || STATE.currentRole === 'admin' || STATE.currentRole === 'secretaria');

    // Identificar asignación de curso
    let currentCourseObj = null;
    if (courseId && courseId !== 'GENERAL') {
        currentCourseObj = (STATE.pensum || []).find(p => p.id === courseId);
    }

    if (currentTeacherBadge) {
        if (currentCourseObj && currentCourseObj.teacher) {
            currentTeacherBadge.innerHTML = `<i class="fa-solid fa-chalkboard-user"></i> Catedrático: <strong>${currentCourseObj.teacher}</strong>`;
            currentTeacherBadge.style.display = 'inline-block';
        } else if (isDirectorOrAdmin) {
            currentTeacherBadge.innerHTML = `<i class="fa-solid fa-school"></i> Monitoreo Institucional Completo`;
            currentTeacherBadge.style.display = 'inline-block';
        } else {
            currentTeacherBadge.style.display = 'none';
        }
    }

    // 1. GENERAR ENCABEZADO DE DÍAS (1 AL FIN DE MES)
    let thDaysHtml = '';
    for (let day = 1; day <= daysInMonth; day++) {
        const dObj = new Date(year, month - 1, day);
        const dayOfWeek = dayNames[dObj.getDay()];
        const isWeekend = (dObj.getDay() === 0 || dObj.getDay() === 6);
        const weekendClass = isWeekend ? 'col-day-weekend' : '';
        thDaysHtml += `
            <th class="col-day ${weekendClass}" title="${dObj.toLocaleDateString('es-GT', { weekday: 'long', day: 'numeric', month: 'long' })}">
                <div class="day-letter">${dayOfWeek}</div>
                <div class="day-number">${day}</div>
            </th>
        `;
    }

    head.innerHTML = `
        <tr>
            <th class="col-num" rowspan="2">No.</th>
            <th class="col-carne" rowspan="2">Código Personal</th>
            <th class="col-name" rowspan="2">Apellidos y Nombres</th>
            <th colspan="${daysInMonth}" class="col-month-header" style="background:#15803d; color:#fff; text-align:center; font-weight:800; font-size:0.85rem; padding:4px;">
                <i class="fa-regular fa-calendar-days"></i> DÍAS DEL MES DE ${((document.getElementById('attendanceMonthSelect')?.options[document.getElementById('attendanceMonthSelect')?.selectedIndex]?.text) || 'Agosto').toUpperCase()} (CICLO ${year})
            </th>
            <th colspan="4" style="background:#0f172a; color:#fff; text-align:center; font-size:0.8rem; padding:4px;">RESUMEN</th>
            <th class="col-stat" rowspan="2" style="background:#0f172a; color:#fff;">Total</th>
            <th class="col-pct" rowspan="2" style="background:#0284c7; color:#fff;">% Asistencia</th>
        </tr>
        <tr>
            ${thDaysHtml}
            <th class="col-stat col-stat-p" title="Total Asistencias (Presente)">P</th>
            <th class="col-stat col-stat-a" title="Total Faltas (Ausente)">A</th>
            <th class="col-stat col-stat-j" title="Total Justificaciones">J</th>
            <th class="col-stat col-stat-t" title="Total Tardanzas">T</th>
        </tr>
    `;

    // 2. OBTENER ESTUDIANTES DEL GRADO Y SECCIÓN CON FILTRO ROBUSTO
    const qGradeObj = (STATE.gradesList || []).find(g => g.code === gradeCode || g.id === gradeCode || g.name === gradeCode);
    const rawQ = `${gradeCode || ''} ${qGradeObj ? (qGradeObj.name + ' ' + qGradeObj.section) : ''}`.toUpperCase();
    let qGradeNum = 0;
    if (rawQ.includes('6') || rawQ.includes('SEXTO') || rawQ.includes('6TO')) qGradeNum = 6;
    else if (rawQ.includes('5') || rawQ.includes('QUINTO') || rawQ.includes('5TO')) qGradeNum = 5;
    else if (rawQ.includes('4') || rawQ.includes('CUARTO') || rawQ.includes('4TO')) qGradeNum = 4;
    const qSec = getCleanSectionLetter(qGradeObj ? qGradeObj.section : gradeCode);

    const students = (STATE.students || []).filter(s => {
        if (!isStudentActive(s)) return false;
        const rawS = `${s.grade || ''} ${s.gradeCode || ''} ${s.gradeLabel || ''}`.toUpperCase();
        let sGradeNum = 0;
        if (rawS.includes('6') || rawS.includes('SEXTO') || rawS.includes('6TO')) sGradeNum = 6;
        else if (rawS.includes('5') || rawS.includes('QUINTO') || rawS.includes('5TO')) sGradeNum = 5;
        else if (rawS.includes('4') || rawS.includes('CUARTO') || rawS.includes('4TO')) sGradeNum = 4;
        const sSec = getCleanSectionLetter(s.section || s.gradeCode || s.gradeLabel || rawS);

        return (qGradeNum === sGradeNum) && (qSec === sSec);
    }).sort((a, b) => (a.fullName || (a.lastName + ' ' + a.firstName)).localeCompare(b.fullName || (b.lastName + ' ' + b.firstName)));

    if (students.length === 0) {
        body.innerHTML = `<tr><td colspan="${daysInMonth + 8}" style="text-align:center; padding:35px; color:#64748b; font-size:0.95rem;">
            <i class="fa-solid fa-users-slash" style="font-size:2rem; color:#cbd5e1; display:block; margin-bottom:8px;"></i>
            No hay estudiantes activos registrados en este grado y sección para el ciclo activo.
        </td></tr>`;
        if (foot) foot.innerHTML = '';
        if (statsSummary) statsSummary.innerHTML = '';
        return;
    }

    // 3. RECUPERAR REGISTROS DE ASISTENCIA
    if (!STATE.attendanceRecords) STATE.attendanceRecords = {};
    const recordKey = getAttendanceRecordKey(gradeCode, month, courseId);
    const monthData = STATE.attendanceRecords[recordKey] || {};

    let tbodyHtml = '';
    let dayPresentTotals = new Array(daysInMonth + 1).fill(0);
    let dayAbsentTotals = new Array(daysInMonth + 1).fill(0);
    let totalClassLogs = 0;
    let totalClassPresent = 0;

    students.forEach((s, idx) => {
        const sRecords = monthData[s.id] || {};
        let pCount = 0, aCount = 0, jCount = 0, tCount = 0;
        let cellsHtml = '';
        const studentFullName = s.fullName || `${s.lastName || ''}, ${s.firstName || s.name || ''}`.trim();
        const isAbsentStatus = (s.status === 'Ausente');

        for (let day = 1; day <= daysInMonth; day++) {
            const dObj = new Date(year, month - 1, day);
            const isWeekend = (dObj.getDay() === 0 || dObj.getDay() === 6);
            const weekendClass = isWeekend ? 'col-day-weekend' : '';

            if (isWeekend) {
                cellsHtml += `<td class="att-cell ${weekendClass}" data-weekend="true">-</td>`;
            } else {
                let rawVal = sRecords[day];
                // Las casillas de asistencia aparecen en blanco inicialmente; al marcarse muestran su letra y color asignado
                let val = (rawVal !== undefined && rawVal !== null && rawVal !== '') ? rawVal : '';

                let cellClass = 'att-val-empty';
                if (val === 'P') {
                    cellClass = 'att-val-p att-val-P';
                    pCount++;
                    dayPresentTotals[day]++;
                } else if (val === 'A') {
                    cellClass = 'att-val-a att-val-A';
                    aCount++;
                    dayAbsentTotals[day]++;
                } else if (val === 'J') {
                    cellClass = 'att-val-j att-val-J';
                    jCount++;
                } else if (val === 'T') {
                    cellClass = 'att-val-t att-val-T';
                    tCount++;
                }

                cellsHtml += `
                    <td class="att-cell ${cellClass}" 
                        data-student-id="${s.id}" 
                        data-day="${day}" 
                        onclick="toggleAttendanceCell('${s.id}', ${day})"
                        title="${studentFullName} — Día ${day}: ${val ? (val === 'P' ? 'PRESENTE' : (val === 'A' ? 'AUSENTE / FALTA' : (val === 'J' ? 'JUSTIFICADO' : 'TARDANZA'))) : 'Sin registrar (Haga clic para marcar P)'}">
                        ${val}
                    </td>
                `;
            }
        }

        const totalLogged = pCount + aCount + jCount + tCount;
        totalClassPresent += (pCount + jCount + (tCount * 0.5));
        totalClassLogs += (totalLogged > 0 ? totalLogged : 0);

        // Cálculo de porcentaje individual de asistencia horizontal
        let pct = 100;
        if (totalLogged > 0) {
            pct = Math.round(((pCount + jCount + (tCount * 0.5)) / totalLogged) * 100);
        }

        let barColor = '#16a34a';
        let badgeStyle = 'background:#dcfce7; color:#15803d; border:1px solid #86efac;';
        if (pct < 85 && pct >= 70) {
            barColor = '#ca8a04';
            badgeStyle = 'background:#fef9c3; color:#ca8a04; border:1px solid #fde047;';
        } else if (pct < 70) {
            barColor = '#dc2626';
            badgeStyle = 'background:#fee2e2; color:#dc2626; border:1px solid #fca5a5;';
        }

        let statusTag = '';
        if (isAbsentStatus) {
            statusTag = `<span class="badge" style="font-size:0.68rem; margin-left:5px; background:#fef3c7; color:#92400e; border:1px solid #fcd34d;">Ausente</span>`;
        }

        tbodyHtml += `
            <tr data-student-id="${s.id}">
                <td class="col-num">${idx + 1}</td>
                <td class="col-carne"><code>${s.personalCode || s.cui || s.carne || 'S/C'}</code></td>
                <td class="col-name" title="${studentFullName}">
                    <strong>${studentFullName}</strong>${statusTag}
                </td>
                ${cellsHtml}
                <td class="col-stat col-stat-p" id="statP_${s.id}">${pCount}</td>
                <td class="col-stat col-stat-a" id="statA_${s.id}">${aCount}</td>
                <td class="col-stat col-stat-j" id="statJ_${s.id}">${jCount}</td>
                <td class="col-stat col-stat-t" id="statT_${s.id}">${tCount}</td>
                <td class="col-stat" id="statTot_${s.id}" style="font-weight:700;">${totalLogged}</td>
                <td class="col-pct" id="pctCol_${s.id}">
                    <div class="att-pct-container" title="Asistencia Horizontal: ${pct}% (${pCount} Presentes / ${totalLogged} Días)">
                        <div class="att-pct-bar-bg">
                            <div class="att-pct-bar-fill" style="width:${pct}%; background:${barColor};"></div>
                        </div>
                        <span class="att-pct-badge" style="${badgeStyle}">
                            ${pct}%
                        </span>
                    </div>
                </td>
            </tr>
        `;
    });

    body.innerHTML = tbodyHtml;

    // 4. GENERAR FILAS DE TOTALES Y PORCENTAJES AL FINAL DE LA TABLA (TFOOT)
    let totalPresentRow = `
        <tr class="summary-row">
            <td colspan="3" style="text-align:right; padding-right:12px; font-weight:800;">
                <i class="fa-solid fa-check"></i> TOTAL ASISTENCIAS DIARIAS (P):
            </td>
    `;
    for (let day = 1; day <= daysInMonth; day++) {
        const dObj = new Date(year, month - 1, day);
        const isWeekend = (dObj.getDay() === 0 || dObj.getDay() === 6);
        totalPresentRow += `<td style="${isWeekend ? 'background:#091e12;' : ''}">${isWeekend ? '-' : dayPresentTotals[day]}</td>`;
    }
    const globalSumP = dayPresentTotals.reduce((a, b) => a + b, 0);
    const globalSumA = dayAbsentTotals.reduce((a, b) => a + b, 0);
    const globalSumJ = students.reduce((acc, s) => {
        const sRecords = monthData[s.id] || {};
        return acc + Object.values(sRecords).filter(v => v === 'J').length;
    }, 0);
    const globalSumT = students.reduce((acc, s) => {
        const sRecords = monthData[s.id] || {};
        return acc + Object.values(sRecords).filter(v => v === 'T').length;
    }, 0);
    const globalTotalLogged = globalSumP + globalSumA + globalSumJ + globalSumT;

    totalPresentRow += `
        <td class="col-stat-p" style="background:#15803d !important; color:#fff !important;">${globalSumP}</td>
        <td class="col-stat-a" style="background:#b91c1c !important; color:#fff !important;">${globalSumA}</td>
        <td class="col-stat-j" style="background:#ea580c !important; color:#fff !important;">${globalSumJ}</td>
        <td class="col-stat-t" style="background:#0284c7 !important; color:#fff !important;">${globalSumT}</td>
        <td style="background:#0f172a !important; color:#ffffff !important; font-weight:800;">${globalTotalLogged}</td>
        <td style="background:#0f172a !important; color:#38bdf8 !important; font-size:0.82rem; font-weight:800; text-align:center;">
            TOTALES
        </td>
    </tr>`;

    const overallPct = totalClassLogs > 0 ? Math.round((totalClassPresent / totalClassLogs) * 100) : 100;
    const overallBarColor = overallPct >= 85 ? '#4ade80' : (overallPct >= 70 ? '#facc15' : '#f87171');

    let overallRow = `
        <tr class="summary-row-pct">
            <td colspan="${daysInMonth + 3}" style="text-align:right; padding-right:12px; font-weight:800;">
                <i class="fa-solid fa-chart-pie"></i> PROMEDIO HORIZONTAL DE ASISTENCIA DEL GRADO:
            </td>
            <td colspan="4" style="text-align:center; font-weight:800; font-size:0.8rem; background:#1e293b !important; color:#94a3b8 !important;">
                ${students.length} Alumnos
            </td>
            <td style="text-align:center; font-weight:800; background:#1e293b !important; color:#ffffff !important;">
                ${globalTotalLogged} Regs
            </td>
            <td style="background:#0284c7 !important; color:#ffffff !important; font-size:0.88rem; font-weight:900; letter-spacing:0.5px; white-space:nowrap; text-align:center;">
                <div style="display:flex; flex-direction:row; align-items:center; justify-content:center; gap:6px;">
                    <div style="width:36px; height:7px; background:rgba(255,255,255,0.25); border-radius:999px; overflow:hidden;">
                        <div style="width:${overallPct}%; height:100%; background:${overallBarColor}; border-radius:999px;"></div>
                    </div>
                    <span>${overallPct}%</span>
                </div>
            </td>
        </tr>`;

    if (foot) {
        foot.innerHTML = totalPresentRow + overallRow;
    }

    if (statsSummary) {
        statsSummary.innerHTML = `
            <div class="attendance-stats-horizontal">
                <span class="att-stat-card-horizontal">
                    <i class="fa-solid fa-users" style="color:var(--brand-green);"></i>
                    <span><strong>${students.length}</strong> Alumnos</span>
                </span>
                <span class="att-stat-card-horizontal">
                    <i class="fa-solid fa-check" style="color:#16a34a;"></i>
                    <span>Total P: <strong>${globalSumP}</strong></span>
                </span>
                <span class="att-stat-card-horizontal">
                    <i class="fa-solid fa-xmark" style="color:#dc2626;"></i>
                    <span>Total A: <strong>${globalSumA}</strong></span>
                </span>
                <span class="att-stat-card-horizontal" style="background:#f0fdf4; border-color:#86efac;">
                    <i class="fa-solid fa-chart-line" style="color:#15803d;"></i>
                    <span>% Asistencia Promedio:</span>
                    <div class="att-global-pct-bar">
                        <div style="width:${overallPct}%; height:100%; background:${overallPct >= 85 ? '#16a34a' : (overallPct >= 70 ? '#ca8a04' : '#dc2626')}; border-radius:999px;"></div>
                    </div>
                    <strong style="color:#15803d; font-size:0.92rem;">${overallPct}%</strong>
                </span>
            </div>
        `;
    }
}

function toggleAttendanceCell(studentId, day) {
    const gradeSelect = document.getElementById('attendanceGradeSelect');
    const monthSelect = document.getElementById('attendanceMonthSelect');
    const courseSelect = document.getElementById('attendanceCourseSelect');
    if (!gradeSelect || !monthSelect) return;

    const gradeCode = gradeSelect.value;
    const month = parseInt(monthSelect.value) || 8;
    const courseId = courseSelect ? courseSelect.value : 'GENERAL';

    if (!STATE.attendanceRecords) STATE.attendanceRecords = {};
    const recordKey = getAttendanceRecordKey(gradeCode, month, courseId);
    if (!STATE.attendanceRecords[recordKey]) STATE.attendanceRecords[recordKey] = {};
    if (!STATE.attendanceRecords[recordKey][studentId]) STATE.attendanceRecords[recordKey][studentId] = {};

    const cur = STATE.attendanceRecords[recordKey][studentId][day] || '';
    let next = 'P';
    if (!cur || cur === '') next = 'P';
    else if (cur === 'P') next = 'A';
    else if (cur === 'A') next = 'J';
    else if (cur === 'J') next = 'T';
    else if (cur === 'T') next = '';
    else next = 'P';

    if (next) {
        STATE.attendanceRecords[recordKey][studentId][day] = next;
    } else {
        delete STATE.attendanceRecords[recordKey][studentId][day];
    }

    // Actualizar visualmente la celda de inmediato con su letra y color asignado
    const td = document.querySelector(`td[data-student-id="${studentId}"][data-day="${day}"]`);
    if (td) {
        td.className = next ? `att-cell att-val-${next.toLowerCase()} att-val-${next.toUpperCase()}` : 'att-cell att-val-empty';
        td.textContent = next;
        td.title = next ? `Día ${day}: ${next === 'P' ? 'PRESENTE' : (next === 'A' ? 'AUSENTE / FALTA' : (next === 'J' ? 'JUSTIFICADO' : 'TARDANZA'))} (Haga clic para alternar P/A/J/T)` : `Día ${day}: Sin registrar (Haga clic para marcar P)`;
    }

    saveAttendanceRecords(false);
    updateAttendanceLiveStats();
}

function updateAttendanceLiveStats() {
    const gradeSelect = document.getElementById('attendanceGradeSelect');
    const monthSelect = document.getElementById('attendanceMonthSelect');
    const foot = document.getElementById('attendanceExcelGridFoot');
    const statsSummary = document.getElementById('attendanceStatsSummary');
    if (!gradeSelect || !monthSelect) return;

    const month = parseInt(monthSelect.value) || 8;
    const year = 2026;
    const daysInMonth = new Date(year, month, 0).getDate();

    const rows = document.querySelectorAll('#attendanceExcelGridBody tr[data-student-id]');
    let dayPresentTotals = new Array(daysInMonth + 1).fill(0);
    let dayAbsentTotals = new Array(daysInMonth + 1).fill(0);
    let dayJustTotals = new Array(daysInMonth + 1).fill(0);
    let dayTardyTotals = new Array(daysInMonth + 1).fill(0);
    let totalClassLogs = 0;
    let totalClassPresent = 0;

    rows.forEach(tr => {
        const studentId = tr.getAttribute('data-student-id');
        const cells = tr.querySelectorAll('td.att-cell:not([data-weekend="true"])');
        let pCount = 0, aCount = 0, jCount = 0, tCount = 0;

        cells.forEach(td => {
            const day = parseInt(td.getAttribute('data-day')) || 0;
            const text = (td.textContent || '').trim();
            if (text === 'P') {
                pCount++;
                if (day > 0) dayPresentTotals[day]++;
            } else if (text === 'A') {
                aCount++;
                if (day > 0) dayAbsentTotals[day]++;
            } else if (text === 'J') {
                jCount++;
                if (day > 0) dayJustTotals[day]++;
            } else if (text === 'T') {
                tCount++;
                if (day > 0) dayTardyTotals[day]++;
            }
        });

        const totalLogged = pCount + aCount + jCount + tCount;
        totalClassPresent += (pCount + jCount + (tCount * 0.5));
        totalClassLogs += (totalLogged > 0 ? totalLogged : 0);

        let pct = 100;
        if (totalLogged > 0) {
            pct = Math.round(((pCount + jCount + (tCount * 0.5)) / totalLogged) * 100);
        }

        let barColor = '#16a34a';
        let badgeStyle = 'background:#dcfce7; color:#15803d; border:1px solid #86efac;';
        if (pct < 85 && pct >= 70) {
            barColor = '#ca8a04';
            badgeStyle = 'background:#fef9c3; color:#ca8a04; border:1px solid #fde047;';
        } else if (pct < 70) {
            barColor = '#dc2626';
            badgeStyle = 'background:#fee2e2; color:#dc2626; border:1px solid #fca5a5;';
        }

        const pEl = document.getElementById(`statP_${studentId}`);
        if (pEl) pEl.textContent = pCount;
        const aEl = document.getElementById(`statA_${studentId}`);
        if (aEl) aEl.textContent = aCount;
        const jEl = document.getElementById(`statJ_${studentId}`);
        if (jEl) jEl.textContent = jCount;
        const tEl = document.getElementById(`statT_${studentId}`);
        if (tEl) tEl.textContent = tCount;
        const totEl = document.getElementById(`statTot_${studentId}`);
        if (totEl) totEl.textContent = totalLogged;

        const pctEl = document.getElementById(`pctCol_${studentId}`);
        if (pctEl) {
            pctEl.innerHTML = `
                <div class="att-pct-container" title="Asistencia Horizontal: ${pct}% (${pCount} Presentes / ${totalLogged} Días)">
                    <div class="att-pct-bar-bg">
                        <div class="att-pct-bar-fill" style="width:${pct}%; background:${barColor};"></div>
                    </div>
                    <span class="att-pct-badge" style="${badgeStyle}">
                        ${pct}%
                    </span>
                </div>
            `;
        }
    });

    const globalSumP = dayPresentTotals.reduce((a, b) => a + b, 0);
    const globalSumA = dayAbsentTotals.reduce((a, b) => a + b, 0);
    const globalSumJ = dayJustTotals.reduce((a, b) => a + b, 0);
    const globalSumT = dayTardyTotals.reduce((a, b) => a + b, 0);
    const globalTotalLogged = globalSumP + globalSumA + globalSumJ + globalSumT;

    let totalPresentRow = `
        <tr class="summary-row">
            <td colspan="3" style="text-align:right; padding-right:12px; font-weight:800;">
                <i class="fa-solid fa-check"></i> TOTAL ASISTENCIAS DIARIAS (P):
            </td>
    `;
    for (let day = 1; day <= daysInMonth; day++) {
        const dObj = new Date(year, month - 1, day);
        const isWeekend = (dObj.getDay() === 0 || dObj.getDay() === 6);
        totalPresentRow += `<td style="${isWeekend ? 'background:#091e12;' : ''}">${isWeekend ? '-' : dayPresentTotals[day]}</td>`;
    }
    totalPresentRow += `
        <td class="col-stat-p" style="background:#15803d !important; color:#fff !important;">${globalSumP}</td>
        <td class="col-stat-a" style="background:#b91c1c !important; color:#fff !important;">${globalSumA}</td>
        <td class="col-stat-j" style="background:#ea580c !important; color:#fff !important;">${globalSumJ}</td>
        <td class="col-stat-t" style="background:#0284c7 !important; color:#fff !important;">${globalSumT}</td>
        <td style="background:#0f172a !important; color:#ffffff !important; font-weight:800;">${globalTotalLogged}</td>
        <td style="background:#0f172a !important; color:#38bdf8 !important; font-size:0.82rem; font-weight:800; text-align:center;">
            TOTALES
        </td>
    </tr>`;

    const overallPct = totalClassLogs > 0 ? Math.round((totalClassPresent / totalClassLogs) * 100) : 100;
    const overallBarColor = overallPct >= 85 ? '#4ade80' : (overallPct >= 70 ? '#facc15' : '#f87171');

    let overallRow = `
        <tr class="summary-row-pct">
            <td colspan="${daysInMonth + 3}" style="text-align:right; padding-right:12px; font-weight:800;">
                <i class="fa-solid fa-chart-pie"></i> PROMEDIO HORIZONTAL DE ASISTENCIA DEL GRADO:
            </td>
            <td colspan="4" style="text-align:center; font-weight:800; font-size:0.8rem; background:#1e293b !important; color:#94a3b8 !important;">
                ${rows.length} Alumnos
            </td>
            <td style="text-align:center; font-weight:800; background:#1e293b !important; color:#ffffff !important;">
                ${globalTotalLogged} Regs
            </td>
            <td style="background:#0284c7 !important; color:#ffffff !important; font-size:0.88rem; font-weight:900; letter-spacing:0.5px; white-space:nowrap; text-align:center;">
                <div style="display:flex; flex-direction:row; align-items:center; justify-content:center; gap:6px;">
                    <div style="width:36px; height:7px; background:rgba(255,255,255,0.25); border-radius:999px; overflow:hidden;">
                        <div style="width:${overallPct}%; height:100%; background:${overallBarColor}; border-radius:999px;"></div>
                    </div>
                    <span>${overallPct}%</span>
                </div>
            </td>
        </tr>`;

    if (foot) {
        foot.innerHTML = totalPresentRow + overallRow;
    }

    if (statsSummary) {
        statsSummary.innerHTML = `
            <div class="attendance-stats-horizontal">
                <span class="att-stat-card-horizontal">
                    <i class="fa-solid fa-users" style="color:var(--brand-green);"></i>
                    <span><strong>${rows.length}</strong> Alumnos</span>
                </span>
                <span class="att-stat-card-horizontal">
                    <i class="fa-solid fa-check" style="color:#16a34a;"></i>
                    <span>Total P: <strong>${globalSumP}</strong></span>
                </span>
                <span class="att-stat-card-horizontal">
                    <i class="fa-solid fa-xmark" style="color:#dc2626;"></i>
                    <span>Total A: <strong>${globalSumA}</strong></span>
                </span>
                <span class="att-stat-card-horizontal" style="background:#f0fdf4; border-color:#86efac;">
                    <i class="fa-solid fa-chart-line" style="color:#15803d;"></i>
                    <span>% Asistencia Promedio:</span>
                    <div class="att-global-pct-bar">
                        <div style="width:${overallPct}%; height:100%; background:${overallPct >= 85 ? '#16a34a' : (overallPct >= 70 ? '#ca8a04' : '#dc2626')}; border-radius:999px;"></div>
                    </div>
                    <strong style="color:#15803d; font-size:0.92rem;">${overallPct}%</strong>
                </span>
            </div>
        `;
    }
}

function markAllPresentToday() {
    const gradeSelect = document.getElementById('attendanceGradeSelect');
    const monthSelect = document.getElementById('attendanceMonthSelect');
    const courseSelect = document.getElementById('attendanceCourseSelect');
    if (!gradeSelect || !monthSelect) return;

    const gradeCode = gradeSelect.value;
    const month = parseInt(monthSelect.value) || 8;
    const courseId = courseSelect ? courseSelect.value : 'GENERAL';

    const today = new Date();
    const todayDay = today.getDate();
    const todayMonth = today.getMonth() + 1;

    const targetDay = (month === todayMonth) ? todayDay : 1;

    if (!STATE.attendanceRecords) STATE.attendanceRecords = {};
    const recordKey = getAttendanceRecordKey(gradeCode, month, courseId);
    if (!STATE.attendanceRecords[recordKey]) STATE.attendanceRecords[recordKey] = {};

    // Obtener estudiantes del grado
    const qGradeObj = (STATE.gradesList || []).find(g => g.code === gradeCode || g.id === gradeCode || g.name === gradeCode);
    const rawQ = `${gradeCode || ''} ${qGradeObj ? (qGradeObj.name + ' ' + qGradeObj.section) : ''}`.toUpperCase();
    let qGradeNum = 0;
    if (rawQ.includes('6') || rawQ.includes('SEXTO') || rawQ.includes('6TO')) qGradeNum = 6;
    else if (rawQ.includes('5') || rawQ.includes('QUINTO') || rawQ.includes('5TO')) qGradeNum = 5;
    else if (rawQ.includes('4') || rawQ.includes('CUARTO') || rawQ.includes('4TO')) qGradeNum = 4;
    const qSec = getCleanSectionLetter(qGradeObj ? qGradeObj.section : gradeCode);

    const students = (STATE.students || []).filter(s => {
        if (!isStudentActive(s)) return false;
        const rawS = `${s.grade || ''} ${s.gradeCode || ''} ${s.gradeLabel || ''}`.toUpperCase();
        let sGradeNum = 0;
        if (rawS.includes('6') || rawS.includes('SEXTO') || rawS.includes('6TO')) sGradeNum = 6;
        else if (rawS.includes('5') || rawS.includes('QUINTO') || rawS.includes('5TO')) sGradeNum = 5;
        else if (rawS.includes('4') || rawS.includes('CUARTO') || rawS.includes('4TO')) sGradeNum = 4;
        const sSec = getCleanSectionLetter(s.section || s.gradeCode || s.gradeLabel || rawS);

        return (qGradeNum === sGradeNum) && (qSec === sSec);
    });

    students.forEach(s => {
        if (!STATE.attendanceRecords[recordKey][s.id]) STATE.attendanceRecords[recordKey][s.id] = {};
        STATE.attendanceRecords[recordKey][s.id][targetDay] = 'P';
    });

    saveAttendanceRecords(false);
    loadAttendanceList();
    showToast(`Se registraron ${students.length} asistencias en 'Presente' para el día ${targetDay}.`, 'success');
}

function saveAttendanceRecords(showToastMsg = true) {
    saveStateToLocalStorage();
    if (showToastMsg) {
        showToast('Planilla de asistencia guardada exitosamente en la base de datos.', 'success');
    }
}

function printAttendanceOfficialSheet(forcedIsBlank = null) {
    const gradeSelect = document.getElementById('attendanceGradeSelect');
    const monthSelect = document.getElementById('attendanceMonthSelect');
    const courseSelect = document.getElementById('attendanceCourseSelect');
    const teacherSelect = document.getElementById('attendanceTeacherSelect');

    const gradeCode = gradeSelect ? gradeSelect.value : '';
    const gradeText = gradeSelect && gradeSelect.selectedIndex >= 0 ? gradeSelect.options[gradeSelect.selectedIndex].text : 'Grado y Sección';
    const month = parseInt(monthSelect ? monthSelect.value : '8') || 8;
    const courseId = courseSelect ? courseSelect.value : 'GENERAL';
    const year = 2026;
    const daysInMonth = new Date(year, month, 0).getDate();
    const dayNames = ['D', 'L', 'M', 'M', 'J', 'V', 'S'];

    const monthNames = {
        1: 'Enero', 2: 'Febrero', 3: 'Marzo', 4: 'Abril', 5: 'Mayo', 6: 'Junio',
        7: 'Julio', 8: 'Agosto', 9: 'Septiembre', 10: 'Octubre', 11: 'Noviembre', 12: 'Diciembre'
    };

    // Determinar asignatura y catedrático
    let subjectTitle = 'Control General de Asistencia (Jornada Diaria)';
    let teacherName = 'Docente Titular';

    if (courseId && courseId !== 'GENERAL') {
        const targetPensum = (STATE.pensum || []).find(p => p.id === courseId);
        if (targetPensum) {
            subjectTitle = `${targetPensum.subject} (${targetPensum.grade} "${targetPensum.section || 'A'}")`;
            teacherName = targetPensum.teacher || (STATE.currentUser ? STATE.currentUser.name : 'Catedrático');
        }
    } else if (teacherSelect && teacherSelect.value) {
        const teacherObj = (STATE.users || []).find(u => u.id === teacherSelect.value);
        if (teacherObj) teacherName = teacherObj.name;
    } else if (STATE.currentUser) {
        teacherName = STATE.currentUser.name;
    }

    // Filtrar estudiantes con coincidencia perfecta de grado y sección
    const qGradeObj = (STATE.gradesList || []).find(g => g.code === gradeCode || g.id === gradeCode || g.name === gradeCode);
    const rawQ = `${gradeCode || ''} ${qGradeObj ? (qGradeObj.name + ' ' + qGradeObj.section) : ''}`.toUpperCase();
    let qGradeNum = 0;
    if (rawQ.includes('6') || rawQ.includes('SEXTO') || rawQ.includes('6TO')) qGradeNum = 6;
    else if (rawQ.includes('5') || rawQ.includes('QUINTO') || rawQ.includes('5TO')) qGradeNum = 5;
    else if (rawQ.includes('4') || rawQ.includes('CUARTO') || rawQ.includes('4TO')) qGradeNum = 4;
    const qSec = getCleanSectionLetter(qGradeObj ? qGradeObj.section : gradeCode);

    const students = (STATE.students || []).filter(s => {
        if (!isStudentActive(s)) return false;
        const rawS = `${s.grade || ''} ${s.gradeCode || ''} ${s.gradeLabel || ''}`.toUpperCase();
        let sGradeNum = 0;
        if (rawS.includes('6') || rawS.includes('SEXTO') || rawS.includes('6TO')) sGradeNum = 6;
        else if (rawS.includes('5') || rawS.includes('QUINTO') || rawS.includes('5TO')) sGradeNum = 5;
        else if (rawS.includes('4') || rawS.includes('CUARTO') || rawS.includes('4TO')) sGradeNum = 4;
        const sSec = getCleanSectionLetter(s.section || s.gradeCode || s.gradeLabel || rawS);

        return (qGradeNum === sGradeNum) && (qSec === sSec);
    }).sort((a, b) => (a.fullName || (a.lastName + ' ' + a.firstName)).localeCompare(b.fullName || (b.lastName + ' ' + b.firstName)));

    if (students.length === 0) {
        showToast("No hay estudiantes registrados en este grado para generar la planilla de asistencia.", "warning");
        return;
    }

    const recordKey = getAttendanceRecordKey(gradeCode, month, courseId);
    const monthData = (STATE.attendanceRecords && STATE.attendanceRecords[recordKey]) || {};

    let printWin = window.open('', '_blank');
    if (!printWin) {
        showToast("Habilite las ventanas emergentes en su navegador para imprimir.", "danger");
        return;
    }

    const h = STATE.schoolHeader || { schoolName: 'Escuela Nacional de Ciencias Comerciales', code: 'ENCCO Jutiapa', location: 'Jutiapa' };
    const capDate = new Date().toLocaleDateString('es-GT', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

    // Encabezado de días
    let thDaysHtml = '';
    for (let day = 1; day <= daysInMonth; day++) {
        const dObj = new Date(year, month - 1, day);
        const dayOfWeek = dayNames[dObj.getDay()];
        const isWeekend = (dObj.getDay() === 0 || dObj.getDay() === 6);
        const weekendClass = isWeekend ? 'background:#e2e8f0; color:#64748b;' : '';
        thDaysHtml += `
            <th style="width:20px; text-align:center; font-size:7.5pt; border:1px solid #0f172a; padding:3px 1px; ${weekendClass}">
                <div>${dayOfWeek}</div>
                <div>${day}</div>
            </th>
        `;
    }

    let tbodyRows = '';
    let dayPresentTotals = new Array(daysInMonth + 1).fill(0);
    let dayAbsentTotals = new Array(daysInMonth + 1).fill(0);

    students.forEach((s, idx) => {
        const sRecords = monthData[s.id] || {};
        let pCount = 0, aCount = 0, jCount = 0, tCount = 0;
        let dayCells = '';
        const studentFullName = s.fullName || `${s.lastName || ''}, ${s.firstName || s.name || ''}`.trim();

        for (let day = 1; day <= daysInMonth; day++) {
            const dObj = new Date(year, month - 1, day);
            const isWeekend = (dObj.getDay() === 0 || dObj.getDay() === 6);

            if (isWeekend) {
                dayCells += `<td style="background:#e2e8f0; text-align:center; color:#94a3b8; font-size:8pt; border:1px solid #64748b;">-</td>`;
            } else {
                let rawVal = sRecords[day];
                let val = (rawVal !== undefined && rawVal !== null && rawVal !== '') ? rawVal : '';

                let bg = '#ffffff';
                let fg = '#000000';
                if (val === 'P') { bg = '#dcfce7'; fg = '#15803d'; pCount++; dayPresentTotals[day]++; }
                else if (val === 'A') { bg = '#fee2e2'; fg = '#b91c1c'; aCount++; dayAbsentTotals[day]++; }
                else if (val === 'J') { bg = '#ffedd5'; fg = '#c2410c'; jCount++; }
                else if (val === 'T') { bg = '#e0f2fe'; fg = '#0369a1'; tCount++; }

                dayCells += `<td style="background:${bg}; color:${fg}; text-align:center; font-weight:bold; font-size:8pt; border:1px solid #64748b;">${val}</td>`;
            }
        }

        const totalLogged = pCount + aCount + jCount + tCount;
        const pct = totalLogged > 0 ? Math.round(((pCount + jCount + (tCount * 0.5)) / totalLogged) * 100) : 100;

        tbodyRows += `
            <tr style="${idx % 2 === 1 ? 'background-color:#f8fafc;' : ''}">
                <td style="text-align:center; font-weight:bold; border:1px solid #64748b; padding:4px 2px;">${idx + 1}</td>
                <td style="font-family:monospace; font-weight:bold; border:1px solid #64748b; padding:4px 4px; font-size:7.8pt;">${s.personalCode || s.cui || s.carne || 'S/C'}</td>
                <td style="font-weight:bold; border:1px solid #64748b; padding:4px 6px; white-space:nowrap; font-size:8.2pt;">${studentFullName}</td>
                ${dayCells}
                <td style="text-align:center; font-weight:bold; color:#15803d; border:1px solid #64748b; font-size:8pt;">${pCount}</td>
                <td style="text-align:center; font-weight:bold; color:#b91c1c; border:1px solid #64748b; font-size:8pt;">${aCount}</td>
                <td style="text-align:center; font-weight:bold; color:#c2410c; border:1px solid #64748b; font-size:8pt;">${jCount}</td>
                <td style="text-align:center; font-weight:bold; color:#0369a1; border:1px solid #64748b; font-size:8pt;">${tCount}</td>
                <td style="text-align:center; font-weight:bold; background:#f1f5f9; border:1px solid #64748b; font-size:8.5pt;">${pct}%</td>
            </tr>
        `;
    });

    const grandSumP = dayPresentTotals.reduce((a, b) => a + b, 0);
    const grandSumA = dayAbsentTotals.reduce((a, b) => a + b, 0);

    printWin.document.write(`
        <!DOCTYPE html>
        <html lang="es">
        <head>
            <meta charset="UTF-8">
            <title>Planilla Oficial de Asistencia - ${gradeText}</title>
            <style>
                @page { size: 13in 8.5in landscape; margin: 6mm 8mm; }
                body { font-family: 'Segoe UI', Arial, sans-serif; color: #000; background: #fff; line-height: 1.2; font-size: 8pt; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
                
                .official-header { border: 1.5px solid #15803d; border-radius: 4px; overflow: hidden; margin-bottom: 8px; }
                .top-banner { background: #15803d !important; color: #fff; display: flex; align-items: center; justify-content: space-between; padding: 6px 14px; }
                .top-banner img { height: 38px; width: auto; }
                .top-banner h1 { margin: 0; font-size: 13pt; font-weight: 900; color: #fff; text-transform: uppercase; }
                .sub-tag { font-size: 8pt; font-weight: 700; color: #bbf7d0; }
                
                .meta-bar { background: #f0fdf4; border-top: 1px solid #166534; padding: 4px 14px; display: flex; justify-content: space-between; font-size: 8.5pt; font-weight: 700; color: #166534; }
                
                .stat-table { width: 100%; border-collapse: collapse; margin-top: 6px; border: 1.5px solid #0f172a; font-size: 8pt; }
                .stat-table th { background: #15803d !important; color: #ffffff !important; border: 1px solid #0f172a; padding: 4px 2px; text-align: center; font-weight: 900; }
                
                .signatures { margin-top: 24px; display: flex; justify-content: space-around; text-align: center; }
                .sig-box { width: 220px; border-top: 1.5px solid #000; padding-top: 3px; font-size: 8pt; font-weight: bold; }
            </style>
        </head>
        <body>
            <div class="official-header">
                <div class="top-banner">
                    <div style="display:flex; align-items:center; gap:10px;">
                        <img src="logo.png" alt="Logo ENCCO" onerror="this.src='portada-comercio-principal.webp'">
                        <div>
                            <h1>${h.schoolName || 'ESCUELA NACIONAL DE CIENCIAS COMERCIALES'}</h1>
                            <div class="sub-tag">JUTIAPA — FUNDADA EN 1970 | CICLO ESCOLAR ${STATE.activeCycle || '2026'}</div>
                        </div>
                    </div>
                    <div style="text-align:right;">
                        <div style="font-size:11pt; font-weight:900; text-transform:uppercase;">PLANILLA OFICIAL DE ASISTENCIA</div>
                        <div style="font-size:8pt; color:#bbf7d0;">MES: ${monthNames[month].toUpperCase()} ${year}</div>
                    </div>
                </div>
                <div class="meta-bar">
                    <div><strong>Grado y Sección:</strong> ${gradeText}</div>
                    <div><strong>Asignatura:</strong> ${subjectTitle}</div>
                    <div><strong>Catedrático:</strong> ${teacherName}</div>
                    <div><strong>Total Alumnos:</strong> ${students.length}</div>
                </div>
            </div>

            <table class="stat-table">
                <thead>
                    <tr>
                        <th style="width:25px;" rowspan="2">No.</th>
                        <th style="width:75px;" rowspan="2">Código Personal</th>
                        <th style="text-align:left; padding-left:6px;" rowspan="2">Apellidos y Nombres</th>
                        <th colspan="${daysInMonth}">DÍAS DEL MES DE ${monthNames[month].toUpperCase()}</th>
                        <th style="width:24px;" rowspan="2">P</th>
                        <th style="width:24px;" rowspan="2">A</th>
                        <th style="width:24px;" rowspan="2">J</th>
                        <th style="width:24px;" rowspan="2">T</th>
                        <th style="width:38px;" rowspan="2">% Asist</th>
                    </tr>
                    <tr>
                        ${thDaysHtml}
                    </tr>
                </thead>
                <tbody>
                    ${tbodyRows}
                    <tr style="background:#dcfce7; font-weight:900; font-size:8.5pt;">
                        <td colspan="3" style="text-align:right; padding-right:8px; border:1px solid #0f172a;">TOTAL ASISTENCIAS DIARIAS (P):</td>
                        ${dayPresentTotals.slice(1).map((tot, idx) => {
                            const dObj = new Date(year, month - 1, idx + 1);
                            const isWk = (dObj.getDay() === 0 || dObj.getDay() === 6);
                            return `<td style="text-align:center; border:1px solid #0f172a; ${isWk ? 'background:#cbd5e1;' : ''}">${isWk ? '-' : tot}</td>`;
                        }).join('')}
                        <td style="text-align:center; background:#15803d; color:#fff; border:1px solid #0f172a;">${grandSumP}</td>
                        <td style="text-align:center; background:#b91c1c; color:#fff; border:1px solid #0f172a;">${grandSumA}</td>
                        <td colspan="3" style="text-align:center; background:#0f172a; color:#fff; border:1px solid #0f172a;">${students.length} Alumnos</td>
                    </tr>
                </tbody>
            </table>

            <div class="signatures">
                <div class="sig-box">
                    ${teacherName}<br>
                    Catedrático(a) Titular
                </div>
                <div class="sig-box">
                    Comisión de Asistencia y Disciplina<br>
                    Vo.Bo. Control de Plantel
                </div>
                <div class="sig-box">
                    Licda. Director(a) ENCCO<br>
                    Sello Oficial Institucional
                </div>
            </div>
        </body>
        </html>
    `);
    printWin.document.close();
    setTimeout(() => {
        printWin.focus();
        printWin.print();
    }, 400);
}

function exportAttendanceOfficialExcel() {
    const gradeSelect = document.getElementById('attendanceGradeSelect');
    const monthSelect = document.getElementById('attendanceMonthSelect');
    const courseSelect = document.getElementById('attendanceCourseSelect');

    const gradeCode = gradeSelect ? gradeSelect.value : '';
    const gradeText = gradeSelect && gradeSelect.selectedIndex >= 0 ? gradeSelect.options[gradeSelect.selectedIndex].text : 'Grado';
    const month = parseInt(monthSelect ? monthSelect.value : '8') || 8;
    const courseId = courseSelect ? courseSelect.value : 'GENERAL';
    const year = 2026;
    const daysInMonth = new Date(year, month, 0).getDate();

    const qGradeObj = (STATE.gradesList || []).find(g => g.code === gradeCode || g.id === gradeCode || g.name === gradeCode);
    const rawQ = `${gradeCode || ''} ${qGradeObj ? (qGradeObj.name + ' ' + qGradeObj.section) : ''}`.toUpperCase();
    let qGradeNum = 0;
    if (rawQ.includes('6') || rawQ.includes('SEXTO') || rawQ.includes('6TO')) qGradeNum = 6;
    else if (rawQ.includes('5') || rawQ.includes('QUINTO') || rawQ.includes('5TO')) qGradeNum = 5;
    else if (rawQ.includes('4') || rawQ.includes('CUARTO') || rawQ.includes('4TO')) qGradeNum = 4;
    const qSec = getCleanSectionLetter(qGradeObj ? qGradeObj.section : gradeCode);

    const students = (STATE.students || []).filter(s => {
        if (!isStudentActive(s)) return false;
        const rawS = `${s.grade || ''} ${s.gradeCode || ''} ${s.gradeLabel || ''}`.toUpperCase();
        let sGradeNum = 0;
        if (rawS.includes('6') || rawS.includes('SEXTO') || rawS.includes('6TO')) sGradeNum = 6;
        else if (rawS.includes('5') || rawS.includes('QUINTO') || rawS.includes('5TO')) sGradeNum = 5;
        else if (rawS.includes('4') || rawS.includes('CUARTO') || rawS.includes('4TO')) sGradeNum = 4;
        const sSec = getCleanSectionLetter(s.section || s.gradeCode || s.gradeLabel || rawS);

        return (qGradeNum === sGradeNum) && (qSec === sSec);
    }).sort((a, b) => (a.fullName || (a.lastName + ' ' + a.firstName)).localeCompare(b.fullName || (b.lastName + ' ' + b.firstName)));

    if (students.length === 0) {
        showToast("No hay estudiantes para exportar.", "warning");
        return;
    }

    const recordKey = getAttendanceRecordKey(gradeCode, month, courseId);
    const monthData = (STATE.attendanceRecords && STATE.attendanceRecords[recordKey]) || {};

    let csv = `\uFEFFNo,Codigo_Personal,Apellidos y Nombres,`;
    for (let d = 1; d <= daysInMonth; d++) csv += `Dia_${d},`;
    csv += `Total_P,Total_A,Total_J,Total_T,Porcentaje_Asistencia\n`;

    students.forEach((s, idx) => {
        const sRecords = monthData[s.id] || {};
        let p = 0, a = 0, j = 0, t = 0;
        let line = `${idx + 1},"${s.personalCode || s.cui || s.carne || ''}","${s.fullName || (s.lastName + ', ' + s.firstName)}",`;

        for (let d = 1; d <= daysInMonth; d++) {
            const dObj = new Date(year, month - 1, d);
            const isWeekend = (dObj.getDay() === 0 || dObj.getDay() === 6);
            if (isWeekend) {
                line += `-,`;
            } else {
                let val = sRecords[d] || '';
                if (val === 'P') p++;
                else if (val === 'A') a++;
                else if (val === 'J') j++;
                else if (val === 'T') t++;
                line += `${val},`;
            }
        }
        const tot = p + a + j + t;
        const pct = tot > 0 ? Math.round(((p + j + (t * 0.5)) / tot) * 100) : 100;
        line += `${p},${a},${j},${t},${pct}%\n`;
        csv += line;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `Asistencia_${gradeCode}_Mes_${month}_2026.csv`;
    link.click();
    showToast("Planilla descargada exitosamente en formato CSV / Excel.", "success");
}

function exportAttendanceToCSV() { exportAttendanceOfficialExcel(); }
function printAttendanceExcelSheet() { printAttendanceOfficialSheet(); }

function loadHonorRoll() {
    const select = document.getElementById('honorRollTypeSelect');
    const tbody = document.getElementById('honorRollTableBody');
    const titleText = document.getElementById('honorRollTitleText');
    if (!tbody || !select) return;

    // Poblar el selector dinámicamente con las opciones de Cuadro de Honor
    const curVal = select.value || 'ALL_BALANCED';
    
    let opts = `
        <option value="ALL_BALANCED">🏆 Cuadro de Honor General de Toda la Escuela (Promedio Equilibrado Base 100)</option>
        <option value="GROUP_4TO_5TO">🥈 Cuadro de Honor Oficial: 4to y 5to Grado (9 Clases)</option>
        <option value="GROUP_6TO">🎓 Cuadro de Honor Oficial: 6to Grado (10 Clases - Graduandos)</option>
    `;

    opts += `<optgroup label="📌 Cuadros de Honor por Grado y Sección">`;
    (STATE.gradesList || []).forEach(g => {
        opts += `<option value="GRADE_${g.code}">📘 ${g.name} (${g.section})</option>`;
    });
    opts += `</optgroup>`;

    opts += `<optgroup label="🎓 Cuadros de Honor por Carrera">`;
    (STATE.careers || []).forEach(c => {
        opts += `<option value="CAREER_${c.name}">🏅 Carrera: ${c.name}</option>`;
    });
    opts += `</optgroup>`;

    if (!select.dataset || select.dataset.loaded !== 'true' || (select.options && select.options.length !== (3 + (STATE.gradesList?.length || 0) + (STATE.careers?.length || 0)))) {
        select.innerHTML = opts;
        select.value = curVal;
        if (select.dataset) select.dataset.loaded = 'true';
    }

    const type = select.value;
    const onlyEligible = document.getElementById('honorRollOnlyEligibleCheck') ? document.getElementById('honorRollOnlyEligibleCheck').checked : true;

    let list = (STATE.students || []).filter(s => isStudentActive(s));

    if (type === 'ALL_BALANCED' || type === 'SCHOOL') {
        titleText.textContent = `CUADRO DE HONOR GENERAL - TODA LA ESCUELA (CICLO ${STATE.activeCycle || '2026'})`;
    } else if (type === 'GROUP_4TO_5TO') {
        titleText.textContent = `CUADRO DE HONOR OFICIAL - 4TO Y 5TO GRADO (9 CLASES) - CICLO ${STATE.activeCycle || '2026'}`;
        list = list.filter(s => {
            const info = getStudentAcademicInfo(s);
            return info.is4to || info.is5to;
        });
    } else if (type === 'GROUP_6TO') {
        titleText.textContent = `CUADRO DE HONOR OFICIAL - 6TO GRADO GRADUANDOS (10 CLASES) - CICLO ${STATE.activeCycle || '2026'}`;
        list = list.filter(s => {
            const info = getStudentAcademicInfo(s);
            return info.is6to;
        });
    } else if (type.startsWith('GRADE_')) {
        const gCode = type.replace('GRADE_', '');
        const gradeObj = (STATE.gradesList || []).find(x => x.code === gCode);
        const gName = gradeObj ? `${gradeObj.name} (${gradeObj.section})` : gCode;
        titleText.textContent = `CUADRO DE HONOR - ${gName}`;
        list = list.filter(s => s.grade === gCode || s.gradeLabel?.includes(gradeObj?.name));
    } else if (type.startsWith('CAREER_')) {
        const cName = type.replace('CAREER_', '');
        titleText.textContent = `CUADRO DE HONOR - CARRERA: ${cName}`;
        const matchingGrades = (STATE.gradesList || []).filter(g => g.career === cName).map(g => g.code);
        list = list.filter(s => matchingGrades.includes(s.grade));
    }

    // Filtrar estrictamente solo estudiantes con calificaciones ingresadas y elegibles
    const evaluatedList = list.filter(s => {
        const info = getStudentAcademicInfo(s);
        if (onlyEligible) {
            return info.eligibleForHonorRoll && info.gradedClasses > 0 && info.average > 0;
        }
        return info.gradedClasses > 0 && info.average > 0;
    });

    if (evaluatedList.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="8" style="text-align:center; padding:45px 20px; color:var(--text-muted);">
                    <i class="fa-solid fa-trophy" style="font-size:2.4rem; margin-bottom:12px; display:block; color:var(--brand-green); opacity:0.8;"></i>
                    <strong style="font-size:1.1rem; color:var(--text-primary); display:block; margin-bottom:6px;">Aún no hay calificaciones ingresadas en el sistema</strong>
                    <span style="font-size:0.88rem; max-width:550px; display:inline-block; line-height:1.4;">
                        El Cuadro de Honor se calculará y nivelará automáticamente en tiempo real (Base 100 equilibrada) en cuanto los catedráticos ingresen las calificaciones bimestrales de sus asignaturas.
                    </span>
                </td>
            </tr>
        `;
        return;
    }

    // Ordenamiento estricto: primero los elegibles por promedio descendente, luego no elegibles
    evaluatedList.sort((a, b) => {
        const infoA = getStudentAcademicInfo(a);
        const infoB = getStudentAcademicInfo(b);
        if (infoA.eligibleForHonorRoll !== infoB.eligibleForHonorRoll) {
            return infoA.eligibleForHonorRoll ? -1 : 1;
        }
        return infoB.average - infoA.average;
    });

    tbody.innerHTML = evaluatedList.map((s, idx) => {
        const info = getStudentAcademicInfo(s);
        let badgeHtml = '';
        let posBadge = `<span style="font-weight:800; font-size:1.05rem;">#${idx + 1}</span>`;

        if (!info.eligibleForHonorRoll) {
            posBadge = `<span class="badge" style="background:#fee2e2; color:#b91c1c; font-size:0.75rem;"><i class="fa-solid fa-ban"></i> No Elegible</span>`;
            if (info.isExonerated) {
                badgeHtml = `<span class="badge" style="background:#ccfbf1; color:#0f766e; border:1px solid #5eead4; font-weight:700;"><i class="fa-solid fa-user-shield"></i> Exonerado (Sin Cuadro)</span>`;
            } else {
                badgeHtml = `<span class="badge" style="background:#fee2e2; color:#b91c1c; border:1px solid #f87171; font-weight:700;" title="Materias reprobadas: ${info.failedSubjectsList.join(', ')}"><i class="fa-solid fa-triangle-exclamation"></i> Nota &lt; 60 pts (${info.failedSubjectsList.length})</span>`;
            }
        } else {
            if (idx === 0) {
                posBadge = `<span style="font-size:1.15rem;">🥇 <strong>#1</strong></span>`;
                badgeHtml = `<span class="badge" style="background:#fef08a; color:#854d0e; border:1px solid #eab308; font-weight:800;"><i class="fa-solid fa-medal"></i> 1er Lugar - Oro</span>`;
            } else if (idx === 1) {
                posBadge = `<span style="font-size:1.1rem;">🥈 <strong>#2</strong></span>`;
                badgeHtml = `<span class="badge" style="background:#f1f5f9; color:#334155; border:1px solid #94a3b8; font-weight:800;"><i class="fa-solid fa-medal"></i> 2do Lugar - Plata</span>`;
            } else if (idx === 2) {
                posBadge = `<span style="font-size:1.1rem;">🥉 <strong>#3</strong></span>`;
                badgeHtml = `<span class="badge" style="background:#ffedd5; color:#9a3412; border:1px solid #f97316; font-weight:800;"><i class="fa-solid fa-medal"></i> 3er Lugar - Bronce</span>`;
            } else if (idx < 10) {
                badgeHtml = `<span class="badge badge-success" style="font-weight:700;"><i class="fa-solid fa-star"></i> Cuadro de Honor</span>`;
            } else {
                badgeHtml = `<span class="badge badge-info"><i class="fa-solid fa-award"></i> Alto Rendimiento</span>`;
            }
        }

        const loadBadge = info.is6to 
            ? `<span class="badge" style="background:#fef3c7; color:#92400e; font-weight:700; border:1px solid #fde68a;">10 Clases (6to)</span>`
            : `<span class="badge" style="background:#e0f2fe; color:#0369a1; font-weight:700; border:1px solid #bae6fd;">9 Clases (4to/5to)</span>`;

        let exonBadges = '';
        if (info.exoneratedCount > 0) {
            exonBadges = `<span class="badge" style="background:#ccfbf1; color:#0f766e; border:1px solid #5eead4; font-size:0.75rem; margin-right:4px;" title="Tiene ${info.exoneratedCount} consideración(es) o exoneración(es)"><i class="fa-solid fa-user-shield"></i> Exonerado</span>`;
        }

        const actionBtn = `<button type="button" class="btn btn-sm btn-outline-primary" style="padding:2px 8px; font-size:0.75rem;" onclick="openAcademicExonerationModal('${s.id}')" title="Configurar consideración individual o exoneración"><i class="fa-solid fa-user-shield"></i> Exonerar</button>`;

        return `
            <tr style="${!info.eligibleForHonorRoll ? 'background:#fff1f2; opacity:0.92;' : ''}">
                <td style="text-align:center;">${posBadge}</td>
                <td style="text-align:center;"><code>${s.personalCode || '—'}</code></td>
                <td><strong>${(s.lastName || '').toUpperCase()}, ${(s.firstName || '').toUpperCase()}</strong></td>
                <td>${formatStudentGradeAndSection(s)}</td>
                <td style="text-align:center;">${loadBadge}</td>
                <td style="text-align:center;">
                    <strong style="color:${info.eligibleForHonorRoll ? 'var(--brand-green)' : '#b91c1c'}; font-size:1.15rem;">${info.average.toFixed(2)} pts</strong>
                    <div style="font-size:0.72rem; color:var(--text-muted);">Total: ${info.totalPoints}/${info.officialClassLoad * 100} pts</div>
                </td>
                <td style="text-align:center;">${badgeHtml}</td>
                <td style="text-align:center; white-space:nowrap;">
                    ${exonBadges}
                    ${actionBtn}
                </td>
            </tr>
        `;
    }).join('');
}


function printHonorRoll() {
    const h = STATE.schoolHeader || getInitialData().schoolHeader;
    const select = document.getElementById('honorRollTypeSelect');
    const titleText = document.getElementById('honorRollTitleText')?.textContent || 'CUADRO DE HONOR OFICIAL';
    if (!select) return;

    const type = select.value;
    let list = (STATE.students || []).filter(s => isStudentActive(s));

    if (type === 'GROUP_4TO_5TO') {
        list = list.filter(s => {
            const info = getStudentAcademicInfo(s);
            return info.is4to || info.is5to;
        });
    } else if (type === 'GROUP_6TO') {
        list = list.filter(s => {
            const info = getStudentAcademicInfo(s);
            return info.is6to;
        });
    } else if (type.startsWith('GRADE_')) {
        const gCode = type.replace('GRADE_', '');
        const gradeObj = (STATE.gradesList || []).find(x => x.code === gCode);
        list = list.filter(s => s.grade === gCode || s.gradeLabel?.includes(gradeObj?.name));
    } else if (type.startsWith('CAREER_')) {
        const cName = type.replace('CAREER_', '');
        const matchingGrades = (STATE.gradesList || []).filter(g => g.career === cName).map(g => g.code);
        list = list.filter(s => matchingGrades.includes(s.grade));
    }

    // Filtrar estrictamente solo estudiantes elegibles (sin materias reprobadas < 60 pts)
    list = list.filter(s => getStudentAcademicInfo(s).eligibleForHonorRoll);
    list.sort((a, b) => getStudentAcademicInfo(b).average - getStudentAcademicInfo(a).average);

    if (list.length === 0) {
        showToast("No hay estudiantes elegibles para imprimir en el Cuadro de Honor seleccionado.", "warning");
        return;
    }

    const printRowsHtml = list.map((s, idx) => {
        const info = getStudentAcademicInfo(s);
        let dist = 'Cuadro de Honor';
        if (idx === 0) dist = '1er Lugar - Medalla de Oro 🥇';
        else if (idx === 1) dist = '2do Lugar - Medalla de Plata 🥈';
        else if (idx === 2) dist = '3er Lugar - Medalla de Bronce 🥉';
        else if (idx >= 10) dist = 'Alto Rendimiento Académico';

        const loadBadge = info.is6to ? '10 Clases (6to)' : '9 Clases (4to/5to)';

        return `
            <tr>
                <td style="text-align:center; font-weight:bold;">#${idx + 1}</td>
                <td style="text-align:center;">${s.personalCode || '—'}</td>
                <td style="font-weight:bold; padding-left:8px;">${(s.lastName || '').toUpperCase()}, ${(s.firstName || '').toUpperCase()}</td>
                <td>${formatStudentGradeAndSection(s)}</td>
                <td style="text-align:center;">${loadBadge}</td>
                <td style="text-align:center; font-weight:bold; font-size:11.5px; color:#15803d;">${info.average.toFixed(2)} pts</td>
                <td style="text-align:center; font-weight:bold;">${dist}</td>
            </tr>
        `;
    }).join('');

    const printWin = window.open('', '_blank');
    if (!printWin) {
        showToast("Permita las ventanas emergentes para visualizar e imprimir el cuadro de honor.", "warning");
        return;
    }

    printWin.document.write(`
        <!DOCTYPE html>
        <html lang="es">
        <head>
            <meta charset="UTF-8">
            <title>${titleText} - ENCCO 1970</title>
            <style>
                @page { size: 8.5in 13in portrait; margin: 6mm 6mm; }
                body { font-family: 'Segoe UI', Arial, sans-serif; color: #000; margin: 0; padding: 0; background: #fff; font-size: 11px; width: 100%; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                .encc-official-header { border: 1.5px solid #000; margin-bottom: 0px; background: #ffffff; }
                .encc-top-banner { background-color: #99b958 !important; border-bottom: 1.5px solid #000; display: flex; justify-content: space-between; align-items: center; padding: 4px 12px; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                .encc-top-banner .logo-box { display: flex; align-items: center; gap: 12px; }
                .encc-top-banner img { height: 48px; width: auto; object-fit: contain; }
                .encc-top-banner h1 { margin: 0; font-size: 20px; font-weight: 800; color: #142d14; letter-spacing: 0.3px; }
                .encc-top-banner .bimestre-badge { font-size: 11px; font-weight: 800; color: #142d14; background: #ffffff; padding: 2px 8px; border-radius: 4px; border: 1px solid #142d14; text-transform: uppercase; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                .encc-meta-row { display: flex; justify-content: space-between; align-items: stretch; background: #ffffff; padding: 8px 12px; border-bottom: 1.5px solid #000; }
                .balance-notice-box { background: #f8fafc; border: 1px solid #cbd5e1; padding: 6px 10px; font-size: 9.5px; color: #334155; margin-bottom: 6px; border-radius: 3px; }
                table.honor-table { width: 100%; border-collapse: collapse; font-size: 10.5px; border: 1.5px solid #000; }
                table.honor-table th, table.honor-table td { border: 1px solid #000; padding: 5px 6px; }
                table.honor-table th { font-weight: 800; background-color: #d9e9f9; color: #0f172a; text-align: center; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                .signatures-box { display: flex; justify-content: space-around; margin-top: 35px; text-align: center; }
                .sig-line { width: 220px; border-top: 1.5px solid #000; padding-top: 4px; font-size: 10.5px; }
                .footer-stamp { margin-top: 15px; display: flex; justify-content: space-between; font-size: 9px; color: #475569; }
                @media print { .no-print { display: none; } body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }
            </style>
        </head>
        <body>
            <div class="encc-official-header">
                <div class="encc-top-banner">
                    <div class="logo-box">
                        <img src="logo.png" alt="Escudo Oficial" onerror="this.src='https://ui-avatars.com/api/?name=ENCCO&background=15803d&color=fff'">
                        <h1>${h.schoolName || 'Escuela Nacional de Ciencias Comerciales'}</h1>
                    </div>
                    <div class="bimestre-badge">${STATE.config?.activeBimestre || 2}º Bimestre Activo</div>
                </div>
                <div class="encc-meta-row">
                    <div>
                        <strong style="font-size:13px; color:#15803d;">${titleText}</strong><br>
                        <span style="font-size:11px; color:#475569;">Ciclo Lectivo: ${STATE.activeCycle || '2026'} - Sede Central Jutiapa 1970</span>
                    </div>
                    <div style="text-align:right; font-size:10.5px;">
                        <strong>Fecha de Certificación:</strong> ${new Date().toLocaleDateString('es-GT', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
                    </div>
                </div>
            </div>

            <div class="balance-notice-box">
                ⚖️ <strong>Criterio Oficial de Elegibilidad y Equiparación:</strong> Promedios calculados sobre <strong>Base 100 puntos</strong> para equilibrar la diferencia de carga curricular (4to/5to con 9 asignaturas y 6to con 10 asignaturas). Los estudiantes seleccionados no poseen calificaciones menores a 60 puntos en ningún bimestre evaluado (o cuentan con exoneración académica oficial).
            </div>

            <table class="honor-table">
                <thead>
                    <tr>
                        <th style="width:45px;">Pos.</th>
                        <th style="width:105px;">Código Personal</th>
                        <th style="text-align:left; padding-left:8px;">Nombre del Estudiante</th>
                        <th style="width:170px;">Grado y Carrera</th>
                        <th style="width:95px;">Carga Curricular</th>
                        <th style="width:95px;">Promedio (Base 100)</th>
                        <th style="width:130px;">Distinción Otorgada</th>
                    </tr>
                </thead>
                <tbody>
                    ${printRowsHtml}
                </tbody>
            </table>

            <div class="footer-stamp">
                <span>Excelencia Académica ENCCO Jutiapa - Fundada en 1970</span>
                <span>Generado el: ${new Date().toLocaleDateString('es-GT')}</span>
            </div>
        </body>
        </html>
    `);
    printWin.document.close();
    setTimeout(() => {
        printWin.focus();
        printWin.print();
    }, 300);
}

// ==========================================================================
// 11. LLAMADAS DE ATENCIÓN DISCIPLINARIAS (ADMIN PUEDE ELIMINAR CUALQUIER REPORTE)
// ==========================================================================

// ──────────────────────────────────────────────────────────────────────────
// ⚖️ CONTROLADOR INTEGRAL DE DISCIPLINA, REPORTES DOCENTES Y RESOLUCIONES
// ──────────────────────────────────────────────────────────────────────────

function checkDisciplineCreatePermission() {
    const role = STATE.currentRole || (STATE.currentUser ? STATE.currentUser.role : 'docente');
    // Docentes, auxiliares, directores y administradores pueden ingresar reportes
    return ['admin', 'director', 'secretaria', 'profesor_auxiliar', 'docente'].includes(role);
}
window.checkDisciplineCreatePermission = checkDisciplineCreatePermission;

function checkDisciplineResolvePermission() {
    const role = STATE.currentRole || (STATE.currentUser ? STATE.currentUser.role : 'docente');
    // Auxiliar, director y admin pueden dictaminar y resolver faltas
    return ['admin', 'director', 'profesor_auxiliar'].includes(role);
}
window.checkDisciplineResolvePermission = checkDisciplineResolvePermission;

function checkDisciplineDirectorPermission() {
    const role = STATE.currentRole || (STATE.currentUser ? STATE.currentUser.role : 'docente');
    // Únicamente la Dirección y el Administrador pueden autorizar cambios a resoluciones emitidas o eliminar reportes
    return ['admin', 'director'].includes(role);
}
window.checkDisciplineDirectorPermission = checkDisciplineDirectorPermission;

// ==========================================================================
// ⚠️ GESTOR DINÁMICO DE REPORTES DISCIPLINARIOS Y LLAMADAS DE ATENCIÓN (V75)
// ==========================================================================

function populateDisciplineGradeFilter() {
    const gradeSelect = document.getElementById('discGradeFilter');
    if (!gradeSelect) return;

    const gradesList = Array.isArray(STATE.gradesList) && STATE.gradesList.length > 0 
        ? STATE.gradesList 
        : [
            { code: '4to Perito Contador', name: '4to Perito Contador' },
            { code: '5to Perito Contador', name: '5to Perito Contador' },
            { code: '6to Perito Contador', name: '6to Perito Contador' }
        ];

    const currentVal = gradeSelect.value || 'ALL';
    let optionsHtml = '<option value="ALL">-- Todos los Grados --</option>';
    gradesList.forEach(g => {
        const val = g.name || g.code;
        optionsHtml += `<option value="${val}">${g.name} (${g.code})</option>`;
    });

    gradeSelect.innerHTML = optionsHtml;
    if (gradesList.some(g => (g.name || g.code) === currentVal)) {
        gradeSelect.value = currentVal;
    }
}

function clearDisciplineStudentSearch() {
    const input = document.getElementById('discStudentSearchInput');
    const btn = document.getElementById('discClearSearchBtn');
    if (input) {
        input.value = '';
        input.focus();
    }
    if (btn) btn.style.display = 'none';
    filterDisciplineStudentList();
}

function filterDisciplineStudentList() {
    const gradeFilter = (document.getElementById('discGradeFilter')?.value || 'ALL').trim();
    const sectionFilter = (document.getElementById('discSectionFilter')?.value || 'ALL').trim().toUpperCase();
    const searchInput = document.getElementById('discStudentSearchInput');
    const q = (searchInput?.value || '').trim().toLowerCase();
    const clearBtn = document.getElementById('discClearSearchBtn');
    if (clearBtn) clearBtn.style.display = q ? 'block' : 'none';

    const select = document.getElementById('discStudentSelect');
    const badge = document.getElementById('discStudentCountBadge');
    if (!select) return;

    let students = (STATE.students || []).filter(s => isStudentActive(s));

    // Filtro de grado
    if (gradeFilter && gradeFilter !== 'ALL') {
        const gfLower = gradeFilter.toLowerCase();
        students = students.filter(s => {
            const sg = (s.grade || s.gradeCode || '').toLowerCase();
            return sg === gfLower || sg.includes(gfLower) || gfLower.includes(sg);
        });
    }

    // Filtro de sección
    if (sectionFilter && sectionFilter !== 'ALL') {
        students = students.filter(s => {
            const sec = (s.section || '').toUpperCase().trim();
            return sec === sectionFilter || sec === `SECCIÓN ${sectionFilter}` || sec === `SECCION ${sectionFilter}` || sec.endsWith(sectionFilter);
        });
    }

    // Búsqueda en vivo por nombre, apellido, carné o cui
    if (q) {
        students = students.filter(s => {
            const fullName = `${s.lastName || ''} ${s.firstName || ''} ${s.name || ''}`.toLowerCase();
            const carne = (s.carne || '').toLowerCase();
            const cui = (s.cui || '').toLowerCase();
            return fullName.includes(q) || carne.includes(q) || cui.includes(q);
        });
    }

    // Ordenar alfabéticamente por apellidos
    students.sort((a, b) => (a.lastName || a.name || '').localeCompare(b.lastName || b.name || ''));

    if (badge) {
        badge.textContent = `${students.length} alumno(s) encontrado(s)`;
        badge.style.background = students.length > 0 ? '#e0f2fe' : '#fee2e2';
        badge.style.color = students.length > 0 ? '#0369a1' : '#dc2626';
    }

    if (students.length === 0) {
        select.innerHTML = '<option value="">⚠️ No hay estudiantes con este filtro</option>';
        select.disabled = true;
    } else {
        select.disabled = false;
        select.innerHTML = `<option value="">-- Seleccione Estudiante (${students.length} disponibles) --</option>` + students.map(s => {
            const fullName = `${s.lastName || ''}, ${s.firstName || ''}`.trim() || s.name || 'Estudiante';
            const gradeDisplay = s.grade || s.gradeCode || 'Grado Oficial';
            const secDisplay = (s.section || 'A').replace(/secci[oó]n\s*/i, '');
            return `<option value="${s.id}">${fullName} • [${gradeDisplay} - Sec ${secDisplay}] (Carné: ${s.carne || 'S/C'})</option>`;
        }).join('');

        // Si solo hay un estudiante tras la búsqueda, seleccionarlo automáticamente
        if (students.length === 1 && q) {
            select.value = students[0].id;
        }
    }
}

function openDisciplineModal() {
    if (!checkDisciplineCreatePermission()) {
        showToast('No tiene permisos para registrar reportes disciplinarios.', 'warning');
        return;
    }

    const form = document.querySelector('#disciplineModal form');
    if (form) form.reset();

    // 1. Poblar y reiniciar filtros dinámicos
    populateDisciplineGradeFilter();
    const gradeSelect = document.getElementById('discGradeFilter');
    const secSelect = document.getElementById('discSectionFilter');
    const searchInput = document.getElementById('discStudentSearchInput');

    if (gradeSelect) gradeSelect.value = 'ALL';
    if (secSelect) secSelect.value = 'ALL';
    if (searchInput) searchInput.value = '';

    // 2. Filtrar lista de estudiantes
    filterDisciplineStudentList();

    // 3. Fecha actual por defecto si existe campo
    const dateInput = document.getElementById('discDate');
    if (dateInput) {
        dateInput.value = new Date().toISOString().split('T')[0];
    }

    showModalById('disciplineModal');
}

function closeDisciplineModal() {
    const modal = document.getElementById('disciplineModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

function openDisciplineModalForStudent(studentId) {
    if (!studentId) studentId = STATE.selectedStudentId;
    closeStudentProfileModal();
    openDisciplineModal();
    
    if (studentId) {
        const s = (STATE.students || []).find(x => x.id === studentId);
        if (s) {
            const gradeSelect = document.getElementById('discGradeFilter');
            const secSelect = document.getElementById('discSectionFilter');
            if (gradeSelect && s.grade) {
                // Ajustar al grado del alumno
                Array.from(gradeSelect.options).forEach(opt => {
                    if (opt.value && s.grade.toLowerCase().includes(opt.value.toLowerCase())) {
                        gradeSelect.value = opt.value;
                    }
                });
            }
            if (secSelect && s.section) {
                const cleanSec = s.section.replace(/secci[oó]n\s*/i, '').trim().toUpperCase();
                secSelect.value = cleanSec || 'ALL';
            }
            filterDisciplineStudentList();
        }

        setTimeout(() => {
            const studentSelect = document.getElementById('discStudentSelect');
            if (studentSelect && studentId) {
                studentSelect.value = studentId;
            }
        }, 100);
    }
}



function closeDisciplineResolutionModal() {
    const modal = document.getElementById('disciplineResolutionModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}
window.closeDisciplineResolutionModal = closeDisciplineResolutionModal;

function saveDisciplineForm(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (!checkDisciplineCreatePermission()) {
        showToast('No tiene permisos para registrar reportes disciplinarios.', 'warning');
        return;
    }

    const stuSelect = document.getElementById('discStudentSelect');
    const stuId = stuSelect ? stuSelect.value : '';
    const student = (STATE.students || []).find(s => s.id === stuId);

    const severityInput = document.getElementById('discSeverity');
    const severity = severityInput ? severityInput.value : 'Leve';

    const reasonInput = document.getElementById('discReason');
    const reason = reasonInput ? reasonInput.value.trim() : '';

    const dateInput = document.getElementById('discDate');
    const date = (dateInput && dateInput.value) ? dateInput.value : new Date().toISOString().split('T')[0];

    if (!stuId || !reason) {
        showToast('Seleccione un estudiante e ingrese el motivo del reporte disciplinario.', 'warning');
        return;
    }

    const stuName = student ? (student.name || `${student.firstName || ''} ${student.lastName || ''}`.trim()) : 'Estudiante';
    const grade = student ? (student.grade || student.gradeCode || 'Perito Contador') : '4to Perito Contador';
    const section = student ? (student.section || 'Sección A') : 'Sección A';
    const teacherName = STATE.currentUser ? (STATE.currentUser.name || STATE.currentUser.username) : 'Docente Catedrático';

    if (!Array.isArray(STATE.disciplineReports)) STATE.disciplineReports = [];

    const newReport = {
        id: 'rep-disc-' + Date.now(),
        studentId: stuId,
        studentName: stuName,
        grade: `${grade} (${section})`,
        teacher: teacherName,
        teacherId: STATE.currentUser ? STATE.currentUser.id : '',
        date: date,
        severity: severity,
        reason: reason,
        status: 'Pendiente',
        actionType: 'Pendiente de Resolución por Auxiliatura',
        resolution: '',
        resolvedBy: '',
        resolvedDate: '',
        isLocked: false,
        lockedForTeacher: true
    };

    STATE.disciplineReports.unshift(newReport);
    saveStateToLocalStorage();
    closeDisciplineModal();
    renderDisciplineTable();
    if (typeof renderDashboard === 'function') renderDashboard();
    showToast(`Reporte disciplinario registrado correctamente. Ha sido canalizado al Profesor Auxiliar para su resolución y dictamen.`, 'success');
}
window.saveDisciplineForm = saveDisciplineForm;

function openDisciplineResolutionModal(reportId) {
    const list = STATE.disciplineReports || STATE.discipline || [];
    const rep = list.find(r => r.id === reportId);
    if (!rep) {
        showToast('Reporte disciplinario no encontrado.', 'warning');
        return;
    }

    const currentRole = STATE.currentRole || (STATE.currentUser ? STATE.currentUser.role : 'docente');
    const isDirector = checkDisciplineDirectorPermission();
    const isAuxiliar = currentRole === 'profesor_auxiliar';
    const isDocente = currentRole === 'docente' || (!isDirector && !isAuxiliar);

    const idInput = document.getElementById('discResModalReportId');
    const nameEl = document.getElementById('discResModalStudentName');
    const gradeEl = document.getElementById('discResModalStudentGrade');
    const teacherEl = document.getElementById('discResModalTeacher');
    const dateEl = document.getElementById('discResModalDate');
    const reasonEl = document.getElementById('discResModalReason');
    const severityEl = document.getElementById('discResModalSeverity');

    const metaResolvedInfo = document.getElementById('discResMetaResolvedInfo');
    const resolvedByEl = document.getElementById('discResModalResolvedBy');
    const resolvedDateEl = document.getElementById('discResModalResolvedDate');

    const actionSelect = document.getElementById('discResActionType');
    const statusSelect = document.getElementById('discResStatusSelect');
    const resTextarea = document.getElementById('discResResolutionText');
    const submitBtn = document.getElementById('discResSubmitBtn') || document.querySelector('#disciplineResolutionModal button[type="submit"]');
    const unlockBtn = document.getElementById('discResDirectorUnlockBtn');

    if (idInput) idInput.value = rep.id;
    if (nameEl) nameEl.textContent = rep.studentName || 'Estudiante';
    if (gradeEl) gradeEl.textContent = rep.grade || 'Grado no especificado';
    if (teacherEl) teacherEl.textContent = rep.teacher || 'Docente Catedrático';
    if (dateEl) dateEl.textContent = rep.date || 'Fecha actual';
    if (reasonEl) reasonEl.textContent = rep.reason || 'Sin detalles';

    if (severityEl) {
        let badgeColor = '#eab308';
        if (rep.severity === 'Grave') badgeColor = '#ea580c';
        if (rep.severity === 'Muy Grave') badgeColor = '#dc2626';
        severityEl.innerHTML = `<span class="badge" style="background:${badgeColor}; color:#fff; font-weight:700;">Falta ${rep.severity || 'Leve'}</span>`;
    }

    // Información de auditoría de resolución
    if (metaResolvedInfo) {
        if (rep.resolvedBy || rep.resolution) {
            metaResolvedInfo.style.display = 'block';
            if (resolvedByEl) resolvedByEl.textContent = rep.resolvedBy || 'Profesor Auxiliar / Dirección';
            if (resolvedDateEl) resolvedDateEl.textContent = rep.resolvedDate || rep.date || 'Fecha registrada';
        } else {
            metaResolvedInfo.style.display = 'none';
        }
    }

    // Valores en el formulario
    if (actionSelect) {
        actionSelect.value = rep.actionType || 'Citación de Padres de Familia';
    }
    if (statusSelect) {
        statusSelect.value = rep.status || rep.resolutionStatus || 'Pendiente';
    }
    if (resTextarea) {
        resTextarea.value = rep.resolution || rep.resolutionText || '';
    }

    // Banner informativo de seguridad según el rol
    let securityBanner = document.getElementById('discResSecurityBanner');
    if (!securityBanner) {
        const bodyEl = document.querySelector('#disciplineResolutionModal .modal-body');
        if (bodyEl) {
            securityBanner = document.createElement('div');
            securityBanner.id = 'discResSecurityBanner';
            securityBanner.style.cssText = 'padding:10px 14px; border-radius:8px; margin-bottom:14px; font-size:0.83rem; font-weight:600; display:flex; align-items:center; gap:10px; line-height:1.4;';
            bodyEl.insertBefore(securityBanner, bodyEl.firstChild);
        }
    }

    const isResolvedAndLocked = (rep.status === 'Resuelto' || rep.isLocked === true) && Boolean(rep.resolution);

    // GESTIÓN DE PRIVILEGIOS Y ESTADOS
    if (isDocente) {
        // --- 1. DOCENTE: Consulta de solo lectura sin posibilidad de modificar ---
        if (securityBanner) {
            securityBanner.style.background = '#eff6ff';
            securityBanner.style.border = '1px solid #bfdbfe';
            securityBanner.style.color = '#1e40af';
            securityBanner.innerHTML = '<i class="fa-solid fa-lock" style="font-size:1.1rem; color:#2563eb;"></i> <span><strong>Consulta de Dictamen Oficial:</strong> Como catedrático puede revisar la resolución y medidas disciplinarias aplicadas. Por normativa institucional, los dictámenes no pueden ser modificados por docentes.</span>';
        }
        if (actionSelect) { actionSelect.disabled = true; actionSelect.style.backgroundColor = '#f8fafc'; }
        if (statusSelect) { statusSelect.disabled = true; statusSelect.style.backgroundColor = '#f8fafc'; }
        if (resTextarea) {
            resTextarea.disabled = true;
            resTextarea.readOnly = true;
            resTextarea.style.backgroundColor = '#f8fafc';
            resTextarea.placeholder = 'En espera de dictamen oficial emitido por Auxiliatura.';
        }
        if (submitBtn) submitBtn.style.display = 'none';
        if (unlockBtn) unlockBtn.style.display = 'none';

    } else if (isAuxiliar) {
        // --- 2. PROFESOR AUXILIAR ---
        if (isResolvedAndLocked) {
            // Caso ya resuelto y cerrado: Bloqueado. Solo Dirección puede modificar
            if (securityBanner) {
                securityBanner.style.background = '#fefce8';
                securityBanner.style.border = '1px solid #fde047';
                securityBanner.style.color = '#854d0e';
                securityBanner.innerHTML = '<i class="fa-solid fa-lock" style="font-size:1.1rem; color:#d97706;"></i> <span><strong>Caso Resuelto y Cerrado:</strong> El dictamen de esta falta disciplinaria ha sido emitido. De acuerdo a la normativa institucional, una vez ingresada la resolución, <u>únicamente la Dirección</u> puede autorizar modificaciones o reaperturas.</span>';
            }
            if (actionSelect) { actionSelect.disabled = true; actionSelect.style.backgroundColor = '#f8fafc'; }
            if (statusSelect) { statusSelect.disabled = true; statusSelect.style.backgroundColor = '#f8fafc'; }
            if (resTextarea) {
                resTextarea.disabled = true;
                resTextarea.readOnly = true;
                resTextarea.style.backgroundColor = '#f8fafc';
            }
            if (submitBtn) submitBtn.style.display = 'none';
            if (unlockBtn) unlockBtn.style.display = 'none';
        } else {
            // Caso pendiente o en proceso: Auxiliar puede dictaminar
            if (securityBanner) {
                securityBanner.style.background = '#f0fdf4';
                securityBanner.style.border = '1px solid #86efac';
                securityBanner.style.color = '#166534';
                securityBanner.innerHTML = '<i class="fa-solid fa-gavel" style="font-size:1.1rem; color:#16a34a;"></i> <span><strong>Dictamen de Auxiliatura:</strong> Seleccione la medida disciplinaria adoptada y detalle la resolución oficial para el estudiante.</span>';
            }
            if (actionSelect) { actionSelect.disabled = false; actionSelect.style.backgroundColor = '#ffffff'; }
            if (statusSelect) { statusSelect.disabled = false; statusSelect.style.backgroundColor = '#ffffff'; }
            if (resTextarea) {
                resTextarea.disabled = false;
                resTextarea.readOnly = false;
                resTextarea.style.backgroundColor = '#ffffff';
                resTextarea.placeholder = 'Detalle el dictamen, compromisos del estudiante y acuerdos con los padres de familia...';
            }
            if (submitBtn) {
                submitBtn.style.display = 'inline-block';
                submitBtn.innerHTML = '<i class="fa-solid fa-check-double"></i> Guardar Dictamen y Notificar';
            }
            if (unlockBtn) unlockBtn.style.display = 'none';
        }

    } else if (isDirector) {
        // --- 3. DIRECCIÓN Y ADMINISTRACIÓN: Máxima autoridad ---
        if (isResolvedAndLocked) {
            // Caso resuelto: Requiere desbloqueo explícito de Dirección para editar
            if (securityBanner) {
                securityBanner.style.background = '#eff6ff';
                securityBanner.style.border = '1px solid #bfdbfe';
                securityBanner.style.color = '#1e40af';
                securityBanner.innerHTML = '<i class="fa-solid fa-user-shield" style="font-size:1.1rem; color:#2563eb;"></i> <span><strong>Control de Dirección:</strong> Este caso se encuentra resuelto. Como Directivo del establecimiento, usted tiene la facultad exclusiva de autorizar modificaciones o reclasificaciones a este dictamen.</span>';
            }
            if (actionSelect) { actionSelect.disabled = true; actionSelect.style.backgroundColor = '#f8fafc'; }
            if (statusSelect) { statusSelect.disabled = true; statusSelect.style.backgroundColor = '#f8fafc'; }
            if (resTextarea) {
                resTextarea.disabled = true;
                resTextarea.readOnly = true;
                resTextarea.style.backgroundColor = '#f8fafc';
            }
            if (submitBtn) submitBtn.style.display = 'none';
            if (unlockBtn) {
                unlockBtn.style.display = 'inline-block';
                unlockBtn.innerHTML = '<i class="fa-solid fa-unlock-keyhole"></i> Permitir Modificación (Dirección)';
            }
        } else {
            // Caso pendiente: Directivo puede resolver directamente
            if (securityBanner) {
                securityBanner.style.background = '#f0fdf4';
                securityBanner.style.border = '1px solid #86efac';
                securityBanner.style.color = '#166534';
                securityBanner.innerHTML = '<i class="fa-solid fa-user-shield" style="font-size:1.1rem; color:#16a34a;"></i> <span><strong>Gestión de Dirección:</strong> Puede emitir o registrar el dictamen directamente.</span>';
            }
            if (actionSelect) { actionSelect.disabled = false; actionSelect.style.backgroundColor = '#ffffff'; }
            if (statusSelect) { statusSelect.disabled = false; statusSelect.style.backgroundColor = '#ffffff'; }
            if (resTextarea) {
                resTextarea.disabled = false;
                resTextarea.readOnly = false;
                resTextarea.style.backgroundColor = '#ffffff';
            }
            if (submitBtn) {
                submitBtn.style.display = 'inline-block';
                submitBtn.innerHTML = '<i class="fa-solid fa-check-double"></i> Guardar Resolución';
            }
            if (unlockBtn) unlockBtn.style.display = 'none';
        }
    }

    showModalById('disciplineResolutionModal');
}
window.openDisciplineResolutionModal = openDisciplineResolutionModal;

function enableDisciplineDirectorEdit() {
    if (!checkDisciplineDirectorPermission()) {
        showToast('Acceso denegado: Únicamente la Dirección puede autorizar modificaciones a dictámenes emitidos.', 'danger');
        return;
    }

    const actionSelect = document.getElementById('discResActionType');
    const statusSelect = document.getElementById('discResStatusSelect');
    const resTextarea = document.getElementById('discResResolutionText');
    const submitBtn = document.getElementById('discResSubmitBtn') || document.querySelector('#disciplineResolutionModal button[type="submit"]');
    const unlockBtn = document.getElementById('discResDirectorUnlockBtn');
    const securityBanner = document.getElementById('discResSecurityBanner');

    if (actionSelect) { actionSelect.disabled = false; actionSelect.style.backgroundColor = '#ffffff'; }
    if (statusSelect) { statusSelect.disabled = false; statusSelect.style.backgroundColor = '#ffffff'; }
    if (resTextarea) {
        resTextarea.disabled = false;
        resTextarea.readOnly = false;
        resTextarea.style.backgroundColor = '#ffffff';
        resTextarea.focus();
    }
    if (submitBtn) {
        submitBtn.style.display = 'inline-block';
        submitBtn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Guardar Cambios Autorizados';
    }
    if (unlockBtn) unlockBtn.style.display = 'none';

    if (securityBanner) {
        securityBanner.style.background = '#fffbeb';
        securityBanner.style.border = '1px solid #fde68a';
        securityBanner.style.color = '#b45309';
        securityBanner.innerHTML = '<i class="fa-solid fa-unlock-keyhole" style="font-size:1.1rem; color:#d97706;"></i> <span><strong>Edición Autorizada por Dirección:</strong> Modificación habilitada. Puede actualizar las medidas disciplinarias, el dictamen oficial o el estado del expediente.</span>';
    }

    showToast('Modificación autorizada por Dirección. Campos habilitados para edición.', 'info');
}
window.enableDisciplineDirectorEdit = enableDisciplineDirectorEdit;

function saveDisciplineResolutionForm(e) {
    if (e && e.preventDefault) e.preventDefault();

    const currentRole = STATE.currentRole || (STATE.currentUser ? STATE.currentUser.role : 'docente');
    const isDirector = checkDisciplineDirectorPermission();
    const isAuxiliar = currentRole === 'profesor_auxiliar';

    // 1. Docentes NUNCA pueden guardar ni modificar resoluciones
    if (!checkDisciplineResolvePermission() || (!isDirector && !isAuxiliar)) {
        showToast('Acceso denegado: Los docentes no tienen facultades para dictaminar ni modificar resoluciones disciplinarias.', 'danger');
        return;
    }

    const idInput = document.getElementById('discResModalReportId');
    const statusSelect = document.getElementById('discResStatusSelect');
    const actionSelect = document.getElementById('discResActionType');
    const resTextarea = document.getElementById('discResResolutionText');

    const reportId = idInput ? idInput.value : '';
    const status = statusSelect ? statusSelect.value : 'Resuelto';
    const actionType = actionSelect ? actionSelect.value : 'Citación de Padres de Familia';
    const resolutionText = resTextarea ? resTextarea.value.trim() : '';

    if (!resolutionText) {
        showToast('Debe ingresar el dictamen o resolución oficial de la falta disciplinaria.', 'warning');
        return;
    }

    let list = STATE.disciplineReports || STATE.discipline || [];
    const rep = list.find(r => r.id === reportId);
    if (!rep) {
        showToast('Reporte disciplinario no encontrado.', 'warning');
        return;
    }

    // 2. Profesor Auxiliar solo puede dictaminar si NO estaba resuelto previamente (a menos que Dirección lo autorice)
    if (isAuxiliar && rep.status === 'Resuelto' && rep.isLocked === true) {
        showToast('Este caso ya fue resuelto y cerrado. Solo la Dirección del establecimiento puede autorizar modificaciones.', 'danger');
        return;
    }

    const userName = STATE.currentUser ? (STATE.currentUser.name || STATE.currentUser.username) : (isDirector ? 'Dirección' : 'Profesor Auxiliar');
    const roleLabel = isDirector ? 'Dirección' : 'Profesor Auxiliar';

    rep.status = status;
    rep.resolutionStatus = status;
    rep.actionType = actionType;
    rep.resolution = resolutionText;
    rep.resolutionText = resolutionText;
    rep.resolvedBy = `${userName} (${roleLabel})`;
    rep.resolvedDate = new Date().toISOString().split('T')[0];
    if (status === 'Resuelto') {
        rep.isLocked = true;
    } else {
        rep.isLocked = false;
    }

    saveStateToLocalStorage();
    closeDisciplineResolutionModal();
    renderDisciplineTable();
    if (typeof renderDashboard === 'function') renderDashboard();
    
    if (isDirector) {
        showToast(`Resolución actualizada y validada con éxito por la Dirección.`, 'success');
    } else {
        showToast(`Dictamen emitido y guardado exitosamente por Auxiliatura. Visible para el docente en modo consulta.`, 'success');
    }
}
window.saveDisciplineResolutionForm = saveDisciplineResolutionForm;

function deleteDisciplineReport(reportId) {
    if (!checkDisciplineDirectorPermission()) {
        showToast("Acceso denegado: Únicamente la Dirección o Administrador del establecimiento pueden eliminar reportes disciplinarios.", "danger");
        return;
    }
    if (confirm("¿Está seguro de eliminar este reporte disciplinario del sistema? Esta acción es irreversible y solo puede ser autorizada por Dirección.")) {
        STATE.disciplineReports = (STATE.disciplineReports || []).filter(d => d.id !== reportId);
        saveStateToLocalStorage();
        renderDisciplineTable();
        if (typeof renderDashboard === 'function') renderDashboard();
        showToast("Reporte disciplinario eliminado por Dirección.", "info");
    }
}
window.deleteDisciplineReport = deleteDisciplineReport;

function renderDisciplineTable() {
    const tbody = document.getElementById('disciplineTableBody');
    if (!tbody) return;

    let list = STATE.disciplineReports || [];
    const currentRole = STATE.currentRole || (STATE.currentUser ? STATE.currentUser.role : 'docente');
    const isDirector = checkDisciplineDirectorPermission();
    const isAuxiliar = currentRole === 'profesor_auxiliar';
    const isDocente = currentRole === 'docente' || (!isDirector && !isAuxiliar);

    if (list.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="8" style="text-align:center; padding:35px; color:var(--text-muted);">
                    <i class="fa-solid fa-shield-halved" style="font-size:2.2rem; margin-bottom:10px; display:block; color:var(--brand-green);"></i>
                    <strong>No hay reportes disciplinarios registrados.</strong><br>
                    <span style="font-size:0.85rem;">Los catedráticos y personal del plantel pueden registrar incidencias con el botón <strong>"Nueva Llamada de Atención"</strong>.</span>
                </td>
            </tr>
        `;
        return;
    }

    tbody.innerHTML = list.map(d => {
        // Formatear badge de estado
        let statusBadge = '';
        if (d.status === 'Resuelto') {
            statusBadge = '<span class="badge" style="background:#15803d; color:#fff; font-weight:700;"><i class="fa-solid fa-circle-check"></i> Resuelto</span>';
        } else if (d.status === 'En Proceso') {
            statusBadge = '<span class="badge" style="background:#0284c7; color:#fff; font-weight:700;"><i class="fa-solid fa-spinner"></i> En Proceso</span>';
        } else {
            statusBadge = '<span class="badge" style="background:#d97706; color:#fff; font-weight:700;"><i class="fa-solid fa-clock"></i> Pendiente Auxiliar</span>';
        }

        // Formatear badge de severidad
        let sevColor = '#eab308';
        if (d.severity === 'Grave') sevColor = '#ea580c';
        if (d.severity === 'Muy Grave') sevColor = '#dc2626';
        const sevBadge = `<span class="badge" style="background:${sevColor}; color:#fff; font-weight:700;">${d.severity || 'Leve'}</span>`;

        // Vista previa de la resolución del maestro auxiliar o dirección
        let resSnippet = '';
        if (d.resolution) {
            resSnippet = `
                <div style="font-size:0.82rem; color:#15803d; font-weight:600; margin-top:3px;">
                    <i class="fa-solid fa-gavel"></i> <strong>Dictamen:</strong> ${d.actionType || 'Medida aplicada'}
                </div>
            `;
        } else {
            resSnippet = `<div style="font-size:0.8rem; color:#94a3b8; font-style:italic; margin-top:2px;">En espera de resolución del Profesor Auxiliar</div>`;
        }

        // Acciones según rol del usuario
        let actionButtonsHtml = '';
        if (isDocente) {
            // Catedrático: Solo puede consultar la resolución sin modificarla
            if (d.resolution) {
                actionButtonsHtml = `
                    <button type="button" class="btn btn-sm btn-outline-info" onclick="openDisciplineResolutionModal('${d.id}')" title="Consultar dictamen oficial (Solo Lectura)" style="padding:4px 9px; font-weight:700;">
                        <i class="fa-solid fa-eye"></i> Ver Dictamen
                    </button>
                `;
            } else {
                actionButtonsHtml = `
                    <button type="button" class="btn btn-sm btn-outline-secondary" onclick="openDisciplineResolutionModal('${d.id}')" title="Ver reporte disciplinario (Pendiente de dictamen)" style="padding:4px 9px; font-weight:600;">
                        <i class="fa-solid fa-clock"></i> Pendiente Auxiliar
                    </button>
                `;
            }
        } else if (isAuxiliar) {
            // Profesor Auxiliar: Puede resolver reportes pendientes. Una vez resuelto, queda en solo lectura
            if (d.status === 'Resuelto') {
                actionButtonsHtml = `
                    <button type="button" class="btn btn-sm btn-outline-info" onclick="openDisciplineResolutionModal('${d.id}')" title="Ver resolución oficial (Caso cerrado)" style="padding:4px 9px; font-weight:600;">
                        <i class="fa-solid fa-eye"></i> Ver Resolución
                    </button>
                `;
            } else {
                actionButtonsHtml = `
                    <button type="button" class="btn btn-sm btn-primary" onclick="openDisciplineResolutionModal('${d.id}')" title="Emitir dictamen disciplinario oficial" style="padding:4px 9px; font-weight:700; background:#0284c7; border-color:#0284c7;">
                        <i class="fa-solid fa-gavel"></i> Dictaminar
                    </button>
                `;
            }
        } else if (isDirector) {
            // Dirección / Admin: Puede dictaminar, permitir modificaciones y eliminar
            actionButtonsHtml = `
                <button type="button" class="btn btn-sm btn-outline-info" onclick="openDisciplineResolutionModal('${d.id}')" title="${d.resolution ? 'Gestionar o revisar dictamen' : 'Dictaminar reporte'}" style="padding:4px 9px; margin-right:4px; font-weight:700;">
                    <i class="fa-solid ${d.resolution ? 'fa-eye' : 'fa-gavel'}"></i> ${d.resolution ? 'Gestionar Dictamen' : 'Dictaminar'}
                </button>
                <button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteDisciplineReport('${d.id}')" title="Eliminar reporte (Facultad de Dirección)" style="padding:4px 8px;">
                    <i class="fa-solid fa-trash"></i>
                </button>
            `;
        }

        return `
        <tr>
            <td>${d.date || '2026-08-30'}</td>
            <td>
                <strong>${d.studentName || 'Estudiante'}</strong><br>
                <small style="color:var(--text-muted);">${d.grade || '4to Perito'}</small>
            </td>
            <td>
                <span style="font-weight:600; color:var(--text-primary);"><i class="fa-solid fa-user-tie" style="color:var(--brand-green); margin-right:4px;"></i> ${d.teacher || 'Docente'}</span>
            </td>
            <td>${sevBadge}</td>
            <td>
                <div style="font-size:0.88rem; line-height:1.35; max-width:280px;">${d.reason}</div>
                ${resSnippet}
            </td>
            <td style="text-align:center;">${statusBadge}</td>
            <td style="text-align:center; white-space:nowrap;">
                ${actionButtonsHtml}
            </td>
        </tr>
        `;
    }).join('');
}
window.renderDisciplineTable = renderDisciplineTable;


