// ⌨️ LISTENER GLOBAL DE TECLA ESC (ESCAPE): CIERRE DE TODAS LAS MODALES
// ──────────────────────────────────────────────────────────────────────────

function closeAllActiveModals() {
    const closeFns = [
        typeof closeForgotPasswordModal === 'function' ? closeForgotPasswordModal : null,
        typeof closeGradeModal === 'function' ? closeGradeModal : null,
        typeof closeAssignGuideTeacherModal === 'function' ? closeAssignGuideTeacherModal : null,
        typeof closeGradesDirectoryModal === 'function' ? closeGradesDirectoryModal : null,
        typeof closeSectionStudentsModal === 'function' ? closeSectionStudentsModal : null,
        typeof closePensumSubjectModal === 'function' ? closePensumSubjectModal : null,
        typeof closeClassAssignmentModal === 'function' ? closeClassAssignmentModal : null,
        typeof closeGradingConfigModal === 'function' ? closeGradingConfigModal : null,
        typeof closeCareerModal === 'function' ? closeCareerModal : null,
        typeof closeCycleModal === 'function' ? closeCycleModal : null,
        typeof closeCyclePromotionModal === 'function' ? closeCyclePromotionModal : null,
        typeof closeStudentProfileModal === 'function' ? closeStudentProfileModal : null,
        typeof closeAcademicExonerationModal === 'function' ? closeAcademicExonerationModal : null,
        typeof closeDisciplineModal === 'function' ? closeDisciplineModal : null,
        typeof closeUserModal === 'function' ? closeUserModal : null,
        typeof closeDbConfigModal === 'function' ? closeDbConfigModal : null,
        typeof closeNotificationsModal === 'function' ? closeNotificationsModal : null
    ];

    closeFns.forEach(fn => {
        if (fn) {
            try { fn(); } catch (err) {}
        }
    });

    document.querySelectorAll('.modal-overlay').forEach(modal => {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    });
}

window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' || e.key === 'Esc' || e.keyCode === 27) {
        closeAllActiveModals();
    }
});


