function openGradeModal() {
    if (STATE.currentRole === 'docente' || STATE.currentRole === 'estudiante') {
        showToast('Acceso denegado: El personal docente no tiene acceso a crear o modificar grados.', 'warning');
        return;
    }
    if (!checkEnrolmentPermissions()) return;
    const form = document.getElementById('gradeForm');
    if (form) form.reset();
    document.getElementById('gradeModalId').value = '';
    document.getElementById('gradeModalTitle').innerHTML = '<i class="fa-solid fa-graduation-cap"></i> Registrar Nuevo Grado';
    updateCareerSelectOptions();
    showModalById('gradeModal');
}

function closeGradeModal() {
    const modal = document.getElementById('gradeModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}
window.openGradeModal = openGradeModal;
window.closeGradeModal = closeGradeModal;

function saveGradeForm(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById('gradeModalId').value;
    const name = document.getElementById('gradeModalName').value.trim();
    const section = document.getElementById('gradeModalSection').value.trim().toUpperCase();
    const career = document.getElementById('gradeModalCareer').value;
    const code = document.getElementById('gradeModalCode').value.trim() || (name + '_' + section).replace(/\s+/g, '_').toUpperCase();

    if (!name || !section || !career) {
        showToast('Complete todos los campos del grado.', 'warning');
        return;
    }

    if (!Array.isArray(STATE.gradesList)) STATE.gradesList = [];

    if (id) {
        const g = STATE.gradesList.find(x => x.id === id);
        if (g) {
            g.name = name;
            g.section = section;
            g.career = career;
            g.code = code;
        }
    } else {
        STATE.gradesList.push({
            id: 'grd-' + Date.now(),
            name: name,
            section: section,
            career: career,
            code: code,
            guideTeacher: ''
        });
    }

    saveStateToLocalStorage();
    closeGradeModal();
    renderGradesTable();
    updateGradeFilterSelects();
    showToast('Grado guardado exitosamente.', 'success');
}

// Bloque de pensum gestionado por el controlador moderno (ver seccion 31940)

function openAssignGuideTeacherModal(gradeId) {
    if (typeof canRoleModify === 'function' && !canRoleModify('guide-teachers', STATE.currentRole)) {
        showToast('Acceso Restringido: Su rol no tiene autorización para asignar o modificar Maestros Guías.', 'warning');
        return;
    }
    const grade = (STATE.gradesList || []).find(g => g.id === gradeId);
    if (!grade) return;
    const idEl = document.getElementById('guideTeacherModalGradeId') || document.getElementById('quickGuideGradeId');
    if (idEl) idEl.value = grade.id;
    const nameEl = document.getElementById('guideTeacherModalGradeName') || document.getElementById('quickGuideGradeTitle');
    if (nameEl) nameEl.textContent = `${grade.name} (${grade.section}) - ${grade.career}`;
    populateGuideTeacherSelect(grade.guideTeacherId || grade.guideTeacher);
    showModalById('assignGuideTeacherModal');
}
