function openSirePensumImportModal() {
    if (!checkSireImportPermissions()) return;

    SIRE_PARSED_SUBJECTS_BUFFER = [];
    document.getElementById('sirePasteTextarea').value = '';
    const fileIn = document.getElementById('sireFileInput');
    if (fileIn) fileIn.value = '';

    const previewContainer = document.getElementById('sirePreviewContainer');
    if (previewContainer) previewContainer.style.display = 'none';

    const confirmBtn = document.getElementById('sireConfirmImportBtn');
    if (confirmBtn) confirmBtn.disabled = true;

    // Poblar selectores de carrera
    const careerSelect = document.getElementById('sirePasteCareerSelect');
    if (careerSelect) {
        const careers = STATE.careers || [];
        careerSelect.innerHTML = '<option value="AUTO">-- Detectar automáticamente en el texto --</option>' + 
                                careers.map(c => `<option value="${c.name}">${c.name}</option>`).join('');
    }

    switchSireImportTab('paste');
    showModalById('sirePensumImportModal');
}

function closeSirePensumImportModal() {
    const modal = document.getElementById('sirePensumImportModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

function switchSireImportTab(tabName) {
    const tabs = ['paste', 'file', 'cnb'];
    tabs.forEach(t => {
        const btn = document.getElementById('sireTabBtn' + t.charAt(0).toUpperCase() + t.slice(1));
        const content = document.getElementById('sireTabContent' + t.charAt(0).toUpperCase() + t.slice(1));
        if (btn) {
            if (t === tabName) {
                btn.className = 'btn btn-sm btn-primary sire-tab-btn active';
            } else {
                btn.className = 'btn btn-sm btn-secondary sire-tab-btn';
            }
        }
        if (content) {
            content.style.display = (t === tabName) ? 'block' : 'none';
        }
    });
}

function parseSirePastedText() {
    const text = (document.getElementById('sirePasteTextarea')?.value || '').trim();
    if (!text) {
        showToast('Pegue el texto o tabla de materias del SIRE para analizar.', 'warning');
        return;
    }

    const manualCareer = document.getElementById('sirePasteCareerSelect')?.value;
    const manualGrade = document.getElementById('sirePasteGradeSelect')?.value;

    const lines = text.split(/\r?\n/);
    const parsed = [];
    let curCareer = (manualCareer !== 'AUTO' ? manualCareer : (STATE.careers?.[0]?.name || 'Perito Contador'));
    let curGrade = (manualGrade !== 'AUTO' ? manualGrade : '4to Grado');

    const careersList = (STATE.careers || []).map(c => c.name);

    lines.forEach((line, idx) => {
        const clean = line.trim();
        if (!clean) return;

        // Detectar si la línea es encabezado de carrera o grado
        const lower = clean.toLowerCase();
        if (lower.includes('perito contador')) curCareer = 'Perito Contador';
        else if (lower.includes('administración') || lower.includes('administracion')) curCareer = 'Perito en Administración de Empresas';
        else if (lower.includes('bachillerato')) curCareer = 'Bachillerato en Ciencias y Letras';
        else if (lower.includes('secretariado')) curCareer = 'Secretariado Bilingüe';

        if (lower.includes('4to') || lower.includes('cuarto')) curGrade = '4to Grado';
        else if (lower.includes('5to') || lower.includes('quinto')) curGrade = '5to Grado';
        else if (lower.includes('6to') || lower.includes('sexto')) curGrade = '6to Grado';
        else if (lower.includes('1ro') || lower.includes('primero')) curGrade = '1ro Básico';
        else if (lower.includes('2do') || lower.includes('segundo')) curGrade = '2do Básico';
        else if (lower.includes('3ro') || lower.includes('tercero')) curGrade = '3ro Básico';

        // Separar por tabulaciones, pipes | o múltiples espacios
        let parts = clean.split(/\t+|\|/);
        if (parts.length === 1) {
            parts = clean.split(/\s{2,}/);
        }

        let subjectName = '';
        let subjectCode = '';
        let subjectOrder = parsed.length + 1;

        if (parts.length >= 2) {
            // Ejemplo: "01 	 Contabilidad General" o "CONT-01 	 Contabilidad General"
            const first = parts[0].trim();
            const second = parts[1].trim();

            if (/^\d+$/.test(first) || /^[A-Z0-9\-_]+$/i.test(first)) {
                subjectCode = first;
                subjectName = second;
            } else {
                subjectName = first;
            }

            if (parts.length >= 3 && manualGrade === 'AUTO') {
                const gPart = parts[2].trim();
                if (/4to|5to|6to|1ro|2do|3ro/i.test(gPart)) curGrade = gPart;
            }
            if (parts.length >= 4 && manualCareer === 'AUTO') {
                const cPart = parts[3].trim();
                if (cPart) curCareer = cPart;
            }
        } else {
            // Línea simple: eliminar número inicial si existe
            const cleanLine = clean.replace(/^\d+[\.\-\)]\s*/, '');
            if (cleanLine.length > 2 && !cleanLine.toLowerCase().startsWith('pensum') && !cleanLine.toLowerCase().startsWith('carrera')) {
                subjectName = cleanLine;
                subjectCode = String(parsed.length + 1).padStart(3, '0');
            }
        }

        if (subjectName && subjectName.length >= 3) {
            parsed.push({
                id: 'pen-' + Date.now() + '-' + Math.floor(Math.random()*1000) + '-' + parsed.length,
                code: subjectCode || String(parsed.length + 1).padStart(3, '0'),
                name: subjectName,
                grade: (manualGrade !== 'AUTO' ? manualGrade : curGrade),
                career: (manualCareer !== 'AUTO' ? manualCareer : curCareer),
                order: subjectOrder
            });
        }
    });

    if (parsed.length === 0) {
        showToast('No se pudieron reconocer asignaturas en el texto. Verifique el formato.', 'warning');
        return;
    }

    renderSirePreview(parsed);
}

function handleSireFileUpload(e) {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = function(evt) {
        try {
            const data = new Uint8Array(evt.target.result);
            const workbook = XLSX.read(data, { type: 'array' });
            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
            const rows = XLSX.utils.sheet_to_json(firstSheet, { header: 1 });

            if (!rows || rows.length === 0) {
                showToast('El archivo está vacío.', 'warning');
                return;
            }

            const parsed = [];
            let defaultCareer = STATE.careers?.[0]?.name || 'Perito Contador';
            let defaultGrade = '4to Grado';

            // Recorrer filas omitiendo posibles encabezados
            for (let i = 0; i < rows.length; i++) {
                const row = rows[i];
                if (!row || row.length === 0) continue;

                const rowStr = row.join(' ').toLowerCase();
                if (rowStr.includes('código') && rowStr.includes('asignatura')) continue;
                if (rowStr.includes('pensum') && row.length < 3) continue;

                let code = '';
                let name = '';
                let grade = defaultGrade;
                let career = defaultCareer;

                // Mapeo flexible de columnas
                if (row.length >= 2) {
                    code = String(row[0] || '').trim();
                    name = String(row[1] || '').trim();
                    if (row.length >= 3 && row[2]) grade = String(row[2]).trim();
                    if (row.length >= 4 && row[3]) career = String(row[3]).trim();
                } else if (row.length === 1 && String(row[0]).trim().length > 3) {
                    name = String(row[0]).trim();
                    code = String(parsed.length + 1).padStart(3, '0');
                }

                if (name && name.length >= 3) {
                    parsed.push({
                        id: 'pen-xl-' + Date.now() + '-' + parsed.length,
                        code: code || String(parsed.length + 1).padStart(3, '0'),
                        name: name,
                        grade: grade,
                        career: career,
                        order: parsed.length + 1
                    });
                }
            }

            if (parsed.length === 0) {
                showToast('No se encontraron asignaturas válidas en el archivo Excel.', 'warning');
                return;
            }

            renderSirePreview(parsed);
        } catch(err) {
            console.error('Error al procesar archivo Excel:', err);
            showToast('Error al leer el archivo Excel: ' + err.message, 'danger');
        }
    };
    reader.readAsArrayBuffer(file);
}

